defined( 'ABSPATH' ) || exit;

define( 'GOGH_VERSION', '0.99.421' );

/**
 * gogh/section — a first-class block. STATIC save (no render_callback), so
 * pages keep rendering identically if the plugin is ever deactivated.
 */
add_action( 'init', function () {
	wp_register_script(
		'gogh-block',
		plugins_url( 'gogh-block.js', __FILE__ ),
		array( 'wp-blocks', 'wp-element', 'wp-block-editor' ),
		'0.99.421-chrome',
		true
	);
	register_block_type( 'gogh/section', array(
		'editor_script'   => 'gogh-block',
		// SPIKE (attrs-as-truth): v3 sections store { model, cssT } as block
		// attributes and derive presentation here. Legacy (v2) sections carry
		// no attributes and pass through verbatim — fully static, unchanged.
		'render_callback' => 'gogh_render_section',
	) );
} );

/**
 * SPIKE: emit a v3 section. PHP does scoping + emission ONLY — the layout
 * engine stays in the editor; cssT arrives fully compiled with a GOGHSCOPE
 * placeholder.
 *
 * SECURITY: block attributes are writable by users WITHOUT unfiltered_html
 * (KSES does not police attribute JSON), so everything emitted from them is
 * sanitized here: the scope is slug-cast and the CSS may not contain the
 * characters that could open an element or comment. Without this, cssT would
 * be a stored-XSS bypass around KSES.
 */
function gogh_css_from_attrs( $attrs ) {
	if ( empty( $attrs['cssT'] ) || empty( $attrs['scope'] ) ) {
		return '';
	}
	$scope = preg_replace( '/[^a-z0-9-]/', '', (string) $attrs['scope'] );
	if ( '' === $scope ) {
		return '';
	}
	$css = str_replace( 'GOGHSCOPE', $scope, (string) $attrs['cssT'] );
	// CSS never needs these characters; their absence makes markup injection impossible
	return str_replace( array( '<', '>', '\\' ), '', $css );
}

/**
 * When KSES strips a baked <style> TAG it leaves the CSS behind as loose
 * text. Our stylesheets all open with a sentinel comment and never contain
 * '<', so the residue is precisely delimited and safe to sweep.
 */
function gogh_sweep_css_residue( $html ) {
	return preg_replace( '/\/\* generated by gogh \*\/[^<]*/', '', $html );
}

// the Store API (mini-cart, cart, checkout) hands product descriptions to
// an HTML formatter that drops <style> and <script> TAGS and keeps their
// words — '/* generated by gogh */ .gogh-wrap {…' read as prose in James's
// mini-cart. Over the Store API a section renders as plain content.
function gogh_is_store_api() {
	if ( ! ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) {
		return false;
	}
	$route = '';
	if ( isset( $GLOBALS['wp'] ) && isset( $GLOBALS['wp']->query_vars['rest_route'] ) ) {
		$route = (string) $GLOBALS['wp']->query_vars['rest_route'];
	}
	if ( '' === $route && isset( $_SERVER['REQUEST_URI'] ) ) {
		$route = (string) $_SERVER['REQUEST_URI'];
	}
	return false !== strpos( $route, 'wc/store' );
}
function gogh_render_section( $attrs, $content ) {
	$attrs = is_array( $attrs ) ? $attrs : array();
	if ( function_exists( 'gogh_in_collection' ) && gogh_in_collection() ) {
		return ''; // a product grid never carries a product's page
	}
	if ( gogh_is_store_api() ) {
		$plain = preg_replace( '#<(style|script)\b[^>]*>.*?</\1>#is', '', (string) $content );
		return gogh_sweep_css_residue( $plain );
	}
	$css   = gogh_css_from_attrs( $attrs );
	if ( '' === $css ) {
		return $content; // legacy v2: static markup is already complete
	}
	if ( false === strpos( $content, 'class="gogh-style"' ) ) {
		$content = gogh_sweep_css_residue( $content );
		$style   = '<style class="gogh-style">' . $css . '</style>';
		$out     = preg_replace( '/(<div class="wp-block-gogh-section[^"]*">)/', '$1' . $style, $content, 1, $n );
		$content = $n ? $out : $style . $content;
	}
	return gogh_inject_experiences( $attrs, gogh_faq_schema( $attrs ) . $content );
}

/**
 * FAQ sections carry their questions as DATA in the model — so the render
 * can speak schema.org fluently: one FAQPage JSON-LD script per FAQ
 * section, generated fresh on every render (never stored, never kses'd).
 */
function gogh_faq_schema( $attrs ) {
	$els = isset( $attrs['model']['elements'] ) && is_array( $attrs['model']['elements'] )
		? $attrs['model']['elements'] : array();
	$qa = array();
	foreach ( $els as $e ) {
		if ( empty( $e['faq'] ) || ! is_array( $e['faq'] ) ) {
			continue;
		}
		foreach ( $e['faq'] as $item ) {
			if ( empty( $item['q'] ) || empty( $item['a'] ) ) {
				continue;
			}
			$qa[] = array(
				'@type'          => 'Question',
				'name'           => wp_strip_all_tags( $item['q'] ),
				'acceptedAnswer' => array(
					'@type' => 'Answer',
					'text'  => wp_strip_all_tags( $item['a'] ),
				),
			);
		}
	}
	if ( ! $qa ) {
		return '';
	}
	$schema = array(
		'@context'   => 'https://schema.org',
		'@type'      => 'FAQPage',
		'mainEntity' => $qa,
	);
	return '<script type="application/ld+json">' . wp_json_encode( $schema, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) . '</script>';
}

/**
 * Experiences: stored markup carries only a plain link (kses-safe, and the
 * plugin-off fallback). At render time it becomes a sandboxed iframe. The
 * src is NEVER taken from attributes — only the attachment ID is, and the
 * URL is resolved server-side after checking the attachment really is an
 * uploaded text/html file (uploads of which are capability-gated below).
 * allow-scripts WITHOUT allow-same-origin = opaque origin: the uploaded
 * code cannot read cookies or reach the embedding page.
 */
function gogh_inject_experiences( $attrs, $content ) {
	$els = isset( $attrs['model']['elements'] ) && is_array( $attrs['model']['elements'] )
		? $attrs['model']['elements'] : array();
	foreach ( $els as $i => $e ) {
		if ( empty( $e['type'] ) || 'exp' !== $e['type'] || empty( $e['expId'] ) ) {
			continue;
		}
		$id = intval( $e['expId'] );
		if ( $id <= 0 || 'text/html' !== get_post_mime_type( $id ) ) {
			continue;
		}
		$src = wp_get_attachment_url( $id );
		if ( ! $src ) {
			continue;
		}
		$iframe  = '<iframe src="' . esc_url( $src ) . '" sandbox="allow-scripts" title="Interactive experience" loading="lazy" style="width:100%;height:100%;border:0;display:block"></iframe>';
		// the class list gains render-time extras (layout support), so match
		// by our two authored classes rather than the exact attribute value
		$content = preg_replace_callback(
			'/(<div class="[^"]*\bgogh-el-' . ( $i + 1 ) . '\b[^"]*\bgogh-exp\b[^"]*">).*?<\/div>/s',
			function ( $m ) use ( $iframe ) {
				return $m[1] . $iframe . '</div>';
			},
			$content,
			1
		);
	}
	return $content;
}

/**
 * Page styles: a gogh-provided "Blank canvas" template — post content only,
 * no site header or footer. Registered as a plugin block template (WP 6.7+);
 * on older WordPress the option simply doesn't appear.
 */
add_action( 'init', function () {
	if ( ! function_exists( 'register_block_template' ) ) {
		return;
	}
	register_block_template( 'gogh//blank-canvas', array(
		'title'       => __( 'Blank canvas', 'gogh-editor' ),
		'description' => __( 'Just your content, no site header or footer.', 'gogh-editor' ),
		'post_types'  => array( 'page', 'gogh_panel' ),
		'content'     => '<!-- wp:group {"tagName":"main","layout":{"type":"default"},"style":{"spacing":{"blockGap":"0","margin":{"top":"0","bottom":"0"}}}} --><main class="wp-block-group" style="margin-top:0;margin-bottom:0"><!-- wp:post-content /--></main><!-- /wp:group -->',
	) );
} );

/**
 * Gogh's own patterns: a few pattern-directory favourites captured as plugin
 * patterns (they aren't registered locally by any theme), so every theme gets
 * a decent shelf in the section picker.
 */
add_action( 'init', function () {
	$pats = array(
		'fullscreen-cover-image-gallery' => array( __( 'Fullscreen cover image gallery', 'gogh-editor' ), array( 'gallery', 'banner' ) ),
		'fullwidth-headline-right'       => array( __( 'Fullwidth headline and description', 'gogh-editor' ), array( 'banner' ) ),
		'simple-call-to-action'          => array( __( 'Simple call to action', 'gogh-editor' ), array( 'call-to-action' ) ),
		'three-column-pricing-table'     => array( __( 'Three column pricing table', 'gogh-editor' ), array( 'call-to-action' ) ),
	);
	foreach ( $pats as $slug => $info ) {
		$file = __DIR__ . '/patterns/' . $slug . '.html';
		if ( ! is_readable( $file ) ) {
			continue;
		}
		register_block_pattern( 'gogh/' . $slug, array(
			'title'      => $info[0],
			'categories' => $info[1],
			'content'    => file_get_contents( $file ),
		) );
	}

	// gogh's own headers and footers: a curated shelf for the Change
	// header/footer flicker, so every site gets good choices regardless of
	// what the theme ships. Built from core blocks with theme preset
	// colours — they re-dress when the site style changes.
	$chrome = array(
		'gogh-header-classic' => array( __( 'Classic header — logo left, menu right', 'gogh-editor' ), 'header' ),
		'gogh-header-centred' => array( __( 'Centred header — stacked and calm', 'gogh-editor' ), 'header' ),
		'gogh-header-minimal' => array( __( 'Minimal header — one quiet line', 'gogh-editor' ), 'header' ),
		'gogh-header-bold'    => array( __( 'Bold header — a solid band', 'gogh-editor' ), 'header' ),
		'gogh-header-split'   => array( __( 'Split header — menu centred, search right', 'gogh-editor' ), 'header' ),
		// James: 'i want an option where folks just have a hamburger menu in
		// desktop view' — a LAYOUT, not a buried toggle
		'gogh-header-hamburger' => array( __( 'Hamburger header — everything behind ☰', 'gogh-editor' ), 'header' ),
		'gogh-header-overlay' => array( __( 'Transparent header — floats over your hero', 'gogh-editor' ), 'header' ),
		'gogh-footer-simple'  => array( __( 'Simple footer — everything centred', 'gogh-editor' ), 'footer' ),
		'gogh-footer-columns' => array( __( 'Columns footer — brand, menu, small print', 'gogh-editor' ), 'footer' ),
		'gogh-footer-bold'    => array( __( 'Bold footer — a solid band', 'gogh-editor' ), 'footer' ),
	);
	foreach ( $chrome as $slug => $info ) {
		$file = __DIR__ . '/patterns/' . $slug . '.html';
		if ( ! is_readable( $file ) ) {
			continue;
		}
		register_block_pattern( 'gogh/' . $slug, array(
			'title'       => $info[0],
			'categories'  => array( $info[1] ),
			'blockTypes'  => array( 'core/template-part/' . $info[1] ),
			'viewportWidth' => 1200,
			'content'     => file_get_contents( $file ),
		) );
	}
} );

/**
 * Starter sites: whole sites (pages + menu + front page) shipped as
 * manifests + block-markup files under starters/<slug>/. Pages register as
 * hidden patterns so the preview route can render them; applying a starter
 * is one REST call that trashes current pages (restorable), creates the new
 * set, rebuilds the menu, and wires the front and posts pages.
 */
// the test fixture recreates itself: it reads as junk in the Pages list
// and keeps getting trashed (twice now). Visiting any page with
// ?gogh-test=1 restores or rebuilds it from the bundled copy.
add_action( 'init', function () {
	if ( ! isset( $_GET['gogh-test'] ) || ! current_user_can( 'edit_posts' ) ) {
		return;
	}
	$fixture = get_page_by_path( 'gogh-test-fixture' );
	if ( $fixture && 'publish' === $fixture->post_status ) {
		return;
	}
	if ( $fixture && 'trash' === $fixture->post_status ) {
		wp_untrash_post( $fixture->ID );
		wp_update_post( array( 'ID' => $fixture->ID, 'post_status' => 'publish', 'post_name' => 'gogh-test-fixture' ) );
		return;
	}
	$file = __DIR__ . '/tests-fixture.html';
	if ( is_readable( $file ) ) {
		wp_insert_post( array(
			'post_type'    => 'page',
			'post_status'  => 'publish',
			'post_title'   => 'gogh test fixture',
			'post_name'    => 'gogh-test-fixture',
			'post_content' => file_get_contents( $file ),
		) );
	}
} );

// ---------- gogh as the front door ----------
// With gogh installed, gogh IS the page-building and writing experience:
// Add Page lands on the canvas, Add New Post in the write room, and Edit
// follows — for everything gogh can faithfully edit. Three laws (James,
// 2026-09-03): take over the doors not the bodies; only claim what gogh
// can faithfully edit; always leave the back door (a labelled WordPress
// editor row action, and the gogh_default_editor filter kills the whole
// takeover).
function gogh_default_editor() {
	return (bool) apply_filters( 'gogh_default_editor', true );
}
// can gogh faithfully edit this? New and empty: yes. Built by gogh: yes.
// A post that is prose (the write room's vocabulary): yes. Foreign
// builders, unknown blocks, classic content: the WordPress editor keeps
// it — gogh never opens what it would mangle.
function gogh_claims_post( $post ) {
	$post = get_post( $post );
	if ( ! $post || ! in_array( $post->post_type, array( 'post', 'page' ), true ) ) {
		return false;
	}
	$c     = (string) $post->post_content;
	$claim = false;
	if ( '' === trim( $c ) || false !== strpos( $c, '<!-- wp:gogh/' ) ) {
		$claim = true;
	} elseif ( 'post' === $post->post_type ) {
		$prose = array(
			'core/paragraph', 'core/heading', 'core/image', 'core/list', 'core/list-item',
			'core/quote', 'core/separator', 'core/gallery', 'core/embed', 'core/spacer',
			'core/pullquote', 'core/code', 'core/preformatted',
		);
		$claim = true;
		foreach ( parse_blocks( $c ) as $b ) {
			if ( null === $b['blockName'] ) {
				// stray whitespace between blocks is fine; classic HTML is not
				if ( '' !== trim( $b['innerHTML'] ) ) {
					$claim = false;
					break;
				}
				continue;
			}
			if ( ! in_array( $b['blockName'], $prose, true ) && 0 !== strpos( $b['blockName'], 'gogh/' ) ) {
				$claim = false;
				break;
			}
		}
	}
	return (bool) apply_filters( 'gogh_claims_post', $claim, $post );
}
// the front-end door for a post gogh claims — published posts by
// permalink, drafts through the preview gate
function gogh_front_edit_url( $post ) {
	$post = get_post( $post );
	$args = 'post' === $post->post_type ? array( 'gogh-write' => '1' ) : array( 'gogh-edit' => '1' );
	if ( 'publish' === $post->post_status ) {
		return add_query_arg( $args, get_permalink( $post ) );
	}
	$args['preview'] = 'true';
	$args[ 'page' === $post->post_type ? 'page_id' : 'p' ] = $post->ID;
	return add_query_arg( $args, home_url( '/' ) );
}
// Add Page / Add New Post land straight on gogh's surfaces. An abandoned
// door draft (still blank) is reused, never multiplied; ?gogh-classic=1
// slips past to the WordPress editor.
add_action( 'load-post-new.php', function () {
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- routing only; creation is capability-gated below.
	if ( ! gogh_default_editor() || isset( $_GET['gogh-classic'] ) ) {
		return;
	}
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended
	$type = isset( $_GET['post_type'] ) ? sanitize_key( $_GET['post_type'] ) : 'post';
	if ( ! in_array( $type, array( 'post', 'page' ), true ) ) {
		return;
	}
	$pto = get_post_type_object( $type );
	if ( ! $pto || ! current_user_can( $pto->cap->create_posts ) ) {
		return;
	}
	$id    = 0;
	$stale = get_posts( array(
		'post_type'   => $type,
		'post_status' => 'draft',
		'numberposts' => 1,
		'author'      => get_current_user_id(),
		'meta_key'    => '_gogh_door',
	) );
	if ( $stale && '' === $stale[0]->post_title && '' === trim( wp_strip_all_tags( $stale[0]->post_content ) ) ) {
		$id = $stale[0]->ID;
	}
	if ( ! $id ) {
		// posts seed one blank paragraph (the write room wants a line to
		// stand on); pages must be TRULY empty for the canvas boot invite,
		// so they are born titled and immediately untitled — wp_insert_post
		// refuses an all-empty birth, wp_update_post allows the blanking
		$id = wp_insert_post( array(
			'post_type'    => $type,
			'post_status'  => 'draft',
			'post_title'   => 'page' === $type ? 'Draft page' : '',
			'post_content' => 'page' === $type ? '' : '<!-- wp:paragraph --><p></p><!-- /wp:paragraph -->',
			'meta_input'   => array( '_gogh_door' => 1 ),
		) );
		if ( $id && ! is_wp_error( $id ) && 'page' === $type ) {
			// wp_update_post refuses an all-empty page even as an update —
			// blank the placeholder title directly; the draft is ours,
			// seconds old, and the canvas title block must start empty
			global $wpdb;
			$wpdb->update( $wpdb->posts, array( 'post_title' => '' ), array( 'ID' => $id ) );
			clean_post_cache( $id );
		}
	}
	if ( $id && ! is_wp_error( $id ) ) {
		wp_safe_redirect( gogh_front_edit_url( $id ) );
		exit;
	}
} );
// With gogh as the front door, Appearance → Editor (the block Site
// Editor) is a second, unfamiliar editor for the same site — a beginner
// who wanders in has no way back to what they know (James: 'doesn't seem
// like we should show it for beginners'). The menu item and the admin
// bar's Edit Site go quiet; site-editor.php still answers by URL, and the
// gogh_default_editor filter brings both back.
add_action( 'admin_menu', function () {
	if ( gogh_default_editor() ) {
		remove_submenu_page( 'themes.php', 'site-editor.php' );
	}
}, 999 );
add_action( 'admin_bar_menu', function ( $bar ) {
	if ( gogh_default_editor() ) {
		$bar->remove_node( 'site-editor' );
	}
}, 999 );

// Edit follows the claim: list rows, the admin bar, theme edit links
add_filter( 'get_edit_post_link', function ( $link, $post_id ) {
	if ( ! gogh_default_editor() ) {
		return $link;
	}
	$post = get_post( $post_id );
	if ( ! $post || ! gogh_claims_post( $post ) || ! current_user_can( 'edit_post', $post->ID ) ) {
		return $link;
	}
	return gogh_front_edit_url( $post );
}, 10, 2 );
// the labelled back door on every claimed row
function gogh_classic_row_action( $actions, $post ) {
	if ( ! gogh_default_editor() || ! gogh_claims_post( $post ) || ! current_user_can( 'edit_post', $post->ID ) ) {
		return $actions;
	}
	$actions['gogh_classic'] = '<a href="' . esc_url( admin_url( sprintf( 'post.php?post=%d&action=edit', $post->ID ) ) ) . '">' .
		esc_html__( 'WordPress editor', 'gogh-editor' ) . '</a>';
	return $actions;
}
add_filter( 'page_row_actions', 'gogh_classic_row_action', 10, 2 );
add_filter( 'post_row_actions', 'gogh_classic_row_action', 10, 2 );

// gogh write: a clean canvas and space to think. ?gogh-new-post creates
// a draft and lands the writer straight on the front-end surface;
// ?gogh-write=1 on any editable post enables the mode.
add_action( 'template_redirect', function () {
	if ( ! isset( $_GET['gogh-new-post'] ) || ! current_user_can( 'edit_posts' ) ) {
		return;
	}
	$id = wp_insert_post( array(
		'post_type'    => 'post',
		'post_status'  => 'draft',
		'post_title'   => '',
		// wp_insert_post refuses a FULLY empty post — one blank paragraph
		// is the difference between a canvas and an error
		'post_content' => '<!-- wp:paragraph --><p></p><!-- /wp:paragraph -->',
	) );
	if ( $id && ! is_wp_error( $id ) ) {
		wp_safe_redirect( add_query_arg( array( 'p' => $id, 'preview' => 'true', 'gogh-write' => '1' ), home_url( '/' ) ) );
		exit;
	}
} );
add_action( 'wp_enqueue_scripts', function () {
	if ( ! isset( $_GET['gogh-write'] ) || ! is_singular( 'post' ) ) {
		return;
	}
	$post = get_post();
	if ( ! $post || ! current_user_can( 'edit_post', $post->ID ) ) {
		return;
	}
	wp_register_script( 'gogh-compose', plugins_url( 'gogh-compose.js', __FILE__ ), array(), '0.99.421-chrome', true );
	wp_enqueue_script( 'gogh-write', plugins_url( 'gogh-write.js', __FILE__ ), array( 'gogh-compose' ), '0.99.421-chrome', true );
	wp_enqueue_style( 'gogh-write', plugins_url( 'gogh-write.css', __FILE__ ), array(), '0.99.421-chrome' );
	wp_localize_script( 'gogh-write', 'GOGHWRITE', array(
		'postId'  => $post->ID,
		'restUrl' => esc_url_raw( rest_url() ),
		'nonce'   => wp_create_nonce( 'wp_rest' ),
		'status'  => $post->post_status,
		'homeUrl' => esc_url_raw( home_url( '/' ) ),
		'siteName' => get_bloginfo( 'name' ),
		'adminEdit' => esc_url_raw( get_edit_post_link( $post->ID, 'raw' ) ),
		'postStyle' => get_post_meta( $post->ID, '_gogh_post_style', true ) ?: '',
		'permalink' => esc_url_raw( get_permalink( $post->ID ) ),
		'excerpt' => (string) $post->post_excerpt,
		// the freeform break's starter: a real gogh/section block, generated
		// by the canvas itself and kept as a file — the write room stamps a
		// fresh scope on every insert
		'breakTpl' => (string) file_get_contents( __DIR__ . '/gogh-break.html' ),
	) );
	show_admin_bar( false );
} );

// Pages carry a hand-written description too: the SEO panel's search-
// preview card saves it as the native excerpt. Posts support excerpts out
// of the box; pages need the switch thrown before REST accepts the field.
add_action( 'init', function () {
	add_post_type_support( 'page', 'excerpt' );
} );

/**
 * ✦ Reading styles — how a post READS. The third of the family: Site style
 * (the whole site), Page style (how a page is framed), Post style (how a
 * post reads). A look owns GEOMETRY AND RHYTHM — title treatment, measure,
 * image containment — and never colour or font families: those stay with
 * Site style, so any look composes with any site style and nothing clashes.
 * Switching looks is metadata + CSS; post_content never changes — the words
 * simply re-dress.
 */
/**
 * ✦ Motion style — how the site MOVES. The fourth of the family: Site
 * style (colour and type), Page style (framing), Post style (reading),
 * Motion style (the site's gait). One choice, everywhere, coherent — never
 * per-element animation dropdowns, which is how sites get seasick.
 *
 * All pure CSS scroll-driven animation (animation-timeline: view()): zero
 * JS, compositor-only, and honest about support — browsers without scroll
 * timelines simply see a still site with everything visible. Reduced
 * motion always wins ("motion is a garnish, never a requirement"), and
 * the editor stays still so dragging never fights an entrance.
 */
/**
 * ✦ Blog style — how the blog page presents the work. The fifth of the
 * family. One choice, stored site-wide (there is one blog page), pure CSS
 * over the theme's own query-loop markup — plus one honest render-time
 * enrichment: the stock loop carries only title and date, so while a look
 * that wants media is active, each item gains its featured image (a
 * brand-tinted placeholder when a post has none) and excerpt at render.
 * Nothing is stored; switch to Default and the loop is untouched again.
 */
function gogh_blog_styles() {
	return array( '', 'list', 'cards', 'cover', 'ledger' ); // '' = the theme's own
}
function gogh_blog_style_active() {
	if ( ! ( is_home() || is_category() || is_tag() || is_author() ) ) {
		return '';
	}
	if ( isset( $_GET['gogh-look'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- presentation-only preview
		$look = sanitize_key( $_GET['gogh-look'] ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		if ( in_array( $look, gogh_blog_styles(), true ) ) {
			return $look;
		}
	}
	$opt = get_option( 'gogh_blog_style', '' );
	return in_array( $opt, gogh_blog_styles(), true ) ? $opt : '';
}
add_filter( 'body_class', function ( $classes ) {
	$b = gogh_blog_style_active();
	if ( $b ) {
		$classes[] = 'gogh-blog-' . $b;
	}
	return $classes;
}, 20 );
// the enrichment: media + excerpt join each loop item while a look wants them
add_filter( 'render_block_core/post-template', function ( $content ) {
	if ( ! ( is_home() || is_category() || is_tag() || is_author() ) ) {
		return $content;
	}
	// enrich while a look is active — and ALWAYS for editors, so the pill's
	// hover-audition has real media to dress ('blog style is not showing
	// any images, just empty cards'): the client flips classes instantly,
	// the spans must already be there. Default-look visitors keep clean
	// markup; the CSS hides the spans until a look asks for them.
	$b = gogh_blog_style_active();
	if ( ! in_array( $b, array( 'list', 'cards', 'cover', 'ledger' ), true ) && ! current_user_can( 'edit_theme_options' ) ) {
		return $content;
	}
	return preg_replace_callback(
		'/<li class="wp-block-post post-(\d+)[^"]*">/',
		function ( $m ) {
			$id  = (int) $m[1];
			$img = get_the_post_thumbnail( $id, 'medium_large', array( 'class' => 'gogh-bs-thumb' ) );
			if ( ! $img && preg_match( '/<img[^>]+src="([^"]+)"/', (string) get_post_field( 'post_content', $id ), $im ) ) {
				// no featured image, but the post has pictures — the first one
				// stands in ('its still just showing image placeholders')
				$img = '<img class="gogh-bs-thumb" src="' . esc_url( $im[1] ) . '" alt="" loading="lazy" />';
			}
			if ( ! $img ) {
				// no featured image: a brand-tinted stand-in, hue seeded by the
				// post id so neighbouring posts never match
				$hue = ( $id * 47 ) % 360;
				$img = '<span class="gogh-bs-thumb gogh-bs-thumb-empty" style="background: linear-gradient(130deg, oklch(0.72 0.09 ' . $hue . '), oklch(0.35 0.08 ' . ( ( $hue + 40 ) % 360 ) . '));"></span>';
			}
			$ex = esc_html( wp_trim_words( get_the_excerpt( $id ), 20 ) );
			return $m[0] . '<span class="gogh-bs-media">' . $img . '</span><span class="gogh-bs-excerpt">' . $ex . '</span>';
		},
		$content
	);
} );
function gogh_blog_style_css() {
	$hair    = 'color-mix(in srgb, currentColor 25%, transparent)';
