		'.gogh-blog-ledger li.wp-block-post > .wp-block-group { flex: 1; display: flex; align-items: baseline; gap: 18px; margin: 0 !important; padding: 0 !important; }' .
		'.gogh-blog-ledger li.wp-block-post :is(.wp-block-post-title, .wp-block-post-date) { margin-block: 0 !important; }' .
		'.gogh-blog-ledger .gogh-bs-media { width: 52px; height: 52px; flex: none; border-radius: 8px; overflow: hidden; }' .
		'.gogh-blog-ledger li.wp-block-post .wp-block-post-title { font-size: 1.1em; line-height: 1.25; flex: 1; }' .
		'.gogh-blog-list li.wp-block-post > .wp-block-group { display: contents; }' .
		'.gogh-blog-ledger .gogh-bs-excerpt { display: none; }' .
		'.gogh-blog-ledger li.wp-block-post .wp-block-post-date { font-size: 0.78em; opacity: 0.6; font-variant-numeric: tabular-nums; white-space: nowrap; }';
}

function gogh_motion_styles() {
	return array( '', 'calm', 'rise', 'drama' ); // '' = Still, the default
}
function gogh_motion_css() {
	$targets = function ( $key ) {
		return 'html:not(.gogh-editing) body.gogh-motion-' . $key . ' .gogh-section > *, ' .
			'html:not(.gogh-editing) body.gogh-motion-' . $key . ' .entry-content > *:not(.gogh-wrap):not(.wp-block-post-title):not(.alignfull)';
	};
	return
		'@supports (animation-timeline: view()) { @media (prefers-reduced-motion: no-preference) {' .
		// ranges end at COVER, not entry: a short element's "entry" span is
		// its own height — a badge finished its whole entrance in ~15px of
		// scroll and read as nothing ("doesnt seem very motiony"). Anchoring
		// the end to the element's journey through the viewport gives every
		// element, tall or tiny, a real scroll distance to move across.
		// CALM — a soft fade with barely-there lift
		$targets( 'calm' ) . ' { animation: gogh-mo-calm linear both; animation-timeline: view(); animation-range: entry 0% cover 25%; }' .
		'@keyframes gogh-mo-calm { from { opacity: 0; translate: 0 12px; } }' .
		// RISE — content lifts into place with a small sibling stagger
		$targets( 'rise' ) . ' { animation: gogh-mo-rise linear both; animation-timeline: view(); animation-range: entry 0% cover 30%; }' .
		'html:not(.gogh-editing) body.gogh-motion-rise .gogh-section > :nth-child(2) { animation-range: entry 5% cover 38%; }' .
		'html:not(.gogh-editing) body.gogh-motion-rise .gogh-section > :nth-child(3) { animation-range: entry 10% cover 46%; }' .
		'html:not(.gogh-editing) body.gogh-motion-rise .gogh-section > :nth-child(n+4) { animation-range: entry 15% cover 54%; }' .
		'@keyframes gogh-mo-rise { from { opacity: 0; translate: 0 40px; } }' .
		// DRAMA — bigger travel and a breath of scale
		$targets( 'drama' ) . ' { animation: gogh-mo-drama linear both; animation-timeline: view(); animation-range: entry 0% cover 45%; }' .
		'@keyframes gogh-mo-drama { from { opacity: 0; translate: 0 72px; scale: 0.96; } }' .
		'} }';
}
// the imagination's key — folks bring their own. Three sources, first
// wins: wp-config's GOGH_ASK_KEY (hosts/pros), the environment, or the
// option an admin pasted into the Ask panel (stored unautoloaded,
// write-only: it never travels back to a browser). No key = the tier
// simply isn't there; the vocabulary still answers.
function gogh_ask_key() {
	if ( defined( 'GOGH_ASK_KEY' ) && GOGH_ASK_KEY ) {
		return GOGH_ASK_KEY;
	}
	$env = getenv( 'ANTHROPIC_API_KEY' );
	if ( $env ) {
		return $env;
	}
	return (string) get_option( 'gogh_ask_key', '' );
}
// identity-linked keys act inside a workspace: same three sources
function gogh_ask_workspace() {
	if ( defined( 'GOGH_ASK_WORKSPACE' ) && GOGH_ASK_WORKSPACE ) {
		return GOGH_ASK_WORKSPACE;
	}
	$env = getenv( 'ANTHROPIC_WORKSPACE_ID' );
	if ( $env ) {
		return $env;
	}
	return (string) get_option( 'gogh_ask_workspace', '' );
}
// The section-level imagination tier is PARKED (James, 2026-09-03: the
// dice showed choice-within-guidelines beats ask-and-hope — "we might not
// need ai here"). The vocabulary, the seam and Experiences all stay; the
// model-backed section rewriter waits behind this labs door.
function gogh_labs_ask() {
	if ( defined( 'GOGH_LABS_ASK' ) ) {
		return (bool) GOGH_LABS_ASK;
	}
	return (bool) apply_filters( 'gogh_labs_ask', false );
}
function gogh_ask_handler( $req ) {
	if ( ! gogh_labs_ask() ) {
		return new WP_Error( 'gogh_ask_parked', __( 'The imagination tier is parked — Gogh answers with its built-in vocabulary.', 'gogh-editor' ), array( 'status' => 501 ) );
	}
	$key = gogh_ask_key();
	if ( ! $key ) {
		return new WP_Error( 'gogh_ask_no_key', __( 'The imagination tier has no key.', 'gogh-editor' ), array( 'status' => 501 ) );
	}
	$p           = $req->get_json_params();
	$instruction = isset( $p['instruction'] ) ? substr( sanitize_text_field( (string) $p['instruction'] ), 0, 300 ) : '';
	$section     = isset( $p['section'] ) && is_array( $p['section'] ) ? $p['section'] : null;
	if ( ! $instruction || ! $section || empty( $section['els'] ) || ! is_array( $section['els'] ) ) {
		return new WP_Error( 'gogh_ask_bad', __( 'Nothing to imagine with.', 'gogh-editor' ), array( 'status' => 400 ) );
	}
	// re-project server-side: only the fields the prompt schema names, so
	// the prompt can't be stuffed through a hand-rolled request body
	$els = array();
	foreach ( array_slice( $section['els'], 0, 24 ) as $i => $e ) {
		if ( ! is_array( $e ) ) {
			continue;
		}
		$o = array(
			'i'    => $i,
			'type' => isset( $e['type'] ) ? sanitize_key( $e['type'] ) : 'box',
			'x'    => isset( $e['x'] ) ? (int) $e['x'] : 0,
			'y'    => isset( $e['y'] ) ? (int) $e['y'] : 0,
			'w'    => isset( $e['w'] ) ? (int) $e['w'] : 100,
			'h'    => isset( $e['h'] ) ? (int) $e['h'] : 50,
		);
		foreach ( array( 'fs', 'align' ) as $f ) {
			if ( ! empty( $e[ $f ] ) ) {
				$o[ $f ] = substr( sanitize_text_field( (string) $e[ $f ] ), 0, 20 );
			}
		}
		if ( ! empty( $e['text'] ) ) {
			$o['text'] = substr( sanitize_text_field( (string) $e['text'] ), 0, 120 );
		}
		if ( ! empty( $e['ghost'] ) ) {
			$o['ghost'] = true;
		}
		if ( ! empty( $e['kids'] ) && is_array( $e['kids'] ) ) {
			$o['kids'] = count( $e['kids'] );
		}
		$els[] = $o;
	}
	// the client names the themes its palette actually offers (accents are
	// per-site); slugs only, and the client re-validates on the way back
	$themes = array( 'paper', 'mist', 'ink', 'sweep', 'mesh' );
	if ( ! empty( $section['themes'] ) && is_array( $section['themes'] ) ) {
		$sent = array();
		foreach ( array_slice( $section['themes'], 0, 12 ) as $t ) {
			if ( is_array( $t ) ) {
				// slug plus its MEASURED feel and hex — on a dark-mode
				// palette "ink" paints white, and only the client knows;
				// the hex is what stops "red" coming back blue
				$sl = isset( $t['slug'] ) ? sanitize_key( $t['slug'] ) : '';
				$fl = isset( $t['feel'] ) ? sanitize_key( $t['feel'] ) : '';
				$hx = ( isset( $t['hex'] ) && preg_match( '/^#[0-9a-fA-F]{6}$/', (string) $t['hex'] ) ) ? strtolower( $t['hex'] ) : '';
				if ( $sl ) {
					$note   = trim( $fl . ( $hx ? ' ' . $hx : '' ) );
					$sent[] = $sl . ( $note ? ' (' . $note . ')' : '' );
				}
			} elseif ( is_string( $t ) && sanitize_key( $t ) ) {
				$sent[] = sanitize_key( $t );
			}
		}
		if ( $sent ) {
			$themes = $sent;
		}
	}
	$sys    =
		"You are the imagination inside Gogh, a visual page builder. You redesign ONE section at a time.\n" .
		"A section is a 1200-unit-wide canvas; y grows downward; every element is a rectangle {i,type,x,y,w,h}. " .
		"Types: heading, para (text), button, image, badge, box (a card; kids = how many pieces it holds).\n" .
		"You NEVER write HTML or CSS. You return CHANGES to this model as JSON and the builder renders them safely.\n\n" .
		"Reply with ONLY this JSON — no fences, no prose:\n" .
		'{"candidates":[{"name":"Two words","ops":{}},{"name":"Two words","ops":{}}]}' . "\n" .
		"Exactly 2 candidates, each a genuinely DIFFERENT honest interpretation. name = 2-3 evocative words.\n\n" .
		"ops may contain:\n" .
		'- "set": [{"i":N, ...fields}] to change elements' . "\n" .
		'- "add": [{"type":"heading|para|button|image|badge","x":N,"y":N,"w":N,"h":N,"text":"..."}]' . "\n" .
		'- "remove": [indexes]' . "\n" .
		'- "section": {"theme":"slug","minH":N,"spread":0.7-1.6}' . "\n\n" .
		'Allowed set fields: x y w h (numbers) · text (short, the site\'s voice) · fs (null, "__disp-s", "__disp-m", "__disp-l" — display sizes, big) · align ("left","center","right") · rot (-6..6) · ghost (buttons: quiet outline) · mood (null,"lift","zoom" — hover life, image/box only) · tf {"fw":100-900,"ls2":-0.05-0.4,"tt":"uppercase"|null,"lh":0.9-2}.' . "\n" .
		'Section themes (the ONLY way to colour — never invent colours): ' . implode( ', ', $themes ) . '. A bracket is the colour that theme ACTUALLY paints on this site — trust it over the name. Name candidates by what the ops truly do; never promise a colour the palette cannot paint.' . "\n" .
		"Rules: 24+ units of air between elements; everything fits (x+w ≤ 1200); reading order top-to-bottom; " .
		"a section holds 2-8 elements; big type is the cheapest wow; when in doubt remove rather than add.";
	$user = wp_json_encode( array(
		'instruction' => $instruction,
		'section'     => array(
			'minH'  => isset( $section['minH'] ) ? (int) $section['minH'] : null,
			'theme' => isset( $section['theme'] ) ? sanitize_key( (string) $section['theme'] ) : null,
			'els'   => $els,
		),
	) );
	$headers = array(
		'content-type'      => 'application/json',
		'x-api-key'         => $key,
		'anthropic-version' => '2023-06-01',
	);
	$ws = gogh_ask_workspace();
	if ( $ws ) {
		$headers['anthropic-workspace-id'] = $ws;
	}
	$res = wp_remote_post( 'https://api.anthropic.com/v1/messages', array(
		'timeout' => 25,
		'headers' => $headers,
		'body'    => wp_json_encode( array(
			'model'      => 'claude-sonnet-5',
			// the model may spend a thinking block before its answer —
			// the budget covers both or the text never arrives
			'max_tokens' => 6000,
			'system'     => $sys,
			'messages'   => array( array( 'role' => 'user', 'content' => $user ) ),
		) ),
	) );
	if ( is_wp_error( $res ) ) {
		// name the transport failure (TLS, DNS, timeout) — never the key
		return new WP_Error( 'gogh_ask_down', sprintf(
			/* translators: %s: transport error detail */
			__( 'The imagination could not be reached — %s', 'gogh-editor' ),
			$res->get_error_message()
		), array( 'status' => 502 ) );
	}
	$code = wp_remote_retrieve_response_code( $res );
	$body = json_decode( wp_remote_retrieve_body( $res ), true );
	if ( 401 === $code || 403 === $code ) {
		return new WP_Error( 'gogh_ask_bad_key', __( 'The key was refused — forget it and paste a fresh one.', 'gogh-editor' ), array( 'status' => 502 ) );
	}
	// the answer may sit after a thinking block — take every text block,
	// wherever it lands
	$text = '';
	if ( ! empty( $body['content'] ) && is_array( $body['content'] ) ) {
		foreach ( $body['content'] as $blk ) {
			if ( isset( $blk['type'], $blk['text'] ) && 'text' === $blk['type'] ) {
				$text .= $blk['text'];
			}
		}
	}
	$text = trim( $text );
	if ( 200 !== $code || '' === $text ) {
		$why = isset( $body['error']['message'] ) ? substr( (string) $body['error']['message'], 0, 160 ) : 'HTTP ' . $code;
		if ( 200 === $code ) {
			$why = 'empty answer (' . ( isset( $body['stop_reason'] ) ? $body['stop_reason'] : '?' ) . ': ' .
				implode( ',', array_map( function ( $b2 ) { return isset( $b2['type'] ) ? $b2['type'] : '?'; },
					is_array( $body['content'] ) ? $body['content'] : array() ) ) . ')';
		}
		// an identity-linked key without its workspace gets its own door
		if ( false !== stripos( $why, 'workspace' ) ) {
			return new WP_Error( 'gogh_ask_need_ws', __( 'Your key is workspace-linked — it needs its Workspace ID (starts wrkspc_…, shown beside the key in the console).', 'gogh-editor' ), array( 'status' => 502 ) );
		}
		return new WP_Error( 'gogh_ask_down', sprintf(
			/* translators: %s: upstream error detail */
			__( 'The imagination did not answer — %s', 'gogh-editor' ),
			$why
		), array( 'status' => 502 ) );
	}
	$text = preg_replace( '/^```(?:json)?\s*|\s*```$/', '', $text );
	// a chatty reply still usually carries the JSON — cut to the braces
	$a = strpos( $text, '{' );
	$z = strrpos( $text, '}' );
	if ( false !== $a && false !== $z && $z > $a ) {
		$text = substr( $text, $a, $z - $a + 1 );
	}
	$out = json_decode( $text, true );
	if ( empty( $out['candidates'] ) || ! is_array( $out['candidates'] ) ) {
		return new WP_Error( 'gogh_ask_odd', __( 'The imagination mumbled.', 'gogh-editor' ), array( 'status' => 502 ) );
	}
	// the client re-validates and clamps every field — this is transport,
	// not trust
	return array( 'candidates' => array_slice( array_values( $out['candidates'] ), 0, 3 ) );
}

// ✦ Imagine an experience: one prompt in, one self-contained HTML file
// out — written by the model, saved into the user's OWN media library,
// framed by the sandboxed Experience element. Same key, same workspace,
// same hard-won transport lessons as gogh/v1/ask.
function gogh_imagine_exp_handler( $req ) {
	$key = gogh_ask_key();
	if ( ! $key ) {
		return new WP_Error( 'gogh_ask_no_key', __( 'The imagination tier has no key.', 'gogh-editor' ), array( 'status' => 501 ) );
	}
	$p      = $req->get_json_params();
	$prompt = isset( $p['prompt'] ) ? substr( sanitize_text_field( (string) $p['prompt'] ), 0, 400 ) : '';
	if ( '' === $prompt ) {
		return new WP_Error( 'gogh_exp_bad', __( 'Describe the experience first.', 'gogh-editor' ), array( 'status' => 400 ) );
	}
	// the site's own inks travel along, so "in our brand colours" lands
	$pal     = array();
	$palette = wp_get_global_settings( array( 'color', 'palette' ) );
	foreach ( (array) ( $palette['theme'] ?? array() ) as $c ) {
		if ( isset( $c['slug'], $c['color'] ) ) {
			$pal[] = $c['slug'] . ' ' . $c['color'];
		}
	}
	$sys = 'You write ONE complete, self-contained HTML file: a small interactive or generative "experience" that runs inside a sandboxed iframe on a WordPress page. Rules: ' .
		'look stunning — full creative mode; canvas, SVG and CSS are all yours, motion welcome; ' .
		'ONE file, zero external requests: no CDNs, no web fonts, no remote images, no fetch — everything inline; ' .
		'fill the viewport (html and body at height 100%, margin 0) and adapt to any frame size; ' .
		'respect prefers-reduced-motion with a beautiful still fallback; ' .
		'the frame may report a 0x0 viewport at first paint — size everything from a function that re-runs on the resize event, never once at load; ' .
		'pointer and touch input welcome; sound only if the ask requests it; no alert(), no storage; ' .
		'keep the source under 60KB. ' .
		( $pal ? 'If the ask mentions brand or site colours, the palette is: ' . implode( ', ', array_slice( $pal, 0, 10 ) ) . '. ' : '' ) .
		'Answer with the HTML file ONLY — no fences, no commentary — starting with <!doctype html>.';
	$headers = array(
		'content-type'      => 'application/json',
		'x-api-key'         => $key,
		'anthropic-version' => '2023-06-01',
	);
	$ws = gogh_ask_workspace();
	if ( $ws ) {
		$headers['anthropic-workspace-id'] = $ws;
	}
	if ( function_exists( 'set_time_limit' ) ) {
		set_time_limit( 240 ); // a whole file takes longer than an op list
	}
	$res = wp_remote_post( 'https://api.anthropic.com/v1/messages', array(
		'timeout' => 180,
		'headers' => $headers,
		'body'    => wp_json_encode( array(
			'model'      => 'claude-sonnet-5',
			// a whole file, plus any thinking the model spends first
			'max_tokens' => 24000,
			'system'     => $sys,
			'messages'   => array( array( 'role' => 'user', 'content' => $prompt ) ),
		) ),
	) );
	if ( is_wp_error( $res ) ) {
		return new WP_Error( 'gogh_ask_down', sprintf(
			/* translators: %s: transport error detail */
			__( 'The imagination could not be reached — %s', 'gogh-editor' ),
			$res->get_error_message()
		), array( 'status' => 502 ) );
	}
	$code = wp_remote_retrieve_response_code( $res );
	$body = json_decode( wp_remote_retrieve_body( $res ), true );
	if ( 401 === $code || 403 === $code ) {
		return new WP_Error( 'gogh_ask_bad_key', __( 'The key was refused — forget it and paste a fresh one.', 'gogh-editor' ), array( 'status' => 502 ) );
	}
	$text = '';
	if ( ! empty( $body['content'] ) && is_array( $body['content'] ) ) {
		foreach ( $body['content'] as $blk ) {
			if ( isset( $blk['type'], $blk['text'] ) && 'text' === $blk['type'] ) {
				$text .= $blk['text'];
			}
		}
	}
	$text = trim( $text );
	if ( 200 !== $code || '' === $text ) {
		$why = isset( $body['error']['message'] ) ? substr( (string) $body['error']['message'], 0, 160 ) : 'HTTP ' . $code;
		if ( false !== stripos( $why, 'workspace' ) ) {
			return new WP_Error( 'gogh_ask_need_ws', __( 'Your key is workspace-linked — it needs its Workspace ID (starts wrkspc_…, shown beside the key in the console).', 'gogh-editor' ), array( 'status' => 502 ) );
		}
		return new WP_Error( 'gogh_ask_down', sprintf(
			/* translators: %s: upstream error detail */
			__( 'The imagination did not answer — %s', 'gogh-editor' ),
			$why
		), array( 'status' => 502 ) );
	}
	// unwrap fences if the model added them anyway, and cut to the document
	$text = preg_replace( '/^```(?:html)?\s*|\s*```$/', '', $text );
	$a    = stripos( $text, '<!doctype' );
	if ( false === $a ) {
		$a = stripos( $text, '<html' );
	}
	if ( false !== $a ) {
		$text = substr( $text, $a );
	}
	$z = strripos( $text, '</html>' );
	if ( false !== $z ) {
		$text = substr( $text, 0, $z + 7 );
	}
	if ( false === stripos( $text, '<body' ) && false === stripos( $text, '<canvas' ) ) {
		return new WP_Error( 'gogh_exp_odd', __( 'The imagination mumbled — try describing it differently.', 'gogh-editor' ), array( 'status' => 502 ) );
	}
	if ( strlen( $text ) > 400000 ) {
		return new WP_Error( 'gogh_exp_big', __( 'That came out too large — ask for something simpler.', 'gogh-editor' ), array( 'status' => 502 ) );
	}
	// the seatbelt: sandboxed frames can boot at 0x0 before layout sizes
	// them — a tiny injected watcher fires one synthetic resize the moment
	// the viewport is real, so any well-behaved rebuild-on-resize file
	// (the prompt requires one) heals itself
	$seatbelt = '<script>(function(){var n=0,iv=setInterval(function(){if(innerWidth>0&&innerHeight>0){clearInterval(iv);dispatchEvent(new Event("resize"));}else if(++n>600){clearInterval(iv);}},50);})();</script>';
	if ( false !== stripos( $text, '<head>' ) ) {
		$text = preg_replace( '/<head>/i', '<head>' . $seatbelt, $text, 1 );
	} else {
		$text = $seatbelt . $text;
	}
	$slug = sanitize_title( wp_trim_words( $prompt, 6, '' ) );
	$up   = wp_upload_bits( ( $slug ? $slug : 'experience' ) . '.html', null, $text );
	if ( ! empty( $up['error'] ) ) {
		return new WP_Error( 'gogh_exp_save', $up['error'], array( 'status' => 500 ) );
	}
	$att = wp_insert_attachment( array(
		'post_mime_type' => 'text/html',
		'post_title'     => ucwords( wp_trim_words( $prompt, 8 ) ),
		'post_status'    => 'inherit',
	), $up['file'] );
	if ( ! $att || is_wp_error( $att ) ) {
		return new WP_Error( 'gogh_exp_save', __( 'The file could not join the media library.', 'gogh-editor' ), array( 'status' => 500 ) );
	}
	return array(
		'id'    => (int) $att,
		'url'   => $up['url'],
		'title' => get_the_title( $att ),
	);
}

// preview any reading look on any post: ?gogh-look=gazette — CSS-only,
// nothing stored; lets a writer share "how would this read as X" links
// (and lets screenshots be taken without touching the post)
add_filter( 'body_class', function ( $classes ) {
	if ( isset( $_GET['gogh-look'] ) && is_singular() ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- presentation-only preview
		$look = sanitize_key( $_GET['gogh-look'] ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		if ( in_array( $look, gogh_reading_styles(), true ) && $look ) {
			$classes   = array_diff( $classes, array_map( function ( $s ) { return 'gogh-read-' . $s; }, gogh_reading_styles() ) );
			$classes[] = 'gogh-read-' . $look;
		}
	}
	return $classes;
}, 20 );

add_filter( 'body_class', function ( $classes ) {
	$m = get_option( 'gogh_motion', '' );
	if ( $m && in_array( $m, gogh_motion_styles(), true ) ) {
		$classes[] = 'gogh-motion-' . $m;
	}
	return $classes;
} );

/**
 * ✦ The wow pass — the devices that turn polite looks into publications
 * (research note: scale commitment, type mixing, editorial furniture,
 * image rhythm, asymmetry). The type rule's honest amendment lives in
 * gogh_look_fonts(): a look may borrow a SECOND voice, but only from the
 * font families the theme itself registers — zero downloads, any brand.
 */
function gogh_look_fonts() {
	static $out = null;
	if ( null !== $out ) {
		return $out;
	}
	$list = array();
	$fams = wp_get_global_settings( array( 'typography', 'fontFamilies' ) );
	if ( is_array( $fams ) ) {
		foreach ( array( 'custom', 'theme', 'default' ) as $srcKey ) {
			if ( empty( $fams[ $srcKey ] ) || ! is_array( $fams[ $srcKey ] ) ) {
				continue;
			}
			foreach ( $fams[ $srcKey ] as $f ) {
				if ( ! empty( $f['fontFamily'] ) && ! empty( $f['slug'] ) ) {
					$list[ $f['slug'] ] = $f['fontFamily'];
				}
			}
		}
	}
	$body = wp_get_global_styles( array( 'typography', 'fontFamily' ) );
	if ( is_string( $body ) && preg_match( '/font-family\|([a-z0-9-]+)/', $body, $m ) && isset( $list[ $m[1] ] ) ) {
		$body = $list[ $m[1] ];
	}
	if ( ! is_string( $body ) || '' === $body ) {
		$body = $list ? reset( $list ) : '';
	}
	$display = '';
	foreach ( $list as $fam ) {
		if ( $fam !== $body ) {
			$display = $fam;
			break;
		}
	}
	$out = array( 'display' => $display, 'body' => $body );
	return $out;
}

function gogh_reading_wow_css() {
	$lf = gogh_look_fonts();
	// the second voice: only when the theme actually registers one
	$disp = $lf['display'] ? ' font-family: ' . $lf['display'] . ';' : '';
	$rule25 = 'color-mix(in srgb, currentColor 25%, transparent)';
	return
		// ---- shared furniture: the asterism and the end-mark. A rule the
		// writer inserts becomes three quiet sparks; the last paragraph
		// closes with the printer's tombstone. ----
		':is(.gogh-read-magazine, .gogh-read-essay, .gogh-read-feature) .entry-content hr { border: 0; margin-block: 2.6em; text-align: center; overflow: visible; }' .
		':is(.gogh-read-magazine, .gogh-read-essay, .gogh-read-feature) .entry-content hr::before { content: "\2726 \2726 \2726"; letter-spacing: 1.1em; padding-left: 1.1em; font-size: 0.72rem; opacity: 0.45; }' .
		':is(.gogh-read-magazine, .gogh-read-gazette, .gogh-read-feature) .entry-content > p:last-of-type::after { content: " \220E"; font-size: 0.8em; opacity: 0.55; }' .
		// ---- MAGAZINE v2: scale commitment + the second voice + furniture ----
		'.gogh-read-magazine :is(.wp-block-post-title, .gogh-w-title) { font-size: clamp(3.4rem, 8vw, 6rem); font-weight: 800; line-height: 0.98; letter-spacing: -0.02em; max-width: 14ch;' . $disp . ' }' .
		'.gogh-read-magazine :is(.wp-block-post-terms, .wp-block-post-date, .wp-block-post-author-name) { font-size: 0.72rem; letter-spacing: 0.16em; text-transform: uppercase; opacity: 0.75; }' .
		'.gogh-read-magazine .wp-block-post-terms a { text-decoration: none; }' .
		// image rhythm: every second contained image goes full-bleed — never
		// the same treatment twice running; nothing stored, pure nth rhythm
		'.gogh-read-magazine .entry-content > figure.wp-block-image:not(.alignwide):not(.alignfull):nth-of-type(even) { width: 100vw; max-width: 100vw; margin-inline: calc(50% - 50vw); }' .
		'.gogh-read-magazine .entry-content > figure.wp-block-image:not(.alignwide):not(.alignfull):nth-of-type(even) img { width: 100%; max-height: 82vh; object-fit: cover; }' .
		'.gogh-read-magazine .entry-content figure.wp-block-image figcaption { font-variant-caps: all-small-caps; letter-spacing: 0.12em; font-size: 0.86rem; opacity: 0.6; margin-top: 0.9em; }' .
		// ---- ESSAY v2: the italic standfirst is the second voice ----
		'.gogh-read-essay .entry-content > p:first-of-type { font-style: italic; font-size: 1.22em; }' .
		'.gogh-read-essay .entry-content blockquote { position: relative; padding-top: 2.6em; }' .
		'.gogh-read-essay .entry-content blockquote::before { content: "\201C"; position: absolute; top: 0.05em; left: 0.28em; font-size: 3.6em; line-height: 1; opacity: 0.28; }' .
		// ---- GAZETTE v2: the columned intro from the Commons Journal ----
		'@media (min-width: 800px) { .gogh-read-gazette .entry-content > p:first-of-type { columns: 2; column-gap: 2.4em; column-rule: 1px solid ' . $rule25 . '; max-width: 68ch; } }' .
		'.gogh-read-gazette :is(.wp-block-post-title, .gogh-w-title) {' . $disp . ' }' .
		'.gogh-read-gazette .entry-content > h2, .gogh-read-gazette .entry-content > h3 {' . $disp . ' }' .
		// ---- GAZETTE v3: the broadsheet. When the server measures a post
		// short enough to fit without scroll-back (.gogh-short), the WHOLE
		// article runs in newspaper columns — length buys the treatment,
		// because print columns only work when the reader never has to
		// scroll down one column and back up for the next. ----
		'@media (min-width: 900px) {' .
			'.gogh-read-gazette.gogh-short .entry-content { columns: 2; column-gap: 2.8em; column-rule: 1px solid ' . $rule25 . '; max-width: min(1100px, 92vw); margin-inline: auto !important; orphans: 2; widows: 2; }' .
			// inside the broadsheet every child yields the theme's centred
			// constraint and fills its column
			'.gogh-read-gazette.gogh-short .entry-content > * { max-width: none; margin-inline: 0; }' .
			// the v2 columned intro stands down — no columns inside columns
			'.gogh-read-gazette.gogh-short .entry-content > p:first-of-type { columns: auto; column-rule: none; }' .
			'.gogh-read-gazette.gogh-short .entry-content :is(figure, blockquote) { break-inside: avoid; }' .
			'.gogh-read-gazette.gogh-short .entry-content > :is(h2, h3) { break-after: avoid; }' .
			'.gogh-read-gazette.gogh-short .entry-content figure.wp-block-image img { width: 100%; }' .
		'}' .
		'@media (min-width: 1200px) { .gogh-read-gazette.gogh-short .entry-content { columns: 3; } }' .
		// ---- PHOTO STORY v2: statements go big, bleed captions move inside ----
		'.gogh-read-photostory .entry-content > figure.wp-block-image + p { font-size: 1.5em; line-height: 1.35; max-width: 30ch; }' .
		'.gogh-read-photostory :is(.wp-block-post-title, .gogh-w-title) {' . $disp . ' }' .
		'.gogh-read-photostory .entry-content figure.wp-block-image:is(.alignwide, .alignfull) { position: relative; }' .
		'.gogh-read-photostory .entry-content figure.wp-block-image:is(.alignwide, .alignfull) figcaption { position: absolute; left: 26px; bottom: 18px; margin: 0; text-align: left; color: #fff; opacity: 0.94; text-shadow: 0 1px 16px rgba(0, 0, 0, 0.65); font-size: 0.88rem; }' .
		// ---- FEATURE: the committed-asymmetric look. Everything ranges hard
		// left; the title is the loudest thing gogh has ever set; a thin rule
		// runs the content's left edge; images offset right and hang their
		// captions back toward the margin. ----
		'.gogh-read-feature :is(.wp-block-post-title, .gogh-w-title) { font-size: clamp(3.6rem, 10vw, 7rem); font-weight: 800; line-height: 0.95; letter-spacing: -0.03em; text-wrap: balance; text-align: left; width: min(1060px, 94vw); max-width: none; margin-inline: auto;' . $disp . ' }' .
		// the composed canvas: a centred stage, everything ranged left WITHIN
		// it — flushing to the viewport edge opened a huge right void
		'.gogh-read-feature .entry-content { max-width: min(1060px, 94vw); margin-inline: auto !important; }' .
		'.gogh-read-feature main :is(p, .wp-block-group):has(.wp-block-post-author-name, a[href*="/author/"]) { width: min(1060px, 94vw); margin-inline: auto; text-align: left; justify-content: flex-start; }' .
		'.gogh-read-feature :is(.wp-block-post-terms, .wp-block-post-date, .wp-block-post-author-name) { font-size: 0.72rem; letter-spacing: 0.14em; text-transform: uppercase; opacity: 0.7; }' .
		'.gogh-read-feature .entry-content { border-left: 1px solid ' . $rule25 . '; padding-left: clamp(16px, 3vw, 34px); }' .
		'.gogh-read-feature .entry-content > * { margin-left: 0 !important; }' .
		'.gogh-read-feature .entry-content > p { max-width: 58ch; line-height: 1.7; }' .
		'.gogh-read-feature .entry-content > h2, .gogh-read-feature .entry-content > h3 { max-width: 58ch; font-size: 1.05em; letter-spacing: 0.12em; text-transform: uppercase; margin-block-start: 2.6em; }' .
		'.gogh-read-feature .entry-content > figure.wp-block-image:not(.alignfull) { margin-left: auto !important; margin-right: 0; width: min(86%, 720px); }' .
		'.gogh-read-feature .entry-content > figure.wp-block-image:not(.alignfull) img { width: 100%; max-height: 78vh; object-fit: cover; }' .
		'.gogh-read-feature .entry-content figure.wp-block-image figcaption { text-align: left; border-top: 1px solid ' . $rule25 . '; padding-top: 0.6em; margin-top: 0.8em; max-width: 26ch; font-size: 0.84rem; opacity: 0.65; }' .
		'.gogh-read-feature .entry-content blockquote { border: 0; font-size: 1.5em; line-height: 1.3; max-width: 24ch; margin-inline: 0; padding: 0; }';
}

/**
 * ✦ Gogh Forms — simple and elegant, no plugin ("most sites need it").
 * One dynamic block, three fields (name, email, message), a honeypot,
 * and every message stored as the user's OWN data: a private Messages
 * book in wp-admin, plus a note to the site's email. The saved page
 * carries plain block markup — the deactivation promise holds.
 */
add_action( 'init', function () {
	// ---------- Menu panels: the mega menu is a gogh page that drops from an item ----------
	// Designed on the blank canvas like any section; carried by the menu item
	// as a class (gogh-panel-12); rendered into the header at view time.
	register_post_type( 'gogh_panel', array(
		'label'               => __( 'Mega menus', 'gogh-editor' ),
		'labels'              => array( 'name' => __( 'Mega menus', 'gogh-editor' ), 'singular_name' => __( 'Mega menu', 'gogh-editor' ) ),
		'public'              => false,
		'publicly_queryable'  => true,  // the editor works on the panel's own URL (editors only — see below)
		'exclude_from_search' => true,
		'show_ui'             => false,
		'show_in_nav_menus'   => false,
		'show_in_rest'        => true,
		'rest_base'           => 'gogh-panels',
		'rewrite'             => array( 'slug' => 'menu-panel', 'with_front' => false ),
		'supports'            => array( 'title', 'editor', 'revisions', 'custom-fields' ),
		'map_meta_cap'        => true,
		'capability_type'     => 'page',
	) );
	register_post_type( 'gogh_message', array(
		'label'        => __( 'Messages', 'gogh-editor' ),
		'labels'       => array(
			'name'          => __( 'Messages', 'gogh-editor' ),
			'singular_name' => __( 'Message', 'gogh-editor' ),
			// the sidebar wears the FRONT-END name — folks added a contact
			// form, so that is the word they scan for (James's call); the
			// book itself stays Messages, and landing-page sign-ups land
			// here too (one inbox, never two)
			'menu_name'     => __( 'Contact form', 'gogh-editor' ),
		),
		'public'       => false,
		'show_ui'      => true,
		'show_in_menu' => true,
		'menu_icon'    => 'dashicons-email',
		'supports'     => array( 'title', 'editor' ),
		'capabilities' => array( 'create_posts' => 'do_not_allow' ), // messages arrive, they are not authored
		'map_meta_cap' => true,
	) );
	register_block_type( 'gogh/form', array(
		'api_version'     => 3,
		'title'           => __( 'Form', 'gogh-editor' ),
		'render_callback' => 'gogh_form_render',
		'attributes'      => array(
			'heading' => array( 'type' => 'string', 'default' => '' ),
			'button'  => array( 'type' => 'string', 'default' => '' ),
		),
	) );
} );
// the panel's pretty URL (menu-panel/…) needs its rewrite rule, and a fresh
// install has none until something flushes: the mega menu button then lands
// on WordPress's 404 guess — the PAGE with the nearest slug (Playground
// showed it: "Collection" opened the Collection page, not the panel). Flush
// once per plugin version, after every post type above is registered.
add_action( 'init', function () {
	if ( get_option( 'gogh_rewrite_stamp' ) !== GOGH_VERSION ) {
		flush_rewrite_rules( false );
		update_option( 'gogh_rewrite_stamp', GOGH_VERSION, false );
	}
}, 99 );

// the Messages list answers at a glance: who, how to reply, from where
add_filter( 'manage_gogh_message_posts_columns', function ( $cols ) {
	return array(
		'cb'       => isset( $cols['cb'] ) ? $cols['cb'] : '<input type="checkbox" />',
		'title'    => __( 'From', 'gogh-editor' ),
		'msg_mail' => __( 'Email', 'gogh-editor' ),
		'msg_body' => __( 'Message', 'gogh-editor' ),
		'msg_page' => __( 'From page', 'gogh-editor' ),
		'date'     => __( 'When', 'gogh-editor' ),
	);
} );
add_action( 'manage_gogh_message_posts_custom_column', function ( $col, $post_id ) {
	if ( 'msg_mail' === $col ) {
		$em = get_post_meta( $post_id, '_gogh_msg_email', true );
		echo $em ? '<a href="mailto:' . esc_attr( $em ) . '">' . esc_html( $em ) . '</a>' : '—';
	} elseif ( 'msg_body' === $col ) {
		if ( 'signup' === get_post_meta( $post_id, '_gogh_msg_kind', true ) ) {
			$utm = get_post_meta( $post_id, '_gogh_msg_utm', true );
			echo '<em>' . esc_html__( 'Sign-up', 'gogh-editor' ) . ( $utm ? ' · ' . esc_html( $utm ) : '' ) . '</em>';
		} else {
			echo esc_html( wp_trim_words( get_post_field( 'post_content', $post_id ), 16, '…' ) );
		}
	} elseif ( 'msg_page' === $col ) {
		$pid = (int) get_post_meta( $post_id, '_gogh_msg_page', true );
		if ( $pid && get_post( $pid ) ) {
			echo '<a href="' . esc_url( get_permalink( $pid ) ) . '">' . esc_html( get_the_title( $pid ) ) . '</a>';
		}
	}
}, 10, 2 );

// ---------- reading the mail ----------
// a message is READ, not edited — clicking one opens a letter, never an
// Edit Post screen with an Update button (James: "i cant read the
// messages"). The row's Edit verb becomes Read; the letter offers a
// mailto reply and a way back.
add_filter( 'get_edit_post_link', function ( $link, $post_id ) {
	$post = get_post( $post_id );
	if ( $post && 'gogh_message' === $post->post_type && current_user_can( 'edit_post', $post->ID ) ) {
		return admin_url( 'admin.php?page=gogh-message-read&msg=' . $post->ID );
	}
	return $link;
}, 10, 2 );
add_filter( 'post_row_actions', function ( $actions, $post ) {
	if ( 'gogh_message' === $post->post_type && isset( $actions['edit'] ) ) {
		$actions['edit'] = '<a href="' . esc_url( admin_url( 'admin.php?page=gogh-message-read&msg=' . $post->ID ) ) . '">' .
			esc_html__( 'Read', 'gogh-editor' ) . '</a>';
	}
	return $actions;
}, 10, 2 );
add_action( 'admin_menu', function () {
	add_submenu_page( '', __( 'Read message', 'gogh-editor' ), '', 'edit_posts', 'gogh-message-read', function () {
		$msg = get_post( absint( isset( $_GET['msg'] ) ? $_GET['msg'] : 0 ) ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only view, capability-checked below
		if ( ! $msg || 'gogh_message' !== $msg->post_type || ! current_user_can( 'edit_post', $msg->ID ) ) {
			wp_die( esc_html__( 'That message is not here any more.', 'gogh-editor' ) );
		}
		$email  = get_post_meta( $msg->ID, '_gogh_msg_email', true );
		$pid    = (int) get_post_meta( $msg->ID, '_gogh_msg_page', true );
		$utm    = get_post_meta( $msg->ID, '_gogh_msg_utm', true );
		$signup = 'signup' === get_post_meta( $msg->ID, '_gogh_msg_kind', true );
		echo '<div class="wrap" style="max-width:680px">';
		echo '<p style="margin:18px 0 6px"><a href="' . esc_url( admin_url( 'edit.php?post_type=gogh_message' ) ) . '">&larr; ' . esc_html__( 'All messages', 'gogh-editor' ) . '</a></p>';
		echo '<div style="background:#fff;border:1px solid #dcdcde;border-radius:12px;padding:28px 32px;box-shadow:0 1px 2px rgba(0,0,0,.04)">';
		echo '<h1 style="margin:0 0 2px;font-size:26px">' . esc_html( get_the_title( $msg ) ) . '</h1>';
		echo '<p style="margin:0 0 18px;color:#646970">';
		echo esc_html( $signup ? __( 'Signed up', 'gogh-editor' ) : __( 'Wrote', 'gogh-editor' ) ) . ' ' . esc_html( human_time_diff( get_post_time( 'U', true, $msg ), time() ) ) . ' ' . esc_html__( 'ago', 'gogh-editor' );
		if ( $pid && get_post( $pid ) ) {
			echo ' &middot; ' . esc_html__( 'from', 'gogh-editor' ) . ' <a href="' . esc_url( get_permalink( $pid ) ) . '">' . esc_html( get_the_title( $pid ) ) . '</a>';
		}
		if ( $utm ) {
			echo ' &middot; ' . esc_html( $utm );
		}
		echo '</p>';
		if ( '' !== trim( (string) $msg->post_content ) ) {
			echo '<div style="font-size:15px;line-height:1.7;white-space:pre-line;border-top:1px solid #f0f0f1;padding-top:18px">' . esc_html( $msg->post_content ) . '</div>';
		} else {
			echo '<p style="color:#646970;font-style:italic;border-top:1px solid #f0f0f1;padding-top:18px;margin:0">' . esc_html__( 'A sign-up — no message, just the hand raised.', 'gogh-editor' ) . '</p>';
		}
		echo '<p style="margin:24px 0 0;display:flex;gap:14px;align-items:center">';
		if ( $email ) {
			echo '<a class="button button-primary" href="mailto:' . esc_attr( $email ) . '">' . esc_html__( 'Reply by email', 'gogh-editor' ) . '</a>';
			echo '<span style="color:#646970">' . esc_html( $email ) . '</span>';
		}
		echo '<a style="margin-left:auto;color:#b32d2e" href="' . esc_url( get_delete_post_link( $msg->ID ) ) . '">' . esc_html__( 'Trash', 'gogh-editor' ) . '</a>';
		echo '</p></div></div>';
	} );
} );
// the book walks out as a spreadsheet — one link, one CSV
add_filter( 'views_edit-gogh_message', function ( $views ) {
	$views['gogh_csv'] = '<a href="' . esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=gogh_messages_csv' ), 'gogh_messages_csv' ) ) . '">' .
		esc_html__( 'Export CSV', 'gogh-editor' ) . '</a>';
	return $views;
} );
add_action( 'admin_post_gogh_messages_csv', function () {
	if ( ! current_user_can( 'edit_others_posts' ) || ! wp_verify_nonce( sanitize_key( isset( $_GET['_wpnonce'] ) ? $_GET['_wpnonce'] : '' ), 'gogh_messages_csv' ) ) {
		wp_die( esc_html__( 'That export link has expired — open the Contact form book and try again.', 'gogh-editor' ) );
	}
	$rows = get_posts( array(
		'post_type'      => 'gogh_message',
		'post_status'    => 'private',
		'posts_per_page' => -1,
		'orderby'        => 'date',
		'order'          => 'DESC',
	) );
	header( 'Content-Type: text/csv; charset=utf-8' );
	header( 'Content-Disposition: attachment; filename=messages-' . gmdate( 'Y-m-d' ) . '.csv' );
	$out = fopen( 'php://output', 'w' );
	fputcsv( $out, array( 'Date', 'Name', 'Email', 'Kind', 'Message', 'Page', 'Campaign' ) );
	foreach ( $rows as $r ) {
		$pid = (int) get_post_meta( $r->ID, '_gogh_msg_page', true );
		fputcsv( $out, array(
			get_post_time( 'Y-m-d H:i', false, $r ),
			get_the_title( $r ),
			get_post_meta( $r->ID, '_gogh_msg_email', true ),
			'signup' === get_post_meta( $r->ID, '_gogh_msg_kind', true ) ? 'Sign-up' : 'Message',
			$r->post_content,
			$pid ? get_the_title( $pid ) : '',
			get_post_meta( $r->ID, '_gogh_msg_utm', true ),
		) );
	}
	exit;
} );

function gogh_form_render( $attrs ) {
	$heading = trim( (string) ( isset( $attrs['heading'] ) ? $attrs['heading'] : '' ) );
	$button  = trim( (string) ( isset( $attrs['button'] ) ? $attrs['button'] : '' ) );
	if ( '' === $button ) {
		$button = __( 'Send', 'gogh-editor' );
	}
	$thanks = isset( $_GET['gogh-thanks'] ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- display state only
	$out    = '<div class="gogh-form" id="gogh-form">';
	if ( '' !== $heading ) {
		$out .= '<p class="gogh-form-heading">' . esc_html( $heading ) . '</p>';
	}
	if ( $thanks ) {
		$out .= '<p class="gogh-form-thanks">' . esc_html__( 'Thank you — your message is on its way.', 'gogh-editor' ) . '</p></div>';
		return $out;
	}
	$out .= '<form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '">' .
		'<input type="hidden" name="action" value="gogh_form_message" />' .
		wp_nonce_field( 'gogh_form_message', '_gogh_form', true, false ) .
		'<input type="hidden" name="fm_page" value="' . esc_attr( get_the_ID() ) . '" />' .
		// the honeypot: humans never see it, bots always fill it
		'<input type="text" name="fm_website" class="gogh-form-hp" tabindex="-1" autocomplete="off" aria-hidden="true" />' .
		'<div class="gogh-form-row">' .
		'<input type="text" name="fm_name" required placeholder="' . esc_attr__( 'Your name', 'gogh-editor' ) . '" />' .
		'<input type="email" name="fm_email" required placeholder="' . esc_attr__( 'Your email', 'gogh-editor' ) . '" />' .
		'</div>' .
		'<textarea name="fm_message" required rows="5" placeholder="' . esc_attr__( 'Your message…', 'gogh-editor' ) . '"></textarea>' .
		'<div class="gogh-form-foot"><button type="submit">' . esc_html( $button ) . '</button>' .
		'<span class="gogh-form-note">' . esc_html__( 'Goes straight to this site — nowhere else.', 'gogh-editor' ) . '</span></div>' .
		'</form></div>';
	return $out;
}

function gogh_form_handle_message() {
	if ( ! isset( $_POST['_gogh_form'] ) || ! wp_verify_nonce( sanitize_key( $_POST['_gogh_form'] ), 'gogh_form_message' ) ) {
		wp_die( esc_html__( 'That form has expired — please go back and try again.', 'gogh-editor' ) );
	}
	$back = wp_get_referer() ? remove_query_arg( 'gogh-thanks', wp_get_referer() ) : home_url( '/' );
	if ( ! empty( $_POST['fm_website'] ) ) { // the honeypot caught something
		wp_safe_redirect( add_query_arg( 'gogh-thanks', '1', $back ) . '#gogh-form' );
		exit;
	}
	$email = sanitize_email( wp_unslash( isset( $_POST['fm_email'] ) ? $_POST['fm_email'] : '' ) );
	$msg   = sanitize_textarea_field( wp_unslash( isset( $_POST['fm_message'] ) ? $_POST['fm_message'] : '' ) );
	if ( ! is_email( $email ) || '' === trim( $msg ) ) {
		wp_die( esc_html__( 'The email or message did not look right — please go back and try again.', 'gogh-editor' ) );
	}
	$name = sanitize_text_field( wp_unslash( isset( $_POST['fm_name'] ) ? $_POST['fm_name'] : '' ) );
	$page = absint( isset( $_POST['fm_page'] ) ? $_POST['fm_page'] : 0 );
	$id   = wp_insert_post( array(
		'post_type'    => 'gogh_message',
		'post_status'  => 'private',
		'post_title'   => $name ? $name : $email,
		'post_content' => $msg,
	) );
	if ( $id && ! is_wp_error( $id ) ) {
		update_post_meta( $id, '_gogh_msg_email', $email );
		update_post_meta( $id, '_gogh_msg_page', $page );
		wp_mail(
			get_option( 'admin_email' ),
			sprintf( /* translators: %s: site name */ __( 'New message on %s', 'gogh-editor' ), get_bloginfo( 'name' ) ),
			sprintf( "%s <%s>\n\n%s\n\n%s", $name, $email, $msg, $page ? get_permalink( $page ) : '' )
		);
	}
	wp_safe_redirect( add_query_arg( 'gogh-thanks', '1', $back ) . '#gogh-form' );
	exit;
}
add_action( 'admin_post_gogh_form_message', 'gogh_form_handle_message' );
add_action( 'admin_post_nopriv_gogh_form_message', 'gogh_form_handle_message' );

// the form wears the theme: inputs inked from currentColor, the button
// from the palette's contrast — composes with any site style
function gogh_form_css() {
	return
		'.gogh-form { width: 100%; }' .
		'.gogh-form-heading { font-weight: 650; margin: 0 0 0.8em; }' .
		'.gogh-form-row { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }' .
		'.gogh-form-row input { flex: 1 1 180px; min-width: 0; }' .
		'.gogh-form input, .gogh-form textarea { box-sizing: border-box; padding: 0.85em 1em; border-radius: 10px; border: 1.5px solid color-mix(in srgb, currentColor 30%, transparent); background: color-mix(in srgb, var(--wp--preset--color--base, #fff) 85%, transparent); color: inherit; font: inherit; }' .
		'.gogh-form textarea { width: 100%; resize: vertical; }' .
		'.gogh-form ::placeholder { color: color-mix(in srgb, currentColor 55%, transparent); }' .
		'.gogh-form-foot { display: flex; align-items: center; gap: 14px; margin-top: 12px; flex-wrap: wrap; }' .
		'.gogh-form-foot button { padding: 0.85em 1.8em; border: 0; border-radius: 10px; font: inherit; font-weight: 650; cursor: pointer; background: var(--wp--preset--color--contrast, #16181c); color: var(--wp--preset--color--base, #fff); }' .
		'.gogh-form-foot button:hover { filter: brightness(1.12); }' .
		'.gogh-form-foot .gogh-form-fbtn { padding: 0.85em 1.8em; border-radius: 10px; font-weight: 650; background: var(--wp--preset--color--contrast, #16181c); color: var(--wp--preset--color--base, #fff); }' .
		'.gogh-form-note { font-size: 0.82em; opacity: 0.6; }' .
		'.gogh-form-thanks { font-weight: 650; }' .
		'.gogh-form-hp { position: absolute !important; left: -9999px !important; width: 1px; height: 1px; opacity: 0; }' .
		'@media (max-width: 560px) { .gogh-form-row { flex-direction: column; } .gogh-form-foot button { width: 100%; } }';
}
add_action( 'wp_enqueue_scripts', function () {
	wp_register_style( 'gogh-form', false, array(), null );
	wp_enqueue_style( 'gogh-form' );
	wp_add_inline_style( 'gogh-form', gogh_form_css() );
} );

/**
 * The menu behind the ☰ — WordPress's default overlay is a blank white
 * sheet with small links in a corner. If gogh offers the hamburger as a
 * layout, the moment after the tap must be designed (James: "make this
 * look beautiful"): the theme's own ground and ink, big centred type, a
 * soft round close, and a staggered arrival. Theme-adaptive throughout —
 * presets only, so it re-dresses with the site style. The same overlay
 * folds the phone menu on every header, so phones get it too.
 */
// ---------- mobile menu style: one site-wide choice, layout + ground ----------
// (James: "it would be cool to have a few different style options for the
// mobile menu"). Stored as one option; worn as two body classes so the
// editor can audition by swapping classes and the CSS below is the same
// stylesheet for editing and for visitors.
function gogh_menu_style() {
	$o = get_option( 'gogh_menu_style', array() );
	$layouts = array( 'stack', 'centred', 'drawer', 'sheet' );
	$grounds = array( 'light', 'dark', 'brand' );
	$layout  = isset( $o['layout'] ) && in_array( $o['layout'], $layouts, true ) ? $o['layout'] : 'stack';
	$ground  = isset( $o['ground'] ) && in_array( $o['ground'], $grounds, true ) ? $o['ground'] : 'light';
	// what phones want at the foot of the menu, and (rarely) a menu of their own
	$phone_menu = isset( $o['phoneMenu'] ) ? (int) $o['phoneMenu'] : 0;
	if ( $phone_menu && 'wp_navigation' !== get_post_type( $phone_menu ) ) {
		$phone_menu = 0;
	}
	return array(
		'layout'    => $layout,
		'ground'    => $ground,
		'phone'     => isset( $o['phone'] ) ? sanitize_text_field( $o['phone'] ) : '',
		'email'     => isset( $o['email'] ) && is_email( $o['email'] ) ? sanitize_email( $o['email'] ) : '',
		'account'   => ! empty( $o['account'] ),
		'phoneMenu' => $phone_menu,
	);
}
add_filter( 'body_class', function ( $classes ) {
	$ms        = gogh_menu_style();
	$classes[] = 'gogh-mm-' . $ms['layout'];
	$classes[] = 'gogh-mmg-' . $ms['ground'];
	if ( $ms['phoneMenu'] ) {
		$classes[] = 'gogh-mm-hasphone';
	}
	return $classes;
} );
function gogh_menu_style_css() {
	$open = '.wp-block-navigation__responsive-container.is-menu-open';
	return
		// GROUNDS — body + class outranks the base rule's own !important
		'body.gogh-mmg-dark ' . $open . ' { background: var(--wp--preset--color--contrast, #141519) !important; color: var(--wp--preset--color--base, #fff) !important; }' .
		'body.gogh-mmg-dark ' . $open . ' .wp-block-navigation-item__content, body.gogh-mmg-dark ' . $open . ' .wp-block-navigation__responsive-container-close { color: inherit !important; }' .
		'body.gogh-mmg-brand ' . $open . ' { background: var(--wp--preset--color--primary, var(--wp--preset--color--accent, var(--wp--preset--color--accent-1, var(--wp--preset--color--main-accent, var(--wp--preset--color--primary-accent, var(--wp--preset--color--secondary, var(--wp--preset--color--contrast, #141519))))))) !important; color: var(--wp--preset--color--base, #fff) !important; }' .
		'body.gogh-mmg-brand ' . $open . ' .wp-block-navigation-item__content, body.gogh-mmg-brand ' . $open . ' .wp-block-navigation__responsive-container-close { color: inherit !important; }' .
		// CENTRED — every line centred on its own axis, not a left column parked mid-page
		'body.gogh-mm-centred ' . $open . ' .wp-block-navigation__container { align-items: center !important; }' .
		'body.gogh-mm-centred ' . $open . ' .wp-block-navigation-item { justify-content: center; text-align: center; }' .
		// DRAWER — slides in from the right, reads top-down like a list
		'body.gogh-mm-drawer ' . $open . ' { inset: 0 0 0 auto !important; left: auto !important; width: min(440px, 88vw) !important; box-shadow: -24px 0 60px rgba(0,0,0,0.22); animation: gogh-menu-drawer 0.36s cubic-bezier(.2,.7,.2,1) both !important; padding-top: clamp(72px, 12vh, 120px) !important; }' .
		'body.gogh-mm-drawer ' . $open . ' .wp-block-navigation__responsive-container-content { align-items: flex-start !important; justify-content: flex-start !important; }' .
		'body.gogh-mm-drawer ' . $open . ' .wp-block-navigation__container { align-items: flex-start !important; text-align: left !important; gap: clamp(8px, 1.6vh, 18px) !important; }' .
		'body.gogh-mm-drawer ' . $open . ' .wp-block-navigation-item__content { font-size: clamp(22px, 3.6vw, 34px) !important; }' .
		// SHEET — rises from the bottom, rounded shoulders, the page still visible above
		'body.gogh-mm-sheet ' . $open . ' { inset: auto 0 0 0 !important; top: auto !important; height: auto !important; max-height: 82vh !important; border-radius: 28px 28px 0 0 !important; box-shadow: 0 -24px 60px rgba(0,0,0,0.22); animation: gogh-menu-sheet 0.4s cubic-bezier(.2,.7,.2,1) both !important; padding: clamp(28px, 5vh, 48px) clamp(24px, 6vw, 64px) clamp(36px, 6vh, 64px) !important; }' .
		'body.gogh-mm-sheet ' . $open . '::before { content: ""; position: absolute; top: 12px; left: 50%; width: 44px; height: 5px; border-radius: 999px; background: currentColor; opacity: 0.28; transform: translateX(-50%); }' .
		'body.gogh-mm-sheet ' . $open . ' .wp-block-navigation__responsive-container-content { align-items: center !important; justify-content: flex-start !important; }' .
		'body.gogh-mm-sheet ' . $open . ' .wp-block-navigation__container { align-items: center !important; text-align: center !important; gap: clamp(8px, 1.6vh, 18px) !important; }' .
		'body.gogh-mm-sheet ' . $open . ' .wp-block-navigation-item { justify-content: center; }' .
		'body.gogh-mm-sheet ' . $open . ' .wp-block-navigation-item__content { font-size: clamp(22px, 3.6vw, 36px) !important; }' .
		'@keyframes gogh-menu-drawer { from { transform: translateX(100%); } to { transform: none; } }' .
		'@keyframes gogh-menu-sheet { from { transform: translateY(100%); } to { transform: none; } }' .
		'@media (prefers-reduced-motion: reduce) { body.gogh-mm-drawer ' . $open . ', body.gogh-mm-sheet ' . $open . ' { animation: none !important; } }';
}
// ---------- the header's dressing, on EVERY front-end page ----------
// These rules lived in gogh-base, which only loads on singular gogh pages —
// so the shop archive, cart, checkout and the blog index wore a broken
// header (James: 'header broken on shop page'). A header is site-wide.
function gogh_chrome_css() {
	return
		'header.wp-block-template-part:not(:has(.gogh-chrome-preview)):has(.gogh-header-overlay), header.wp-block-template-part:has(.gogh-chrome-preview .gogh-header-overlay) { position: absolute; top: var(--wp-admin--admin-bar--height, 0px); left: 0; right: 0; z-index: 40; background: transparent; }' .
		// no automatic scrim: transparent means TRANSPARENT ("transparent not
		// transparent" — over a pale hero the helpful gradient read as a grey
		// smear). The Look row's custom colour + see-through dial is the
		// scrim now, on demand, in the user's own colour.

		// the row declares its text colour; links inherit it — element-level
		// link CSS does not survive every render context (REST previews)
		'.gogh-hrow.has-text-color a, .gogh-hrow.has-text-color .wp-block-navigation-item__content, .gogh-hrow.has-text-color .wp-block-navigation { color: inherit !important; }' .
		'#wpadminbar .gogh-ab-ic { display: inline-block; vertical-align: -2px; margin-right: 7px; }' .
		// when gogh sizes the nav, the links FOLLOW — theme rules on the
		// anchors otherwise out-rank the container's size
		'.wp-block-navigation[style*="font-size"] a { font-size: inherit; }' .
		// a real logo makes the text title redundant — one identity, not two
		// one identity, not two: a real logo image hides the redundant text
		// title — scoped to the whole header part, because some layouts
		// (Centred) don't wear .gogh-hrow and showed BOTH ("two logos")
		'header.wp-block-template-part:has(.wp-block-site-logo img) .wp-block-site-title, .gogh-hrow:has(.wp-block-site-logo img) .wp-block-site-title { display: none; }' .
		// sticky pins the HEADER ELEMENT (the inner group has zero travel);
		// theme-independent, admin-bar aware
		'header.wp-block-template-part:not(:has(.gogh-chrome-preview)):has(.gogh-sticky), header.wp-block-template-part:has(.gogh-chrome-preview .gogh-sticky) { position: sticky; top: var(--wp-admin--admin-bar--height, 0px); z-index: 90; }' .
		// transparent AND sticky: sticky alone keeps its flow space (the
		// grey band that hid the float through three bug reports) — fixed
		// floats over the hero AND stays through the scroll
		'header.wp-block-template-part:not(:has(.gogh-chrome-preview)):has(.gogh-header-overlay):has(.gogh-sticky), header.wp-block-template-part:has(.gogh-chrome-preview .gogh-header-overlay):has(.gogh-chrome-preview .gogh-sticky) { position: fixed; top: var(--wp-admin--admin-bar--height, 0px); left: 0; right: 0; z-index: 90; }' .
		// WooCommerce block-hooks append cart/account icons after the nav in
		// every header — give them a deliberate seat instead of a random one:
		// nav pushes right, icons tuck in beside it, stacks stay centred
		'.gogh-hrow { align-items: center; gap: 1.1rem; }' .
		'.gogh-hrow > .wp-block-navigation { margin-left: auto; }' .
		'.gogh-hrow > [class*="mini-cart"], .gogh-hrow > [class*="customer-account"] { flex: none; }' .
		'.gogh-hstack > [class*="mini-cart"], .gogh-hstack > [class*="customer-account"] { align-self: center; }' .
		'';
}
/**
 * The overlay is the phone menu; the bar is the desktop one. An item can
 * live in either or both (a class on its link block); the extras (Call,
 * Email, My account) and a separate phone menu join the overlay at render.
 */
add_filter( 'render_block_core/navigation', function ( $html ) {
	static $inside = false;
	if ( $inside || false === strpos( $html, 'wp-block-navigation__responsive-container-content' ) ) {
		return $html;
	}
	$ms    = gogh_menu_style();
	$extra = '';
	if ( $ms['phoneMenu'] ) {
		$inside = true;
		$alt    = do_blocks( '<!-- wp:navigation {"ref":' . (int) $ms['phoneMenu'] . ',"overlayMenu":"never"} /-->' );
		$inside = false;
		if ( preg_match( '#<ul[^>]*class="[^"]*wp-block-navigation__container[^"]*"[^>]*>[\s\S]*</ul>#', $alt, $mm ) ) {
			$extra .= preg_replace( '/class="wp-block-navigation__container/', 'class="wp-block-navigation__container gogh-mm-phonelist', $mm[0], 1 );
		}
	}
	$links = array();
	if ( $ms['phone'] ) {
		$links[] = '<a href="tel:' . esc_attr( preg_replace( '/[^0-9+]/', '', $ms['phone'] ) ) . '"><span class="gogh-mm-extra-k">' . esc_html__( 'Call', 'gogh-editor' ) . '</span>' . esc_html( $ms['phone'] ) . '</a>';
	}
	if ( $ms['email'] ) {
		$links[] = '<a href="mailto:' . esc_attr( $ms['email'] ) . '"><span class="gogh-mm-extra-k">' . esc_html__( 'Email', 'gogh-editor' ) . '</span>' . esc_html( $ms['email'] ) . '</a>';
	}
	if ( $ms['account'] && function_exists( 'wc_get_page_permalink' ) ) {
		$links[] = '<a href="' . esc_url( wc_get_page_permalink( 'myaccount' ) ) . '"><span class="gogh-mm-extra-k">' . esc_html__( 'Account', 'gogh-editor' ) . '</span>' . esc_html__( 'My account', 'gogh-editor' ) . '</a>';
	}
	if ( $links ) {
		$extra .= '<div class="gogh-mm-extras">' . implode( '', $links ) . '</div>';
	}
	if ( '' === $extra ) {
		return $html;
	}
	$at = strpos( $html, 'wp-block-navigation__responsive-container-content' );
	if ( false === $at || ! preg_match( '#</ul>\s*</div>#', $html, $m, PREG_OFFSET_CAPTURE, $at ) ) {
		return $html;
	}
	$pos = $m[0][1] + strlen( '</ul>' );
	return substr( $html, 0, $pos ) . $extra . substr( $html, $pos );
}, 20 );
// a panel's page is for its editor: visitors who reach it go home
add_action( 'template_redirect', function () {
	if ( is_singular( 'gogh_panel' ) && ! current_user_can( 'edit_theme_options' ) ) {
		wp_safe_redirect( home_url( '/' ), 302 );
		exit;
	}
} );
// a new panel wears the blank canvas (no header, no footer — it IS the header's)
add_action( 'save_post_gogh_panel', function ( $post_id ) {
	if ( ! get_page_template_slug( $post_id ) ) {
		update_post_meta( $post_id, '_wp_page_template', 'blank-canvas' ); // plugin templates are stored by bare slug
	}
} );
/**
 * The mega menu at view time: a menu item carrying gogh-panel-N gets its
 * panel (the page's sections, rendered) as a dropdown, a chevron that
 * opens it for keyboards and touch, and — for the phone overlay — the
 * panel's links as a plain list that folds under the item.
 */
add_filter( 'render_block_core/navigation-link', function ( $html, $block ) {
	static $inside = false;
	$cls = isset( $block['attrs']['className'] ) ? (string) $block['attrs']['className'] : '';
	if ( $inside || ! preg_match( '/(?:^|\s)gogh-panel-(\d+)(?:\s|$)/', $cls, $m ) ) {
		return $html;
	}
	// while EDITING, the header stays a plain menu: a panel's sections inside
	// it would read as a freeform header to the editor and hide the menu tools
	// (the panel has a page of its own to be edited on)
	if ( isset( $_GET['gogh-edit'] ) || isset( $_GET['gogh-write'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		return $html;
	}
	$panel = get_post( (int) $m[1] );
	if ( ! $panel || 'gogh_panel' !== $panel->post_type || 'publish' !== $panel->post_status ) {
		return $html;
	}
	$inside = true;
	$inner  = do_blocks( $panel->post_content );
	$inside = false;
	$inner  = trim( (string) $inner );
	if ( '' === $inner ) {
		return $html;
	}
	$id    = 'gogh-mega-' . (int) $panel->ID;
	$label = isset( $block['attrs']['label'] ) ? wp_strip_all_tags( (string) $block['attrs']['label'] ) : '';
	// the panel's links, for phones
	$links = '';
	if ( preg_match_all( '/<a\s[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/is', $inner, $mm, PREG_SET_ORDER ) ) {
		$seen = array();
		$rows = array();
		foreach ( $mm as $a ) {
			$text = trim( wp_strip_all_tags( $a[2] ) );
			$href = html_entity_decode( $a[1] );
			if ( '' === $text || isset( $seen[ $href ] ) || 0 === strpos( $href, '#' ) ) {
				continue;
			}
			$seen[ $href ] = 1;
			$rows[]        = '<li><a href="' . esc_url( $href ) . '">' . esc_html( $text ) . '</a></li>';
			if ( count( $rows ) >= 12 ) {
				break;
			}
		}
		if ( $rows ) {
			$links = '<ul class="gogh-mega-links">' . implode( '', $rows ) . '</ul>';
		}
	}
	$toggle = '<button type="button" class="gogh-mega-toggle" aria-expanded="false" aria-controls="' . esc_attr( $id ) . '" aria-label="' . esc_attr( sprintf( __( 'More under %s', 'gogh-editor' ), $label ) ) . '">' .
		'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg></button>';
	$mega   = '<div class="gogh-mega" id="' . esc_attr( $id ) . '" hidden><div class="gogh-mega-in">' . $inner . '</div></div>';
	$out    = preg_replace( '/class="wp-block-navigation-item /', 'class="wp-block-navigation-item gogh-has-panel ', $html, 1 );
	$at     = strrpos( $out, '</li>' );
	if ( false === $at ) {
		return $html;
	}
	return substr( $out, 0, $at ) . $toggle . $mega . $links . substr( $out, $at );
}, 10, 2 );
function gogh_mega_css() {
	return '.wp-block-navigation-item.gogh-has-panel { position: relative; }' .
		'.gogh-mega-toggle { all: unset; cursor: pointer; display: inline-grid; place-items: center; width: 22px; height: 22px; margin-left: 2px; border-radius: 50%; opacity: 0.7; transition: transform 0.2s, opacity 0.2s; }' .
		'.gogh-mega-toggle:hover, .gogh-mega-toggle:focus-visible { opacity: 1; }' .
		'.gogh-mega-toggle:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }' .
		'.gogh-has-panel.is-open > .gogh-mega-toggle { transform: rotate(180deg); }' .
		// the dropdown: the header's width, the theme's paper, under everything in the header
		'.gogh-mega { position: absolute; z-index: 60; top: 100%; left: 0; width: 100vw; background: var(--wp--preset--color--base, #fff); color: var(--wp--preset--color--contrast, #141519); box-shadow: 0 30px 80px -20px rgba(0,0,0,0.35); border-top: 1px solid color-mix(in srgb, currentColor 10%, transparent); max-height: min(72vh, 760px); overflow: auto; overscroll-behavior: contain; text-align: left; }' .
		'.gogh-mega[hidden] { display: none; }' .
		'@media (prefers-reduced-motion: no-preference) { .gogh-mega { animation: gogh-mega-in 0.18s ease; } @keyframes gogh-mega-in { from { opacity: 0; translate: 0 -6px; } to { opacity: 1; translate: 0 0; } } }' .
		// a section inside the panel fills the panel, never the viewport
		'.gogh-mega .gogh-wrap, .gogh-mega .alignfull, .gogh-mega .alignwide { width: 100% !important; max-width: 100% !important; margin-inline: 0 !important; }' .
		'.gogh-mega .gogh-section a { text-decoration: none; }' .
		'.gogh-mega .gogh-section a:hover { text-decoration: underline; text-underline-offset: 3px; }' .
		// phones: no dropdown — the panel's links fold under the item
		'.gogh-mega-links { display: none; }' .
		'.wp-block-navigation__responsive-container.is-menu-open .gogh-mega { display: none !important; }' .
		'.wp-block-navigation__responsive-container.is-menu-open .gogh-has-panel { flex-wrap: wrap; }' .
		'.wp-block-navigation__responsive-container.is-menu-open .gogh-has-panel.is-open > .gogh-mega-links { display: flex; flex-direction: column; gap: 6px; flex-basis: 100%; list-style: none; margin: 8px 0 6px; padding: 0 0 0 0.6em; }' .
		'.wp-block-navigation__responsive-container.is-menu-open .gogh-mega-links a { font-size: clamp(16px, 2.2vw, 22px) !important; font-weight: 500; opacity: 0.85; text-decoration: none; color: inherit; }' .
		'.wp-block-navigation__responsive-container.is-menu-open .gogh-mega-toggle { width: 36px; height: 36px; margin-left: 6px; }' .
		'.wp-block-navigation__responsive-container.is-menu-open .gogh-mega-toggle svg { width: 20px; height: 20px; }';
}
function gogh_menu_overlay_css() {
	return
		// one menu, two places: phone-only items hide in the bar, desktop-only
		// items hide in the overlay; the extras and a phone menu live only there
		'.wp-block-navigation-item.gogh-only-phone { display: none !important; }' .
