		'.gogh-shop-head-gallery .gogh-shop-title { font-size: clamp(2rem, 4vw, 3rem); margin: 0 0 0.3em; }' .
		'.gogh-shop-desc { max-width: 62ch; opacity: 0.8; }' .
		'.gogh-shop-head-gallery .gogh-shop-desc { margin-inline: auto; text-align: center; }' .
		'.gogh-catchips ul.wc-block-product-categories-list { display: flex; flex-wrap: wrap; gap: 8px; list-style: none; padding: 0; margin: 1.2rem 0 0; }' .
		'.gogh-shop-head-gallery .gogh-catchips ul.wc-block-product-categories-list { justify-content: center; }' .
		'.gogh-catchips ul.wc-block-product-categories-list li { margin: 0; }' .
		'.gogh-shop-head-editorial .gogh-catchips, .gogh-shop-head-editorial .gogh-catchips ul { margin-inline: 0 !important; }' .
		'.gogh-catchips ul.wc-block-product-categories-list a { display: inline-block; padding: 7px 14px; border-radius: 999px; border: 1.5px solid color-mix(in srgb, currentColor 30%, transparent); text-decoration: none; font-size: 0.9em; font-weight: 600; }' .
		'.gogh-catchips ul.wc-block-product-categories-list a:hover { border-color: currentColor; }' .
		'.gogh-shop-toolbar { padding: 0.6rem 0 1rem; border-bottom: 1px solid color-mix(in srgb, currentColor 14%, transparent); margin-bottom: 1.5rem !important; }' .
		'.gogh-shop-toolbar .woocommerce-result-count { margin: 0; opacity: 0.7; }' .
		// Woo's sorting control arrives as the browser's own <select> (James:
		// 'this is kinda ugly') — the theme's type, a quiet pill, a drawn chevron
		'.wc-block-catalog-sorting select, .woocommerce-ordering select, form.woocommerce-ordering select.orderby { appearance: none; -webkit-appearance: none; font: inherit; font-size: 0.92em; color: inherit; background: color-mix(in srgb, currentColor 6%, transparent) no-repeat right 14px center / 12px 12px; background-image: url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 24 24%27 fill=%27none%27 stroke=%27currentColor%27 stroke-width=%272.4%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27%3E%3Cpath d=%27M6 9l6 6 6-6%27/%3E%3C/svg%3E"); border: 1.5px solid color-mix(in srgb, currentColor 22%, transparent); border-radius: 999px; padding: 9px 38px 9px 16px; line-height: 1.2; cursor: pointer; }' .
		'.wc-block-catalog-sorting select:hover, .woocommerce-ordering select:hover { border-color: currentColor; }' .
		'.wc-block-catalog-sorting select:focus-visible, .woocommerce-ordering select:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }' .
		'.woocommerce-ordering { margin: 0; }' .
		'.gogh-shoplook-gallery .wc-block-product-template.is-flex-container { gap: 0.9em; }' .
		'.gogh-shoplook-gallery .wp-block-post-title { font-size: 0.98em; }' .
		'.gogh-shoplook-editorial .wp-block-post-title { font-size: 1.15em; }' .
		'.gogh-shop-side .wp-block-woocommerce-product-filters { position: sticky; top: 110px; }' .
		'@media (max-width: 782px) { .gogh-shop-catalogue { flex-direction: column; } .gogh-shop-side { flex-basis: auto !important; } }' .
		// the story under the buy box: plain words get air above and below;
		// a full-bleed section joins the hero flush (James: 'text looks kinda tight')
		'.gogh-story-slot .entry-content:not(:has(> .gogh-wrap:first-child)) { padding-top: clamp(2.5rem, 6vw, 5rem); }' .
		'.gogh-story-slot .entry-content:not(:has(> .gogh-wrap:last-child)) { padding-bottom: clamp(2rem, 5vw, 4rem); }' .
		// a rails widget's block fills its cell (the widget group is a flex row — a
		// block with no width of its own shrank to 46px and its tiles to nothing)
		'.gogh-widget > .wp-block-woocommerce-product-categories, .gogh-widget > .wp-block-woocommerce-product-collection { flex: 1 1 100%; width: 100%; min-width: 0; }' .
		// category tiles (the Categories section): Woo's category list as doors
		'.gogh-shop-cats ul.wc-block-product-categories-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.25em; list-style: none; padding: 0; margin: 0; }' .
		'.gogh-shop-cats-c2 ul.wc-block-product-categories-list { grid-template-columns: repeat(2, minmax(0, 1fr)); }' .
		'.gogh-shop-cats-c4 ul.wc-block-product-categories-list { grid-template-columns: repeat(4, minmax(0, 1fr)); }' .
		'.gogh-shop-cats.gogh-shop-gap-s ul.wc-block-product-categories-list { gap: 0.6em; } .gogh-shop-cats.gogh-shop-gap-l ul.wc-block-product-categories-list { gap: 2em; }' .
		'.gogh-shop-cats li.wc-block-product-categories-list-item { margin: 0; }' .
		'.gogh-shop-cats li.wc-block-product-categories-list-item > a { position: relative; display: block; aspect-ratio: 4 / 3; border-radius: 12px; overflow: hidden; background: color-mix(in srgb, currentColor 8%, transparent); text-decoration: none; }' .
		// Woo dresses the list for 50px thumbnails; the tile wants the whole picture
		'.gogh-shop-cats .wc-block-product-categories-list-item__image { position: absolute !important; inset: 0 !important; margin: 0 !important; width: 100% !important; max-width: none !important; height: 100% !important; float: none !important; }' .
		'.gogh-shop-cats .wc-block-product-categories-list-item__image img { width: 100% !important; max-width: none !important; height: 100% !important; object-fit: cover; display: block; transition: transform 0.4s ease; }' .
		'.gogh-shop-cats li > a:hover .wc-block-product-categories-list-item__image img { transform: scale(1.04); }' .
		'.gogh-shop-cats .wc-block-product-categories-list-item__name { position: absolute; left: 0; right: 0; bottom: 0; padding: 18px 20px; color: #fff; font-weight: 700; font-size: 1.25em; line-height: 1.2; background: linear-gradient(to top, rgba(0, 0, 0, 0.62), transparent); }' .
		'.gogh-shop-cats .wc-block-product-categories-list-item-count { display: none; }' .
		'@media (max-width: 700px) { .gogh-shop-cats ul.wc-block-product-categories-list { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; } }' .
		'.gogh-shop-empty { border: 1.5px dashed color-mix(in srgb, currentColor 30%, transparent); border-radius: 14px; padding: 56px 24px; text-align: center; max-width: 560px; margin-inline: auto; }' .
		'.gogh-shop-empty-owner { border-style: solid; border-color: color-mix(in srgb, currentColor 14%, transparent); background: color-mix(in srgb, currentColor 4%, transparent); }' .
		'.gogh-shop-empty-eyebrow { display: block; font-style: normal; font-size: 0.72em; letter-spacing: 0.14em; text-transform: uppercase; opacity: 0.55; margin-bottom: 14px; }' .
		'.gogh-shop-empty strong { display: block; font-size: 1.5em; line-height: 1.15; margin-bottom: 8px; }' .
		'.gogh-shop-empty span { display: block; opacity: 0.7; max-width: 38ch; margin-inline: auto; }' .
		'.gogh-shop-empty-cta { margin: 22px 0 0; }' .
		// the category banner: the category's own picture, a Cover with its
		// name and words at the foot (Editorial category look)
		'.gogh-shop-banner { margin-bottom: 1.5rem; }' .
		'.gogh-shop-banner .wp-block-cover__inner-container { padding: 2.5rem 0 2rem; }' .
		'.gogh-shop-banner .gogh-shop-title, .gogh-shop-banner .gogh-shop-desc, .gogh-shop-banner .gogh-shop-desc p { color: #fff; }' .
		'.gogh-shop-banner .gogh-shop-desc { max-width: 48ch; opacity: 0.88; }' .
		'.gogh-shop-banner .gogh-shop-title { margin-top: 0; }';
}
/**
 * The designed empty state. Squarespace shows "No results found" to
 * everyone; gogh answers the person actually looking:
 *   - the OWNER of an empty shop gets an invitation with the one button
 *     that matters (Add a product) and the promise that it lands here;
 *   - a visitor to a shop with nothing in it yet gets a graceful coming-soon;
 *   - an empty CATEGORY names itself and points back to the whole shop;
 *   - filters that match nothing say so and offer to clear.
 */
function gogh_shop_empty_state( $block ) {
	$owner = current_user_can( 'edit_products' );
	$attrs = isset( $block['attrs'] ) && is_array( $block['attrs'] ) ? $block['attrs'] : array();
	$shop  = function_exists( 'wc_get_page_permalink' ) ? wc_get_page_permalink( 'shop' ) : home_url( '/' );
	// which slice of the shop is empty?
	$term = null;
	if ( function_exists( 'is_product_category' ) && ( is_product_category() || is_product_tag() ) ) {
		$term = get_queried_object();
	} elseif ( ! empty( $attrs['query']['taxQuery']['product_cat'][0] ) ) {
		$t = get_term( (int) $attrs['query']['taxQuery']['product_cat'][0], 'product_cat' );
		if ( $t && ! is_wp_error( $t ) ) {
			$term = $t;
		}
	}
	$filtered = false;
	foreach ( array_keys( $_GET ) as $k ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		if ( in_array( $k, array( 'min_price', 'max_price', 'rating_filter', 'filter_stock_status', 'stock_status' ), true ) || 0 === strpos( (string) $k, 'filter_' ) || 0 === strpos( (string) $k, 'query_type_' ) ) {
			$filtered = true;
		}
	}
	$eyebrow = '';
	$title   = '';
	$line    = '';
	$cta     = '';
	$cta_url = '';
	$kind    = 'visitor';
	// a rail narrowed to what's on sale: an empty one is not an empty shop
	$on_sale = ! empty( $attrs['query']['woocommerceOnSale'] );
	if ( $filtered ) {
		$title   = __( 'Nothing matches those filters.', 'gogh-editor' );
		$line    = __( 'Loosen one and the shelves fill back up.', 'gogh-editor' );
		$cta     = __( 'Clear filters', 'gogh-editor' );
		$cta_url = strtok( (string) ( $_SERVER['REQUEST_URI'] ?? '' ), '?' ) ?: $shop; // phpcs:ignore
		$cta_url = home_url( $cta_url );
		$kind    = 'filtered';
	} elseif ( $on_sale ) {
		$title = __( 'Nothing is on sale right now.', 'gogh-editor' );
		if ( $owner ) {
			$eyebrow = __( 'Only you can see this', 'gogh-editor' );
			$line    = __( 'Put a sale price on a product and it appears here, in this look.', 'gogh-editor' );
			$cta     = __( 'Manage products', 'gogh-editor' );
			$cta_url = admin_url( 'edit.php?post_type=product' );
			$kind    = 'owner';
		} else {
			$line    = __( 'The rest of the shop is open.', 'gogh-editor' );
			$cta     = __( 'Browse the whole shop', 'gogh-editor' );
			$cta_url = $shop;
		}
	} elseif ( $term ) {
		if ( $owner ) {
			$eyebrow = __( 'Only you can see this', 'gogh-editor' );
			/* translators: %s: category name */
			$title   = sprintf( __( 'Nothing in %s yet.', 'gogh-editor' ), $term->name );
			$line    = __( 'Add a product and put it in this category — it shows up here, in this look, with nothing else to set up.', 'gogh-editor' );
			$cta     = __( 'Add a product', 'gogh-editor' );
			$cta_url = admin_url( 'post-new.php?post_type=product' );
			$kind    = 'owner';
		} else {
			/* translators: %s: category name */
			$title   = sprintf( __( 'Nothing in %s just yet.', 'gogh-editor' ), $term->name );
			$line    = __( 'The rest of the shop is open.', 'gogh-editor' );
			$cta     = __( 'Browse the whole shop', 'gogh-editor' );
			$cta_url = $shop;
		}
	} elseif ( $owner ) {
		$eyebrow = __( 'Only you can see this', 'gogh-editor' );
		$title   = __( 'Your shop is ready for its first product.', 'gogh-editor' );
		$line    = __( 'A name and a price make it sellable. Publish it and it appears right here.', 'gogh-editor' );
		$cta     = __( 'Add a product', 'gogh-editor' );
		$cta_url = admin_url( 'post-new.php?post_type=product' );
		$kind    = 'owner';
	} else {
		$title = __( 'New things are on their way.', 'gogh-editor' );
		$line  = __( 'The shop opens soon — check back shortly.', 'gogh-editor' );
	}
	$out = '<div class="gogh-shop-empty gogh-shop-empty-' . esc_attr( $kind ) . '">';
	if ( $eyebrow ) {
		$out .= '<em class="gogh-shop-empty-eyebrow">' . esc_html( $eyebrow ) . '</em>';
	}
	$out .= '<strong>' . esc_html( $title ) . '</strong><span>' . esc_html( $line ) . '</span>';
	if ( $cta && $cta_url ) {
		$out .= '<p class="gogh-shop-empty-cta"><a class="wp-element-button wp-block-button__link" href="' . esc_url( $cta_url ) . '">' . esc_html( $cta ) . '</a></p>';
	}
	return $out . '</div>';
}
add_filter( 'render_block_woocommerce/product-collection', function ( $html, $block ) {
	$cls = isset( $block['attrs']['className'] ) ? (string) $block['attrs']['className'] : '';
	if ( false === strpos( $cls, 'gogh-shop' ) ) {
		return $html;
	}
	// no products rendered → the designed empty state, in the theme's own ink
	if ( false === strpos( $html, 'wc-block-product' ) || false === strpos( $html, '<li' ) ) {
		return '<div class="wp-block-woocommerce-product-collection ' . esc_attr( $cls ) . '">' . gogh_shop_empty_state( $block ) . '</div>';
	}
	return $html;
}, 10, 2 );
add_action( 'wp_enqueue_scripts', function () {
	wp_register_style( 'gogh-menu', false, array(), null );
	wp_enqueue_style( 'gogh-menu' );
	wp_add_inline_style( 'gogh-menu', gogh_chrome_css() . gogh_menu_overlay_css() . gogh_menu_style_css() . gogh_mega_css() );
	if ( class_exists( 'WooCommerce' ) ) {
		wp_add_inline_style( 'gogh-menu', gogh_shop_css() );
	}
} );

function gogh_reading_styles() {
	return array( 'magazine', 'journal', 'essay', 'gazette', 'photostory', 'feature', 'cover', 'manual' ); // '' = the theme's own default
}
add_action( 'init', function () {
	// the cover's chosen slice: 0 = top of the photo, 100 = bottom
	register_post_meta( 'post', '_gogh_cover_pos', array(
		'show_in_rest'  => true,
		'single'        => true,
		'type'          => 'integer',
		'default'       => 50,
		'sanitize_callback' => function ( $v ) {
			return max( 0, min( 100, (int) $v ) );
		},
		'auth_callback' => function ( $allowed, $meta_key, $post_id ) {
			return current_user_can( 'edit_post', $post_id );
		},
	) );
	register_post_meta( 'post', '_gogh_post_style', array(
		'show_in_rest'  => true,
		'single'        => true,
		'type'          => 'string',
		'default'       => '',
		'sanitize_callback' => function ( $v ) {
			return in_array( $v, gogh_reading_styles(), true ) ? $v : '';
		},
		'auth_callback' => function ( $allowed, $meta_key, $post_id ) {
			return current_user_can( 'edit_post', $post_id );
		},
	) );
} );
add_filter( 'body_class', function ( $classes ) {
	if ( is_singular( 'post' ) ) {
		$style = get_post_meta( get_the_ID(), '_gogh_post_style', true );
		if ( $style && in_array( $style, gogh_reading_styles(), true ) ) {
			$classes[] = 'gogh-read-' . $style;
		}
	}
	return $classes;
} );
// the cover look's raw materials, served on every post whether or not it
// wears the look yet — the write room auditions by flipping the body
// class, and the image must already be on the table when it does
add_action( 'wp_enqueue_scripts', function () {
	if ( ! is_singular( 'post' ) ) {
		return;
	}
	$post = get_post();
	$img  = get_the_post_thumbnail_url( $post, 'full' );
	if ( ! $img && preg_match( '/<img[^>]+src="([^"]+)"/', $post->post_content, $m ) ) {
		$img = $m[1]; // the first picture stands in for a missing featured image
	}
	$author = get_the_author_meta( 'display_name', $post->post_author );
	$byline = trim( ( $author ? $author . ' · ' : '' ) . get_the_date( '', $post ) );
	$pos    = (int) get_post_meta( $post->ID, '_gogh_cover_pos', true );
	$pos    = max( 0, min( 100, $pos ? $pos : 50 ) );
	$css    = 'body { ' .
		( $img ? '--gogh-cover-img: url(' . esc_url( $img ) . '); ' : '' ) .
		'--gogh-cover-pos: ' . $pos . '%; ' .
		'--gogh-cover-byline: "' . str_replace( array( '"', '\\' ), '', $byline ) . '"; }';
	wp_register_style( 'gogh-cover-vars', false, array(), null );
	wp_enqueue_style( 'gogh-cover-vars' );
	wp_add_inline_style( 'gogh-cover-vars', $css );
} );
// the broadsheet gate: gogh measures the post so looks can respond to
// length. Between the bounds the whole piece fits a screen or so and
// newspaper columns work; too short and columns are silly, too long and
// the reader would scroll down one column and back up for the next.
add_filter( 'body_class', function ( $classes ) {
	if ( is_singular( 'post' ) ) {
		$text  = wp_strip_all_tags( get_post_field( 'post_content', get_the_ID() ), true );
		$words = count( preg_split( '/\s+/u', trim( $text ), -1, PREG_SPLIT_NO_EMPTY ) );
		if ( $words >= 120 && $words <= 460 ) {
			$classes[] = 'gogh-short';
		}
	}
	return $classes;
} );
/**
 * The looks themselves. Scoped by body class so the write room auditions by
 * flipping the class — the room IS the post, so the preview is the truth.
 */
function gogh_reading_style_css() {
	return
		// MAGAZINE — the feature treatment: a big centred title with a rule
		// beneath, a lede-sized opener with a drop cap, centred pull-quotes.
		// Unmistakable within one screen of any post.
		'.gogh-read-magazine .wp-block-post-title { text-align: center; font-size: clamp(3rem, 7vw, 4.8rem); line-height: 1.02; letter-spacing: -0.025em; max-width: 16ch; margin-inline: auto; text-wrap: balance; padding-bottom: 0.45em; position: relative; }' .
		'.gogh-read-magazine .wp-block-post-title::after { content: ""; position: absolute; left: 50%; bottom: 0; transform: translateX(-50%); width: 3.5em; height: 2px; background: currentColor; opacity: 0.55; }' .
		'.gogh-read-magazine .entry-content > p:first-of-type { font-size: 1.18em; line-height: 1.55; }' .
		'.gogh-read-magazine .entry-content > p:first-of-type::first-letter { float: left; font-size: 3.4em; line-height: 0.8; padding: 0.05em 0.12em 0 0; font-weight: 700; }' .
		// initial-letter is the real drop cap: sunk three lines, top on line
		// one, base on line three — the float version stays as the fallback
		'@supports (initial-letter: 3) { .gogh-read-magazine .entry-content > p:first-of-type::first-letter { float: none; font-size: unset; line-height: unset; padding: 0; initial-letter: 3; font-weight: 650; margin-right: 0.16em; } }' .
		'.gogh-read-magazine .entry-content > p, .gogh-read-magazine .entry-content > h2, .gogh-read-magazine .entry-content > h3 { max-width: 68ch; }' .
		'.gogh-read-magazine .entry-content > h2, .gogh-read-magazine .entry-content > h3 { text-align: center; }' .
		'.gogh-read-magazine .entry-content blockquote { font-size: 1.4em; line-height: 1.35; text-align: center; border: 0; max-width: 24ch; margin-inline: auto; }' .
		// image rhythm — the missing half of a look ("not sure it handles
		// images so well"). Print rules: a tall portrait runs NARROWER, never
		// three screens tall. In-column images cap at 72vh with the whole
		// photo visible (width follows, centred; no crop, nothing stored).
		// Deliberate bleeds keep their drama but never exceed a screen.
		'.gogh-read-magazine .entry-content figure.wp-block-image:not(.alignwide):not(.alignfull) img { max-height: 72vh; width: auto; max-width: 100%; margin-inline: auto; }' .
		'.gogh-read-magazine .entry-content figure.wp-block-image:not(.alignwide):not(.alignfull) { text-align: center; }' .
		'.gogh-read-magazine .entry-content figure.wp-block-image.alignwide img, .gogh-read-magazine .entry-content figure.wp-block-image.alignfull:not(.gogh-splash-break) img { max-height: 85vh; object-fit: cover; }' .
		// JOURNAL — the quiet notebook: a small uppercase title with a hanging
		// rule, a distinctly narrow measure, roomier lines, images pulled into
		// the column with soft corners. Reads as a different publication.
		'.gogh-read-journal .wp-block-post-title { font-size: clamp(1.15rem, 2vw, 1.5rem); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; line-height: 1.3; border-bottom: 1px solid color-mix(in srgb, currentColor 25%, transparent); padding-bottom: 0.8em; max-width: 58ch; }' .
		'.gogh-read-journal .entry-content > p, .gogh-read-journal .entry-content > h2, .gogh-read-journal .entry-content > h3 { max-width: 54ch; }' .
		'.gogh-read-journal .entry-content > p { font-size: 0.95em; line-height: 1.85; margin-block-end: 1.6em; }' .
		'.gogh-read-journal .entry-content > h2, .gogh-read-journal .entry-content > h3 { font-size: 1.15em; letter-spacing: 0.06em; text-transform: uppercase; }' .
		'.gogh-read-journal .entry-content blockquote { border-left: 2px solid currentColor; padding-left: 1.2em; font-style: italic; opacity: 0.85; }' .
		'.gogh-read-journal .entry-content figure.wp-block-image.alignwide, .gogh-read-journal .entry-content figure.wp-block-image.alignfull:not(.gogh-splash-break) { width: 100% !important; max-width: 54ch !important; margin-inline: auto !important; }' .
		'.gogh-read-journal .entry-content figure.wp-block-image img { border-radius: 10px; }' .
		// the notebook keeps photos modest: whole image visible, never a
		// screen-filler
		'.gogh-read-journal .entry-content figure.wp-block-image img { max-height: 60vh; width: auto; max-width: 100%; margin-inline: auto; }' .
		'.gogh-read-journal .entry-content figure.wp-block-image { text-align: center; }' .
		// ESSAY — the architecture of calm: a centred, unhurried feature.
		// Lighter title than Magazine (no rule, no shout), a centred
		// standfirst, generous air between everything, and pull-quotes on a
		// soft tinted panel (colour mixed from the theme's own ink, so it
		// composes with any site style).
		'.gogh-read-essay .wp-block-post-title { text-align: center; font-size: clamp(2.4rem, 5.5vw, 3.8rem); font-weight: 500; line-height: 1.08; letter-spacing: -0.015em; max-width: 18ch; margin-inline: auto; text-wrap: balance; }' .
		'.gogh-read-essay .entry-content > p:first-of-type { text-align: center; font-size: 1.15em; line-height: 1.6; max-width: 44ch; margin-inline: auto; opacity: 0.85; }' .
		'.gogh-read-essay .entry-content > p { max-width: 62ch; line-height: 1.75; margin-block-end: 1.5em; }' .
		'.gogh-read-essay .entry-content > h2, .gogh-read-essay .entry-content > h3 { max-width: 62ch; font-size: 1.3em; font-weight: 600; margin-block-start: 2.4em; }' .
		'.gogh-read-essay .entry-content blockquote { border: 0; background: color-mix(in srgb, currentColor 6%, transparent); border-radius: 4px; padding: 2em 2.2em; font-size: 1.25em; line-height: 1.45; max-width: 34ch; margin-block: 2.5em; }' .
		'.gogh-read-essay .entry-content figure.wp-block-image { margin-block: 3em; text-align: center; }' .
		'.gogh-read-essay .entry-content figure.wp-block-image:not(.alignwide):not(.alignfull) img { max-height: 75vh; width: auto; max-width: 100%; margin-inline: auto; }' .
		'.gogh-read-essay .entry-content figure.wp-block-image figcaption { font-size: 0.8em; letter-spacing: 0.06em; text-transform: uppercase; opacity: 0.55; margin-top: 1em; text-align: center; }' .
		// GAZETTE — the commons journal: newsprint bones. A tight left title
		// under a double rule, justified columns with hyphenation, boxed
		// pull-quotes, headings in small caps with a hanging rule. All rules
		// draw from currentColor so the ink follows the theme.
		'.gogh-read-gazette .wp-block-post-title { font-size: clamp(2.2rem, 5vw, 3.4rem); font-weight: 700; line-height: 1.04; letter-spacing: -0.02em; max-width: 22ch; border-top: 3px double currentColor; padding-top: 0.45em; }' .
		'.gogh-read-gazette .entry-content > p { max-width: 60ch; text-align: justify; hyphens: auto; -webkit-hyphens: auto; line-height: 1.6; margin-block-end: 1.1em; }' .
		'.gogh-read-gazette .entry-content > p:first-of-type::first-letter { float: left; font-size: 3.1em; line-height: 0.82; padding: 0.04em 0.14em 0 0; font-weight: 700; }' .
		'@supports (initial-letter: 3) { .gogh-read-gazette .entry-content > p:first-of-type::first-letter { float: none; font-size: unset; line-height: unset; padding: 0; initial-letter: 3; font-weight: 700; margin-right: 0.15em; } }' .
		// crossheads sit IN the column, set loud in the display face — the
		// newspaper's "The Fog Machine" move, not a section divider
		// 36ch ≈ the paragraphs' 60ch box: ch here is measured in the
		// crosshead's own 1.65em characters, so the width must scale down
		// or the centred box overhangs the text column
		'.gogh-read-gazette .entry-content > h2, .gogh-read-gazette .entry-content > h3 { max-width: 38ch; font-size: 1.65em; font-weight: 700; line-height: 1.08; letter-spacing: -0.01em; text-transform: none; margin-block: 1.3em 0.45em; }' .
		'.gogh-read-gazette .entry-content blockquote { border: 1px solid color-mix(in srgb, currentColor 45%, transparent); padding: 1.4em 1.6em; text-align: center; font-size: 1.2em; line-height: 1.4; max-width: 30ch; margin-inline: auto; margin-block: 2em; }' .
		'.gogh-read-gazette .entry-content figure.wp-block-image { margin-block: 1.8em; }' .
		'.gogh-read-gazette .entry-content figure.wp-block-image:not(.alignwide):not(.alignfull) img { max-height: 65vh; width: auto; max-width: 100%; margin-inline: auto; }' .
		'.gogh-read-gazette .entry-content figure.wp-block-image figcaption { font-size: 0.78em; opacity: 0.65; border-bottom: 1px solid color-mix(in srgb, currentColor 25%, transparent); padding-bottom: 0.7em; }' .
		// PHOTO STORY — pictures lead, words breathe between. A huge, tight
		// display title; sparse centred text bands on a narrow measure;
		// images run big (bleeds up to a full screen) with prominent
		// breathing room and quiet captions; quotes are bare oversized
		// statements. For posts that are mostly photographs.
		'.gogh-read-photostory .wp-block-post-title { font-size: clamp(3.2rem, 9vw, 6rem); line-height: 0.98; letter-spacing: -0.03em; max-width: 12ch; text-wrap: balance; }' .
		'.gogh-read-photostory .entry-content > p { max-width: 46ch; margin-inline: auto; text-align: center; line-height: 1.8; font-size: 1.05em; margin-block: 2.2em; }' .
		'.gogh-read-photostory .entry-content > h2, .gogh-read-photostory .entry-content > h3 { text-align: center; font-size: 1.1em; letter-spacing: 0.14em; text-transform: uppercase; margin-block-start: 3em; }' .
		'.gogh-read-photostory .entry-content figure.wp-block-image { margin-block: 3.5em; text-align: center; }' .
		'.gogh-read-photostory .entry-content figure.wp-block-image:not(.alignwide):not(.alignfull) img { max-height: 88vh; width: auto; max-width: 100%; margin-inline: auto; }' .
		'.gogh-read-photostory .entry-content figure.wp-block-image.alignwide img, .gogh-read-photostory .entry-content figure.wp-block-image.alignfull:not(.gogh-splash-break) img { max-height: 96vh; object-fit: cover; }' .
		'.gogh-read-photostory .entry-content figure.wp-block-image figcaption { font-size: 0.82em; opacity: 0.6; margin-top: 1.2em; text-align: center; }' .
		'.gogh-read-photostory .entry-content blockquote { border: 0; text-align: center; font-size: 1.6em; line-height: 1.3; max-width: 22ch; margin-inline: auto; margin-block: 2.5em; }' .
		// COVER — the poster front ("takes an image and sets it as the
		// background, with title, author over the top"). The featured image
		// (or the post's first picture) becomes a full-bleed header with the
		// title knocked out over a quiet scrim and the byline beneath it in
		// small caps; the raw materials arrive as CSS vars so the write room
		// can audition the look live. No image → a deep brand-toned cover.
		'.gogh-read-cover .wp-block-post-title { box-sizing: border-box; width: 100vw; max-width: 100vw; position: relative; left: 50%; transform: translateX(-50%); margin-inline: 0; margin-top: 0; min-height: 74vh; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 1.2em 6vw; color: #fff; background: linear-gradient(rgba(8, 9, 12, 0.28), rgba(8, 9, 12, 0.55)), var(--gogh-cover-img, linear-gradient(165deg, #1d2233, #0d0e14)) center var(--gogh-cover-pos, 50%) / cover no-repeat; font-size: clamp(2.8rem, 7vw, 5.2rem); line-height: 1.03; letter-spacing: -0.02em; text-wrap: balance; }' .
		'.gogh-read-cover .wp-block-post-title::after { content: var(--gogh-cover-byline, ""); display: block; margin-top: 1.5em; font-size: 0.82rem; font-weight: 600; letter-spacing: 0.22em; text-transform: uppercase; opacity: 0.85; }' .
		// the byline lives on the cover now; the template rows and the
		// featured-image block fold into it
		'.gogh-read-cover :is(.wp-block-post-date, .wp-block-post-author-name, .wp-block-post-author, .wp-block-post-terms) { display: none; }' .
	// the whole byline ROW folds away — its 'Written by' and 'in' are
	// naked sibling paragraphs, so the shared wrapper is the true target
	'.gogh-read-cover main :is(div, p, .wp-block-group, .wp-block-post-meta):has(> .wp-block-post-author-name), .gogh-read-cover main :is(div, p, .wp-block-group, .wp-block-post-meta):has(> .wp-block-post-date) { display: none !important; }' .
		'.gogh-read-cover .wp-block-post-featured-image { display: none; }' .
		'.gogh-read-cover .entry-content { margin-top: 3rem; }' .
		'.gogh-read-cover .entry-content > p, .gogh-read-cover .entry-content > h2, .gogh-read-cover .entry-content > h3 { max-width: 66ch; }' .
		// FLUSH under the nav: the cover is the page's true top — the
		// template's breathing room above content becomes a stray band here
		'.gogh-read-cover main { padding-block-start: 0 !important; }' .
		'.gogh-read-cover main > :first-child { margin-block-start: 0 !important; padding-block-start: 0 !important; }' .
		// under the write room's audition zoom viewport units lie inside
		// the scaled page — the band sizes to its full-width parent there,
		// padding and all. (The look class rides on BODY, so the selector
		// chains it; the old descendant form never matched and the cover
