		'body.gogh-w-audition.gogh-read-cover .wp-block-post-title { width: calc(100% + var(--wp--style--root--padding-left, 0px) + var(--wp--style--root--padding-right, 0px)); max-width: none; left: calc(-1 * var(--wp--style--root--padding-left, 0px)); transform: none; }' .
		// writing on the cover: the pseudo byline stays out of the caret's way
		'body.gogh-writing.gogh-read-cover .wp-block-post-title::after { content: none; }' .
		// MANUAL — the reference page: a side table of contents that stays
		// put, section headings you can land on, tables and code that are
		// meant to be read rather than admired. The contents are built by
		// gogh-view from the post's own h2/h3 (two or more), so the look
		// asks nothing of the writer.
		// the title lives in the template's own group: give it the text's measure so the two share a left edge
		'.gogh-read-manual .wp-block-post-title { font-size: clamp(1.7rem, 3vw, 2.5rem); font-weight: 700; letter-spacing: -0.01em; line-height: 1.15; text-align: left; margin-block-end: 0.6em; max-width: 46rem; }' .
		// the contents hang in the left gutter beside the theme's own centred
		// measure (title, headings and text keep one edge); when the gutter
		// is too narrow they sit boxed above the text instead
		'.gogh-read-manual .entry-content > :not(.gogh-toc) { max-width: 46rem; }' .
		'.gogh-toc-side { position: fixed; top: 96px; width: 220px; max-height: calc(100vh - 120px); overflow-y: auto; scrollbar-width: thin; z-index: 5; }' .
		'.gogh-read-manual .entry-content > .gogh-toc-boxed { max-width: 46rem; margin-block-end: 2em; padding: 0.9em 1.1em; border: 1px solid color-mix(in srgb, currentColor 14%, transparent); border-radius: 8px; }' .
		'.gogh-toc-boxed ol { border-left: 0; } .gogh-toc-boxed a { padding-left: 0; border-left: 0; } .gogh-toc-boxed li.gogh-toc-h3 a { padding-left: 14px; }' .
		// the writing room's contents: read-only, beside the column, never inside the content
		'.gogh-toc-room { position: fixed; top: 112px; width: 220px; max-height: calc(100vh - 140px); overflow-y: auto; z-index: 5; }' .
		'.gogh-toc-room a { cursor: pointer; }' .
		// the audition shows the column too (James) — placed clear of the looks list, or not at all
		'.gogh-toc-room[hidden] { display: none; }' .
		'.gogh-read-manual .entry-content > .wp-block-table, .gogh-read-manual .entry-content > .wp-block-code, .gogh-read-manual .entry-content > pre, .gogh-read-manual .entry-content > figure.wp-block-image.alignwide, .gogh-read-manual .entry-content > figure.wp-block-image.alignfull { max-width: 46rem; }' .
		'.gogh-toc { font-size: 0.86rem; line-height: 1.45; padding-right: 8px; }' .
		'.gogh-toc-title { display: block; font-size: 0.72rem; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; opacity: 0.6; margin-block-end: 0.8em; }' .
		'.gogh-toc ol { list-style: none; margin: 0; padding: 0; border-left: 1px solid color-mix(in srgb, currentColor 18%, transparent); }' .
		'.gogh-toc li { margin: 0; }' .
		'.gogh-toc a { display: block; padding: 0.35em 0 0.35em 14px; margin-left: -1px; border-left: 2px solid transparent; color: inherit; text-decoration: none; opacity: 0.72; }' .
		'.gogh-toc a:hover { opacity: 1; }' .
		'.gogh-toc a.is-here { opacity: 1; font-weight: 600; border-left-color: currentColor; }' .
		'.gogh-toc li.gogh-toc-h3 a { padding-left: 28px; font-size: 0.94em; }' .
		'.gogh-read-manual .entry-content > h2 { margin-block-start: 2.2em; padding-block-top: 0.9em; padding-top: 0.9em; border-top: 1px solid color-mix(in srgb, currentColor 14%, transparent); font-size: 1.45em; letter-spacing: -0.01em; }' .
		'.gogh-read-manual .entry-content > h3 { margin-block-start: 1.6em; font-size: 1.12em; }' .
		'.gogh-read-manual .entry-content :is(h2, h3, h4) { scroll-margin-top: 32px; }' .
		'.gogh-read-manual .entry-content > p, .gogh-read-manual .entry-content > ul, .gogh-read-manual .entry-content > ol { line-height: 1.65; }' .
		'.gogh-read-manual .entry-content li { margin-block-end: 0.35em; }' .
		// tables read as tables: full measure, a real header row, quiet stripes
		'.gogh-read-manual .entry-content .wp-block-table { overflow-x: auto; }' .
		'.gogh-read-manual .entry-content .wp-block-table table { width: 100%; border-collapse: collapse; font-size: 0.92em; border: 1px solid color-mix(in srgb, currentColor 16%, transparent); }' .
		'.gogh-read-manual .entry-content .wp-block-table :is(th, td) { padding: 0.55em 0.8em; border: 1px solid color-mix(in srgb, currentColor 12%, transparent); text-align: left; vertical-align: top; }' .
		'.gogh-read-manual .entry-content .wp-block-table th, .gogh-read-manual .entry-content .wp-block-table thead td { background: color-mix(in srgb, currentColor 8%, transparent); font-weight: 600; }' .
		'.gogh-read-manual .entry-content .wp-block-table tbody tr:nth-child(even) td { background: color-mix(in srgb, currentColor 3.5%, transparent); }' .
		// code sits on a quiet panel; inline code wears a light tint
		'.gogh-read-manual .entry-content :is(pre, .wp-block-code) { background: color-mix(in srgb, currentColor 6%, transparent); border: 1px solid color-mix(in srgb, currentColor 12%, transparent); border-radius: 8px; padding: 1em 1.2em; font-size: 0.88em; line-height: 1.55; overflow-x: auto; tab-size: 2; }' .
		'.gogh-read-manual .entry-content :not(pre) > code { background: color-mix(in srgb, currentColor 8%, transparent); border-radius: 4px; padding: 0.1em 0.35em; font-size: 0.9em; }' .
		// notes: a blockquote is a callout here, not a pull-quote
		'.gogh-read-manual .entry-content blockquote { border-left: 3px solid currentColor; background: color-mix(in srgb, currentColor 4%, transparent); padding: 0.8em 1.1em; margin-inline: 0; font-style: normal; font-size: 0.95em; border-radius: 0 8px 8px 0; }' .
		'.gogh-read-manual .entry-content blockquote p { margin: 0; }' .
		'.gogh-read-manual .entry-content blockquote cite { display: block; margin-top: 0.4em; font-size: 0.85em; opacity: 0.7; }' .
		// the writing room and phones: one column, the contents fold above the text
		gogh_reading_wow_css();
}

// menus heal themselves: trashing a page removes its links from every
// menu ("i deleted some pages and now the menu looks broken" — core
// leaves a hole where the dead link was). Untrash re-adds nothing; a
// restored page is one drag away in the nav editor.
// a front-door draft is deliberately blank (title, content and excerpt) —
// WordPress refuses to update such a post at all, so it could not even be
// trashed ("Error moving page to trash"). Blank gogh pages may be updated.
add_filter( 'wp_insert_post_empty_content', function ( $maybe_empty, $postarr ) {
	if ( ! $maybe_empty ) {
		return $maybe_empty;
	}
	$id = isset( $postarr['ID'] ) ? (int) $postarr['ID'] : 0;
	if ( $id && get_post_meta( $id, '_gogh_door', true ) ) {
		return false;
	}
	// any page on its way to the trash may be empty — the trash is not a save
	if ( isset( $postarr['post_type'], $postarr['post_status'] ) && 'page' === $postarr['post_type'] && 'trash' === $postarr['post_status'] ) {
		return false;
	}
	return $maybe_empty;
}, 10, 2 );
add_action( 'trashed_post', function ( $post_id ) {
	$type = get_post_type( $post_id );
	if ( ! in_array( $type, array( 'page', 'post' ), true ) ) {
		return;
	}
	$navs = get_posts( array(
		'post_type'   => 'wp_navigation',
		'post_status' => 'publish',
		'numberposts' => 20,
	) );
	foreach ( $navs as $nav ) {
		if ( false === strpos( $nav->post_content, '"id":' . $post_id ) ) {
			continue;
		}
		$cleaned = preg_replace_callback(
			'/<!--\s*wp:navigation-link\s+({[\s\S]*?})\s*\/-->/',
			function ( $m ) use ( $post_id ) {
				$attrs = json_decode( $m[1], true );
				return ( is_array( $attrs ) && isset( $attrs['id'] ) && (int) $attrs['id'] === (int) $post_id ) ? '' : $m[0];
			},
			$nav->post_content
		);
		if ( null !== $cleaned && $cleaned !== $nav->post_content ) {
			wp_update_post( array( 'ID' => $nav->ID, 'post_content' => $cleaned ) );
		}
	}
} );

function gogh_starters() {
	$out = array();
	foreach ( glob( __DIR__ . '/starters/*/manifest.json' ) as $mf ) {
		$slug = basename( dirname( $mf ) );
		$m    = json_decode( file_get_contents( $mf ), true );
		if ( $m && ! empty( $m['pages'] ) ) {
			$m['slug']    = $slug;
			$out[ $slug ] = $m;
		}
	}
	return $out;
}
function gogh_starter_page_content( $slug, $pg ) {
	$file = __DIR__ . '/starters/' . $slug . '/' . basename( $pg['file'] );
	if ( ! is_readable( $file ) ) {
		return '';
	}
	return str_replace(
		array( '{{gogh_theme}}', '{{gogh_plugin}}' ),
		array( get_template_directory_uri(), untrailingslashit( plugins_url( '', __FILE__ ) ) ),
		file_get_contents( $file )
	);
}
add_action( 'init', function () {
	foreach ( gogh_starters() as $slug => $m ) {
		foreach ( $m['pages'] as $pg ) {
			if ( empty( $pg['file'] ) ) {
				continue; // a Woo page in the menu, nothing of ours to register
			}
			$content = gogh_starter_page_content( $slug, $pg );
			if ( '' === $content ) {
				continue;
			}
			register_block_pattern( 'gogh-starter/' . $slug . '-' . $pg['slug'], array(
				'title'    => $m['name'] . ' — ' . $pg['title'],
				'inserter' => false,
				'content'  => $content,
			) );
		}
	}
} );
add_action( 'rest_api_init', function () {
	// the editor asks this on window-focus: a tab that outlived a release
	// gets a quiet "reload" chip instead of silently missing features
	// (a stale tab ate two releases in one day — twice)
	register_rest_route( 'gogh/v1', '/version', array(
		'methods'             => 'GET',
		'permission_callback' => function () {
			return current_user_can( 'edit_posts' );
		},
		'callback'            => function () {
			return array( 'build' => '0.99.421-chrome' );
		},
	) );
	register_rest_route( 'gogh/v1', '/starter', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'manage_options' );
		},
		'args'                => array( 'slug' => array( 'required' => true, 'type' => 'string' ) ),
		'callback'            => function ( $req ) {
			$starters = gogh_starters();
			$slug     = sanitize_key( $req['slug'] );
			if ( empty( $starters[ $slug ] ) ) {
				return new WP_Error( 'gogh_no_starter', __( 'Unknown site design.', 'gogh-editor' ), array( 'status' => 404 ) );
			}
			$m = $starters[ $slug ];
			// current pages step aside, restorably — never deleted
			$old = get_posts( array(
				'post_type'   => 'page',
				'post_status' => array( 'publish', 'draft', 'private', 'pending' ),
				'numberposts' => -1,
				'fields'      => 'ids',
			) );
			// WooCommerce's own pages (shop, cart, checkout, account) are rails,
			// never part of a design: they stay put — James lost them once
			$keep = array();
			if ( function_exists( 'wc_get_page_id' ) ) {
				foreach ( array( 'shop', 'cart', 'checkout', 'myaccount' ) as $wk ) {
					$wid = (int) wc_get_page_id( $wk );
					if ( $wid > 0 ) {
						$keep[] = $wid;
					}
				}
			}
			foreach ( $old as $oid ) {
				if ( in_array( (int) $oid, $keep, true ) ) {
					continue;
				}
				wp_trash_post( $oid );
			}
			$front = 0;
			$blog  = 0;
			$made  = array();
			// a design that needs the shop never applies without it
			if ( ! empty( $m['requires'] ) && 'woo' === $m['requires'] && ! class_exists( 'WooCommerce' ) ) {
				return new WP_Error( 'gogh_needs_woo', __( 'This design needs WooCommerce.', 'gogh-editor' ), array( 'status' => 400 ) );
			}
			foreach ( $m['pages'] as $pg ) {
				if ( ! empty( $pg['woo'] ) ) {
					// Woo's own page (shop, cart, account) takes its seat in the menu — never re-made
					$wid = function_exists( 'wc_get_page_id' ) ? (int) wc_get_page_id( sanitize_key( $pg['woo'] ) ) : 0;
					if ( $wid > 0 ) {
						$made[] = array( 'id' => $wid, 'title' => $pg['title'], 'no_menu' => isset( $pg['menu'] ) && false === $pg['menu'] );
					}
					continue;
				}
				$id = wp_insert_post( array(
					'post_type'    => 'page',
					'post_status'  => 'publish',
					'post_title'   => $pg['title'],
					'post_name'    => $pg['slug'],
					// wp_insert_post unslashes its input — without wp_slash it strips
					// the backslashes from the JSON < / " / - escapes in
					// the gogh/section model, so a widget's whtml became literal
					// "u003cdiv…" text in the editor ("issues with the blueprint")
					'post_content' => wp_slash( gogh_starter_page_content( $slug, $pg ) ),
					'meta_input'   => empty( $pg['template'] ) ? array()
						: array( '_wp_page_template' => sanitize_key( $pg['template'] ) ),
				) );
				if ( ! $id || is_wp_error( $id ) ) {
					continue;
				}
				$made[] = array(
					'id'      => $id,
					'title'   => $pg['title'],
					'no_menu' => isset( $pg['menu'] ) && false === $pg['menu'],
				);
				if ( ! empty( $pg['front'] ) ) {
					$front = $id;
				}
				if ( ! empty( $pg['blog'] ) ) {
					$blog = $id;
				}
			}
			if ( ! $made ) {
				return new WP_Error( 'gogh_starter_failed', __( 'The site design could not be applied.', 'gogh-editor' ), array( 'status' => 500 ) );
			}
			if ( ! empty( $m['shop'] ) && is_array( $m['shop'] ) && function_exists( 'gogh_shop_looks' ) ) {
				$looks = gogh_shop_looks();
				if ( isset( $m['shop']['layout'] ) && array_key_exists( $m['shop']['layout'], $looks ) ) {
					update_option( 'gogh_shop_layout', $m['shop']['layout'] );
				}
				if ( isset( $m['shop']['category'] ) && array_key_exists( $m['shop']['category'], $looks ) ) {
					update_option( 'gogh_category_layout', $m['shop']['category'] );
				}
			}
			// starter posts: the notebook arrives lived-in, and gogh write
			// has a finished example on the shelf
			if ( ! empty( $m['posts'] ) ) {
				foreach ( $m['posts'] as $ps ) {
					$pid = wp_insert_post( array(
						'post_type'    => 'post',
						'post_status'  => 'publish',
						'post_title'   => $ps['title'],
						'post_name'    => $ps['slug'],
						'post_content' => wp_slash( gogh_starter_page_content( $slug, $ps ) ), // see the page insert above
					) );
					if ( $pid && ! is_wp_error( $pid ) && ! empty( $ps['category'] ) ) {
						$term = term_exists( $ps['category'], 'category' );
						if ( ! $term ) {
							$term = wp_insert_term( $ps['category'], 'category' );
						}
						if ( $term && ! is_wp_error( $term ) ) {
							$tid = is_array( $term ) ? (int) $term['term_id'] : (int) $term;
							wp_set_post_terms( $pid, array( $tid ), 'category' );
						}
					}
				}
			}
			$links = '';
			foreach ( $made as $c ) {
				if ( ! empty( $c['no_menu'] ) ) {
					continue;
				}
				$links .= '<!-- wp:navigation-link {"label":"' . esc_attr( $c['title'] ) . '","type":"page","id":' . $c['id'] .
					',"url":"' . esc_url( get_permalink( $c['id'] ) ) . '","kind":"post-type"} /-->';
			}
			// re-use a same-named menu rather than minting a new wp_navigation
			// post on every apply — otherwise re-running a starter litters the
			// "swap menus" list with a fresh "Café menu" each time
			$nav_title = $m['name'] . ' menu';
			$found = new WP_Query( array(
				'post_type'      => 'wp_navigation',
				'post_status'    => 'publish',
				'title'          => $nav_title,
				'posts_per_page' => 1,
				'fields'         => 'ids',
				'no_found_rows'  => true,
			) );
			$nav_id = $found->posts ? (int) $found->posts[0] : 0;
			if ( $nav_id ) {
				wp_update_post( array( 'ID' => $nav_id, 'post_content' => $links ) );
			} else {
				$nav_id = wp_insert_post( array(
					'post_type'    => 'wp_navigation',
					'post_status'  => 'publish',
					'post_title'   => $nav_title,
					'post_content' => $links,
				) );
			}
			// point the live header's menu at the new navigation
			$part = get_block_template( get_stylesheet() . '//header', 'wp_template_part' );
			if ( $part && $nav_id && ! is_wp_error( $nav_id ) ) {
				$praw = (string) $part->content;
				// a starter may choose one of gogh's own headers — the Yellow
				// House floats the transparent overlay over its hero
				if ( ! empty( $m['chrome']['header'] ) ) {
					$pfile = __DIR__ . '/patterns/' . sanitize_file_name( $m['chrome']['header'] ) . '.html';
					if ( is_readable( $pfile ) ) {
						$praw = file_get_contents( $pfile );
					}
				}
				$next = '';
				if ( preg_match( '/wp:navigation[^>]*"ref":\d+/', $praw ) ) {
					$next = preg_replace( '/("ref":)\d+/', '${1}' . $nav_id, $praw, 1 );
				} elseif ( preg_match( '/<!--\s+wp:navigation\s+\{/', $praw ) ) {
					$next = preg_replace( '/(<!--\s+wp:navigation\s+\{)/', '${1}"ref":' . $nav_id . ',', $praw, 1 );
				} else {
					$next = preg_replace( '/(<!--\s+wp:navigation)(\s+-->)/', '${1} {"ref":' . $nav_id . '}${2}', $praw, 1 );
				}
				if ( $next && $next !== $praw ) {
					if ( ! empty( $part->wp_id ) ) {
						wp_update_post( array( 'ID' => $part->wp_id, 'post_content' => $next ) );
					} else {
						$pid = wp_insert_post( array(
							'post_type'    => 'wp_template_part',
							'post_status'  => 'publish',
							'post_title'   => 'header',
							'post_name'    => 'header',
							'post_content' => $next,
						) );
						if ( $pid && ! is_wp_error( $pid ) ) {
							wp_set_post_terms( $pid, array( get_stylesheet() ), 'wp_theme' );
							wp_set_post_terms( $pid, array( 'header' ), 'wp_template_part_area' );
						}
					}
				}
			}
			// a starter may carry a bespoke PALETTE: theme palette slugs are
			// re-coloured (base/contrast keep roles, accents cycle), applied
			// as user global styles — same mechanism as Your brand
			if ( ! empty( $m['palette'] ) && class_exists( 'WP_Theme_JSON_Resolver' ) ) {
				$theme_pal = wp_get_global_settings( array( 'color', 'palette', 'theme' ) );
				if ( is_array( $theme_pal ) && $theme_pal ) {
					$pal     = $m['palette'];
					$accents = isset( $pal['accents'] ) && is_array( $pal['accents'] ) ? array_values( $pal['accents'] ) : array();
					$ai      = 0;
					$out_pal = array();
					foreach ( $theme_pal as $entry ) {
						$slug = isset( $entry['slug'] ) ? $entry['slug'] : '';
						if ( ( 'base' === $slug || 'background' === $slug ) && ! empty( $pal['base'] ) ) {
							$entry['color'] = $pal['base'];
						} elseif ( ( 'contrast' === $slug || 'text' === $slug || 'foreground' === $slug ) && ! empty( $pal['contrast'] ) ) {
							$entry['color'] = $pal['contrast'];
						} elseif ( $accents && 0 === strpos( $slug, 'accent' ) ) {
							$entry['color'] = $accents[ $ai % count( $accents ) ];
							$ai++;
						}
						$out_pal[] = $entry;
					}
					$gs_id = WP_Theme_JSON_Resolver::get_user_global_styles_post_id();
					if ( $gs_id ) {
						wp_update_post( array(
							'ID'           => $gs_id,
							'post_content' => wp_json_encode( array(
								'version'                     => class_exists( 'WP_Theme_JSON' ) ? WP_Theme_JSON::LATEST_SCHEMA : 3,
								'isGlobalStylesUserThemeJSON' => true,
								'settings'                    => array( 'color' => array( 'palette' => array( 'theme' => $out_pal ) ) ),
								'styles'                      => new stdClass(),
							) ),
						) );
					}
				}
			}
			// the design brings its own look: apply the named theme style
			// variation to user global styles. The user's saved gogh brand is
			// untouched and can be re-applied from Your brand at any time.
			$applied_variation = '';
			if ( ! empty( $m['variation'] ) && class_exists( 'WP_Theme_JSON_Resolver' ) ) {
				foreach ( WP_Theme_JSON_Resolver::get_style_variations() as $v ) {
					if ( isset( $v['title'] ) && 0 === strcasecmp( $v['title'], $m['variation'] ) ) {
						$applied_variation = $m['variation'];
						$gs_id = WP_Theme_JSON_Resolver::get_user_global_styles_post_id();
						if ( $gs_id ) {
							wp_update_post( array(
								'ID'           => $gs_id,
								'post_content' => wp_json_encode( array(
									'version'                     => class_exists( 'WP_Theme_JSON' ) ? WP_Theme_JSON::LATEST_SCHEMA : 3,
									'isGlobalStylesUserThemeJSON' => true,
									'settings'                    => isset( $v['settings'] ) ? $v['settings'] : new stdClass(),
									'styles'                      => isset( $v['styles'] ) ? $v['styles'] : new stdClass(),
								) ),
							) );
						}
						break;
					}
				}
			}
			// remember which style the site now wears — WP itself forgets the
			// variation's name the moment it's copied into user global styles.
			// Only when it truly applied: a design's variation is a Twenty
			// Twenty-Five name, and on another theme (James switched to Ollie)
			// nothing matched — recording it anyway would have the Site style
			// panel claim a look the site never put on.
			if ( '' !== $applied_variation ) {
				update_option( 'gogh_active_style', $applied_variation );
			}
			update_option( 'show_on_front', 'page' );
			update_option( 'page_on_front', $front ? $front : $made[0]['id'] );
			update_option( 'page_for_posts', $blog ? $blog : 0 );
			return array( 'home' => get_permalink( $front ? $front : $made[0]['id'] ) );
		},
	) );

	register_rest_route( 'gogh/v1', '/type-scale', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'edit_theme_options' );
		},
		'args'                => array( 'scale' => array( 'required' => true, 'type' => 'number' ) ),
		'callback'            => function ( $req ) {
			$scale = max( 80, min( 140, (int) $req['scale'] ) );
			update_option( 'gogh_type_scale', $scale );
			return array( 'scale' => $scale );
		},
	) );

	register_rest_route( 'gogh/v1', '/blog-style', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'edit_theme_options' );
		},
		'args'                => array( 'key' => array( 'required' => true, 'type' => 'string' ) ),
		'callback'            => function ( $req ) {
			$key = sanitize_key( $req['key'] );
			if ( ! in_array( $key, gogh_blog_styles(), true ) ) {
				return new WP_Error( 'gogh_bad_blog_style', __( 'Unknown blog style.', 'gogh-editor' ), array( 'status' => 400 ) );
			}
			update_option( 'gogh_blog_style', $key );
			return array( 'key' => $key );
		},
	) );

	register_rest_route( 'gogh/v1', '/motion', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'edit_theme_options' );
		},
		'args'                => array( 'key' => array( 'required' => true, 'type' => 'string' ) ),
		'callback'            => function ( $req ) {
			$key = sanitize_key( $req['key'] );
			if ( ! in_array( $key, gogh_motion_styles(), true ) ) {
				return new WP_Error( 'gogh_bad_motion', __( 'Unknown motion style.', 'gogh-editor' ), array( 'status' => 400 ) );
			}
			update_option( 'gogh_motion', $key );
			return array( 'key' => $key );
		},
	) );

	// ---------- Ask Gogh, phase 2: the imagination tier ----------
	// The vocabulary answers instantly and locally; asks it cannot read
	// come here — a real model that NEVER writes markup. It returns
	// changes to the section MODEL (the same ops the vocabulary emits),
	// the client validates and clamps every field, and the solver
	// renders. The key lives server-side only — the browser never sees it.
	register_rest_route( 'gogh/v1', '/ask', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'edit_theme_options' );
		},
		'callback'            => 'gogh_ask_handler',
	) );

	// ✦ Imagine an experience: the gallery hangs wild paintings on calm
	// walls. Full-creative-mode HTML, model-written, uploaded to the
	// user's OWN media library and framed in the sandboxed Experience
	// element — the walls stay themed, the frame holds the madness.
	// Gated like the manual upload: this mints text/html attachments.
	register_rest_route( 'gogh/v1', '/imagine-exp', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'upload_files' ) && current_user_can( 'unfiltered_html' );
		},
		'callback'            => 'gogh_imagine_exp_handler',
	) );

	// the key door: paste once in the Ask panel, gone from sight forever.
	// Admins only (it's a billing credential), shape-checked, write-only —
	// an empty key forgets it. A wp-config constant outranks the option.
	register_rest_route( 'gogh/v1', '/ask-key', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'manage_options' );
		},
		'callback'            => function ( $req ) {
			$p = $req->get_json_params();
			// each field only moves when it's PRESENT in the payload — a
			// workspace-only save must never brush against the stored key
			if ( is_array( $p ) && array_key_exists( 'key', $p ) ) {
				$key = trim( (string) $p['key'] );
				if ( '' === $key ) {
					delete_option( 'gogh_ask_key' );
					delete_option( 'gogh_ask_workspace' );
				} elseif ( ! preg_match( '/^sk-ant-[A-Za-z0-9_\-]{10,250}$/', $key ) ) {
					return new WP_Error( 'gogh_ask_key_shape', __( 'That doesn’t look like an Anthropic key (they start sk-ant-…).', 'gogh-editor' ), array( 'status' => 400 ) );
				} else {
					update_option( 'gogh_ask_key', $key, false );
				}
			}
			// identity-linked keys act inside a workspace — the id is an
			// identifier, not a secret, but it gets the same write-only home
			if ( is_array( $p ) && array_key_exists( 'workspace', $p ) ) {
				$ws = trim( (string) $p['workspace'] );
				if ( '' === $ws ) {
					delete_option( 'gogh_ask_workspace' );
				} elseif ( ! preg_match( '/^wrkspc_[A-Za-z0-9_\-]{4,80}$/', $ws ) ) {
					return new WP_Error( 'gogh_ask_ws_shape', __( 'That doesn’t look like a Workspace ID (they start wrkspc_…).', 'gogh-editor' ), array( 'status' => 400 ) );
				} else {
					update_option( 'gogh_ask_workspace', $ws, false );
				}
			}
			// 'on' lights the section tier (labs-gated); 'exp' lights Experiences
			return array( 'on' => (bool) ( gogh_ask_key() && gogh_labs_ask() ), 'exp' => (bool) gogh_ask_key() );
		},
	) );
	// the miss-log: an ask that missed, errored, or was instantly undone
	// IS a bug report — a quiet capped list, so gaps surface as data
	// instead of screenshots. Write-only from the editor; read as admin.
	// the first minute retires here — outcome to user meta, the honest
	// clock to a small capped log (did the 60-second promise hold?)
	register_rest_route( 'gogh/v1', '/menu-style', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'edit_theme_options' );
		},
		'callback'            => function ( $req ) {
			$p   = $req->get_json_params();
			$cur = gogh_menu_style();
			$next = array(
				'layout'    => isset( $p['layout'] ) ? sanitize_key( $p['layout'] ) : $cur['layout'],
				'ground'    => isset( $p['ground'] ) ? sanitize_key( $p['ground'] ) : $cur['ground'],
				'phone'     => isset( $p['phone'] ) ? sanitize_text_field( $p['phone'] ) : $cur['phone'],
				'email'     => isset( $p['email'] ) ? sanitize_email( $p['email'] ) : $cur['email'],
				'account'   => isset( $p['account'] ) ? (bool) $p['account'] : $cur['account'],
				'phoneMenu' => isset( $p['phoneMenu'] ) ? (int) $p['phoneMenu'] : $cur['phoneMenu'],
			);
			update_option( 'gogh_menu_style', $next, true );
			return array( 'ok' => true, 'style' => gogh_menu_style() );
		},
	) );
	register_rest_route( 'gogh/v1', '/first-minute', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'edit_posts' );
		},
		'callback'            => function ( $req ) {
			$p       = $req->get_json_params();
			$outcome = isset( $p['outcome'] ) && 'skipped' === $p['outcome'] ? 'skipped' : 'done';
			update_user_meta( get_current_user_id(), '_gogh_first_minute', $outcome );
			$log   = get_option( 'gogh_first_minute_log', array() );
			$log[] = array(
				't'    => time(),
				'o'    => $outcome,
				'secs' => isset( $p['secs'] ) ? min( 9999, absint( $p['secs'] ) ) : null,
			);
			if ( count( $log ) > 50 ) {
				$log = array_slice( $log, -50 );
			}
			update_option( 'gogh_first_minute_log', $log, false );
			return array( 'ok' => true );
		},
	) );
	register_rest_route( 'gogh/v1', '/ask-log', array(
		array(
			'methods'             => 'POST',
			'permission_callback' => function () {
				return current_user_can( 'edit_theme_options' );
			},
			'callback'            => function ( $req ) {
				$p   = $req->get_json_params();
				$ask = isset( $p['ask'] ) ? substr( sanitize_text_field( (string) $p['ask'] ), 0, 120 ) : '';
				$o   = isset( $p['outcome'] ) ? sanitize_key( $p['outcome'] ) : '';
				if ( '' === $ask || ! in_array( $o, array( 'miss', 'refused', 'model-error', 'undone', 'seam-miss' ), true ) ) {
					return new WP_Error( 'gogh_ask_log_bad', __( 'Nothing to log.', 'gogh-editor' ), array( 'status' => 400 ) );
				}
				$log = get_option( 'gogh_ask_log', array() );
				if ( ! is_array( $log ) ) {
					$log = array();
				}
				$log[] = array( 't' => time(), 'ask' => $ask, 'o' => $o );
				if ( count( $log ) > 100 ) {
					$log = array_slice( $log, -100 );
				}
				update_option( 'gogh_ask_log', $log, false );
				return array( 'n' => count( $log ) );
			},
		),
		array(
			'methods'             => 'GET',
			'permission_callback' => function () {
				return current_user_can( 'manage_options' );
			},
			'callback'            => function () {
				return array( 'log' => get_option( 'gogh_ask_log', array() ) );
			},
		),
	) );

	register_rest_route( 'gogh/v1', '/active-style', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'edit_theme_options' );
		},
		'args'                => array( 'name' => array( 'required' => true, 'type' => 'string' ) ),
		'callback'            => function ( $req ) {
			$name = sanitize_text_field( $req['name'] );
			update_option( 'gogh_active_style', $name );
			return array( 'name' => $name );
		},
	) );

	// products live outside wp/v2 — gogh's own save route speaks the same
	// minimal contract the editor already uses (GET raw, POST content,
	// autosaves), registered under wp/v2 so the editor's root-splitting
	// URL arithmetic keeps working
	$gogh_product_perm = function ( $req ) {
		return current_user_can( 'edit_post', (int) $req['id'] );
	};
	$gogh_product_get = function ( $req ) {
		$p = get_post( (int) $req['id'] );
		if ( ! $p || 'product' !== $p->post_type ) {
			return new WP_Error( 'gogh_no_product', 'Not a product', array( 'status' => 404 ) );
		}
		return array( 'id' => $p->ID, 'content' => array( 'raw' => $p->post_content ) );
	};
	register_rest_route( 'wp/v2', '/gogh-product/(?P<id>\d+)', array(
		array(
			'methods'             => 'GET',
			'permission_callback' => $gogh_product_perm,
			'callback'            => $gogh_product_get,
		),
		array(
			'methods'             => 'POST',
			'permission_callback' => $gogh_product_perm,
			'callback'            => function ( $req ) use ( $gogh_product_get ) {
				$id = (int) $req['id'];
				$p  = get_post( $id );
				if ( ! $p || 'product' !== $p->post_type ) {
					return new WP_Error( 'gogh_no_product', 'Not a product', array( 'status' => 404 ) );
				}
				wp_update_post( array( 'ID' => $id, 'post_content' => (string) $req['content'] ) );
				return $gogh_product_get( $req );
			},
		),
	) );
	register_rest_route( 'wp/v2', '/gogh-product/(?P<id>\d+)/autosaves', array(
		'methods'             => 'POST',
		'permission_callback' => $gogh_product_perm,
		'callback'            => function ( $req ) {
			$id = (int) $req['id'];
			$p  = get_post( $id );
			if ( ! $p || 'product' !== $p->post_type ) {
				return new WP_Error( 'gogh_no_product', 'Not a product', array( 'status' => 404 ) );
			}
			if ( ! function_exists( 'wp_create_post_autosave' ) ) {
				require_once ABSPATH . 'wp-admin/includes/post.php';
			}
			$aid = wp_create_post_autosave( array(
				'post_ID'      => $id,
				'post_content' => (string) $req['content'],
				'post_title'   => $p->post_title,
				'post_type'    => 'product',
			) );
			return array( 'id' => is_wp_error( $aid ) ? 0 : (int) $aid );
		},
	) );
} );

/**
 * Product layouts: a FEW fixed, opinionated templates to pick from — never
 * a template editor. Classic is WooCommerce's own untouched template; the
 * gogh layouts add a content canvas below the buy box. Picking happens in
 * the admin bar, one click, per product.
 */
function gogh_product_layouts() {
	// no 'Classic' any more: a layout where gogh cannot edit confused people
	// (James: 'why cant we let folks use gogh on every product layout?').
	// Story IS Woo's buy box — with gogh's canvas beneath it.
	return array(
		'gogh-product-story'   => __( 'Standard — buy box, then your sections', 'gogh-editor' ),
		'gogh-product-showcase' => __( 'Showcase — image-led and centred', 'gogh-editor' ),
		'gogh-product-hero'    => __( 'Hero — the product picture fills the screen', 'gogh-editor' ),
	);
}
