/**
 * Shop looks (James: 'give folks some options to change the design of the
 * shop page and product category pages — these are the main things folks
 * want to customize'). A FEW fixed looks for the shop page and for category
 * pages, built from Woo's own blocks over the inherited archive query —
 * filters, sorting, pagination and add-to-cart are all Woo's. One choice
 * per kind, site-wide, from the admin bar. Classic leaves Woo's template
 * untouched.
 */
function gogh_shop_looks() {
	return array(
		''          => __( 'Classic — WooCommerce\'s own', 'gogh-editor' ),
		'editorial' => __( 'Editorial — big title, tall pictures, no buttons', 'gogh-editor' ),
		'gallery'   => __( 'Gallery — four across, pictures first', 'gogh-editor' ),
		'catalogue' => __( 'Catalogue — filters beside a three-up grid', 'gogh-editor' ),
	);
}
function gogh_shop_look_kind() {
	if ( ! function_exists( 'is_shop' ) ) {
		return '';
	}
	if ( is_shop() ) {
		return 'shop';
	}
	if ( is_product_category() || is_product_tag() ) {
		return 'category';
	}
	return '';
}
function gogh_shop_look_active( $kind = null ) {
	$kind = null === $kind ? gogh_shop_look_kind() : $kind;
	if ( ! $kind ) {
		return '';
	}
	if ( 'category' === $kind && ( is_product_category() || is_product_tag() ) ) {
		// this category's own choice wins (James: 'different layouts for
		// different category pages'); 'classic' is an explicit Woo's-own
		$own = (string) get_term_meta( get_queried_object_id(), '_gogh_shop_look', true );
		if ( 'classic' === $own ) {
			return '';
		}
		if ( $own && array_key_exists( $own, gogh_shop_looks() ) ) {
			return $own;
		}
	}
	$look = (string) get_option( 'shop' === $kind ? 'gogh_shop_layout' : 'gogh_category_layout', '' );
	return array_key_exists( $look, gogh_shop_looks() ) ? $look : '';
}
function gogh_shop_archive_markup( $look, $kind ) {
	$coll_query = '"query":{"woocommerceAttributes":[],"woocommerceStockStatus":["instock","outofstock","onbackorder"],"taxQuery":{},"isProductCollectionBlock":true,"perPage":12,"pages":0,"offset":0,"postType":"product","order":"asc","orderBy":"title","author":"","search":"","exclude":[],"sticky":"","inherit":true}';
	$cols       = 'gallery' === $look ? 4 : 3;
	$cls        = 'gogh-shop gogh-shop-grid gogh-shoplook-' . $look;
	$ratio      = 'editorial' === $look ? '3/4' : '1';
	$collection = '<!-- wp:woocommerce/product-collection {"queryId":0,' . $coll_query . ',"tagName":"div","dimensions":{"widthType":"fill","fixedWidth":""},"displayLayout":{"type":"flex","columns":' . $cols . ',"shrinkColumns":true},"convertedFromProducts":false,"queryContextIncludes":["collection"],"align":"wide","className":"' . $cls . '"} -->' .
		'<div class="wp-block-woocommerce-product-collection alignwide ' . $cls . '">' .
		'<!-- wp:woocommerce/product-template -->' .
		'<!-- wp:woocommerce/product-image {"showSaleBadge":true,"imageSizing":"thumbnail","isDescendentOfQueryLoop":true,"aspectRatio":"' . $ratio . '"} --><!-- wp:woocommerce/product-sale-badge {"isDescendentOfQueryLoop":true,"align":"right"} /--><!-- /wp:woocommerce/product-image -->' .
		'<!-- wp:post-title {"level":3,"isLink":true,"__woocommerceNamespace":"woocommerce/product-collection/product-title","style":{"spacing":{"margin":{"top":"12px","bottom":"6px"}}}} /-->' .
		'<!-- wp:woocommerce/product-price {"isDescendentOfQueryLoop":true} /-->' .
		( 'catalogue' === $look ? '<!-- wp:woocommerce/product-button {"isDescendentOfQueryLoop":true} /-->' : '' ) .
		'<!-- /wp:woocommerce/product-template -->' .
		'<!-- wp:query-pagination {"layout":{"type":"flex","justifyContent":"center"}} --><!-- wp:query-pagination-previous /--><!-- wp:query-pagination-numbers /--><!-- wp:query-pagination-next /--><!-- /wp:query-pagination -->' .
		'<!-- wp:woocommerce/product-collection-no-results --><!-- wp:group {"layout":{"type":"flex","orientation":"vertical","justifyContent":"center","flexWrap":"wrap"}} --><div class="wp-block-group"><!-- wp:pattern {"slug":"woocommerce/no-products-found-clear-filters"} /--></div><!-- /wp:group --><!-- /wp:woocommerce/product-collection-no-results -->' .
		'</div><!-- /wp:woocommerce/product-collection -->';
	$toolbar = '<!-- wp:group {"align":"wide","layout":{"type":"flex","flexWrap":"nowrap","justifyContent":"space-between"},"className":"gogh-shop-toolbar"} --><div class="wp-block-group alignwide gogh-shop-toolbar"><!-- wp:woocommerce/product-results-count /--><!-- wp:woocommerce/catalog-sorting /--></div><!-- /wp:group -->';
	$chips   = ( 'shop' === $kind )
		? '<!-- wp:woocommerce/product-categories {"hasCount":false,"hasImage":false,"isDropdown":false,"className":"gogh-catchips"} /-->'
		: '';
	// Editorial, on a category with a picture: the picture becomes the
	// banner — a Cover, the name and description at its foot
	$banner_id = 0;
	if ( 'editorial' === $look && 'category' === $kind && ( is_product_category() || is_product_tag() ) ) {
		$banner_id = (int) get_term_meta( get_queried_object_id(), 'thumbnail_id', true );
		if ( $banner_id && ! wp_get_attachment_image_url( $banner_id, 'full' ) ) {
			$banner_id = 0;
		}
	}
	if ( $banner_id ) {
		$src  = wp_get_attachment_image_url( $banner_id, 'full' );
		$head = '<!-- wp:cover {"url":"' . esc_url( $src ) . '","id":' . $banner_id . ',"dimRatio":50,"minHeight":380,"minHeightUnit":"px","contentPosition":"bottom left","align":"full","className":"gogh-shop-banner","layout":{"type":"constrained"}} -->' .
			'<div class="wp-block-cover alignfull has-custom-content-position is-position-bottom-left gogh-shop-banner" style="min-height:380px">' .
			'<span aria-hidden="true" class="wp-block-cover__background has-background-dim-50 has-background-dim"></span>' .
			'<img class="wp-block-cover__image-background wp-image-' . $banner_id . '" alt="" src="' . esc_url( $src ) . '" data-object-fit="cover"/>' .
			'<div class="wp-block-cover__inner-container">' .
			'<!-- wp:group {"align":"wide","className":"gogh-shop-head gogh-shop-head-editorial gogh-shop-head-banner","layout":{"type":"constrained"}} --><div class="wp-block-group alignwide gogh-shop-head gogh-shop-head-editorial gogh-shop-head-banner">' .
			'<!-- wp:query-title {"type":"archive","showPrefix":false,"align":"wide","className":"gogh-shop-title"} /-->' .
			'<!-- wp:term-description {"align":"wide","className":"gogh-shop-desc"} /-->' .
			'</div><!-- /wp:group -->' .
			'</div></div><!-- /wp:cover -->';
		$body = $toolbar . $collection;
	} elseif ( 'editorial' === $look ) {
		$head = '<!-- wp:group {"align":"wide","className":"gogh-shop-head gogh-shop-head-editorial","style":{"spacing":{"padding":{"top":"2.5rem","bottom":"1.5rem"}}},"layout":{"type":"constrained"}} --><div class="wp-block-group alignwide gogh-shop-head gogh-shop-head-editorial" style="padding-top:2.5rem;padding-bottom:1.5rem">' .
			'<!-- wp:query-title {"type":"archive","showPrefix":false,"align":"wide","className":"gogh-shop-title"} /-->' .
			'<!-- wp:term-description {"align":"wide","className":"gogh-shop-desc"} /-->' .
			$chips . '</div><!-- /wp:group -->';
		$body = $toolbar . $collection;
	} elseif ( 'gallery' === $look ) {
		$head = '<!-- wp:group {"align":"wide","className":"gogh-shop-head gogh-shop-head-gallery","style":{"spacing":{"padding":{"top":"2rem","bottom":"1rem"}}},"layout":{"type":"constrained"}} --><div class="wp-block-group alignwide gogh-shop-head gogh-shop-head-gallery" style="padding-top:2rem;padding-bottom:1rem">' .
			'<!-- wp:query-title {"type":"archive","showPrefix":false,"textAlign":"center","className":"gogh-shop-title"} /-->' .
			'<!-- wp:term-description {"align":"wide","className":"gogh-shop-desc"} /-->' .
			$chips . '</div><!-- /wp:group -->';
		$body = $toolbar . $collection;
	} else { // catalogue
		$filters = '<!-- wp:woocommerce/product-filters --><div class="wp-block-woocommerce-product-filters">' .
			'<!-- wp:woocommerce/product-filter-active --><div class="wp-block-woocommerce-product-filter-active"></div><!-- /wp:woocommerce/product-filter-active -->' .
			'<!-- wp:woocommerce/product-filter-price --><div class="wp-block-woocommerce-product-filter-price"><!-- wp:heading {"level":3,"fontSize":"medium"} --><h3 class="wp-block-heading has-medium-font-size">' . esc_html__( 'Price', 'gogh-editor' ) . '</h3><!-- /wp:heading --><!-- wp:woocommerce/product-filter-price-slider /--></div><!-- /wp:woocommerce/product-filter-price -->';
		if ( function_exists( 'wc_get_attribute_taxonomies' ) ) {
			foreach ( wc_get_attribute_taxonomies() as $attr ) {
				$filters .= '<!-- wp:woocommerce/product-filter-attribute {"attributeId":' . (int) $attr->attribute_id . '} --><div class="wp-block-woocommerce-product-filter-attribute"><!-- wp:heading {"level":3,"fontSize":"medium"} --><h3 class="wp-block-heading has-medium-font-size">' . esc_html( $attr->attribute_label ) . '</h3><!-- /wp:heading --><!-- wp:woocommerce/product-filter-checkbox-list /--></div><!-- /wp:woocommerce/product-filter-attribute -->';
			}
		}
		$filters .= '<!-- wp:woocommerce/product-filter-status --><div class="wp-block-woocommerce-product-filter-status"><!-- wp:heading {"level":3,"fontSize":"medium"} --><h3 class="wp-block-heading has-medium-font-size">' . esc_html__( 'Availability', 'gogh-editor' ) . '</h3><!-- /wp:heading --><!-- wp:woocommerce/product-filter-checkbox-list /--></div><!-- /wp:woocommerce/product-filter-status -->' .
			'</div><!-- /wp:woocommerce/product-filters -->';
		$head = '<!-- wp:woocommerce/breadcrumbs {"align":"wide"} /-->' .
			'<!-- wp:group {"align":"wide","className":"gogh-shop-head gogh-shop-head-catalogue","style":{"spacing":{"padding":{"top":"1.5rem","bottom":"1rem"}}},"layout":{"type":"constrained"}} --><div class="wp-block-group alignwide gogh-shop-head gogh-shop-head-catalogue" style="padding-top:1.5rem;padding-bottom:1rem">' .
			'<!-- wp:query-title {"type":"archive","showPrefix":false,"align":"wide","className":"gogh-shop-title"} /-->' .
			'<!-- wp:term-description {"align":"wide","className":"gogh-shop-desc"} /--></div><!-- /wp:group -->';
		$body = '<!-- wp:columns {"align":"wide","className":"gogh-shop-catalogue","style":{"spacing":{"blockGap":{"left":"3rem"}}}} --><div class="wp-block-columns alignwide gogh-shop-catalogue">' .
			'<!-- wp:column {"width":"26%","className":"gogh-shop-side"} --><div class="wp-block-column gogh-shop-side" style="flex-basis:26%">' . $filters . '</div><!-- /wp:column -->' .
			'<!-- wp:column {"width":"74%"} --><div class="wp-block-column" style="flex-basis:74%">' . $toolbar . $collection . '</div><!-- /wp:column -->' .
			'</div><!-- /wp:columns -->';
	}
	return '<!-- wp:template-part {"slug":"header"} /-->' .
		'<!-- wp:group {"tagName":"main","layout":{"inherit":true,"type":"constrained"},"style":{"spacing":{"margin":{"top":"0","bottom":"0"}}}} --><main class="wp-block-group" style="margin-top:0;margin-bottom:0">' .
		$head . '<!-- wp:woocommerce/store-notices /-->' . $body .
		'</main><!-- /wp:group -->' .
		'<!-- wp:template-part {"slug":"footer"} /-->';
}
// the swap: when a look is chosen for this kind of page, the archive
// template's CONTENT is gogh's — the template itself, its slug and Woo's
// ownership stay exactly as they were (Classic = no swap at all)
add_filter( 'get_block_templates', function ( $templates, $query, $template_type ) {
	if ( 'wp_template' !== $template_type || is_admin() || ! is_array( $templates ) ) {
		return $templates;
	}
	$kind = gogh_shop_look_kind();
	$look = $kind ? gogh_shop_look_active( $kind ) : '';
	if ( ! $look ) {
		return $templates;
	}
	foreach ( $templates as $t ) {
		if ( is_object( $t ) && isset( $t->slug ) && in_array( $t->slug, array( 'archive-product', 'taxonomy-product_cat', 'taxonomy-product_tag' ), true ) ) {
			$t->content = gogh_shop_archive_markup( $look, $kind );
			$t->description = 'gogh · ' . $look;
		}
	}
	return $templates;
}, 20, 3 );
add_filter( 'body_class', function ( $classes ) {
	$kind = gogh_shop_look_kind();
	$look = $kind ? gogh_shop_look_active( $kind ) : '';
	if ( $look ) {
		$classes[] = 'gogh-shoplook-' . $look;
		$classes[] = 'gogh-shoplook-kind-' . $kind;
	}
	return $classes;
}, 20 );
add_action( 'admin_post_gogh_shop_layout', function () {
	if ( ! current_user_can( 'edit_theme_options' ) ) {
		wp_die( esc_html__( 'You cannot change the shop layout.', 'gogh-editor' ) );
	}
	check_admin_referer( 'gogh_shop_layout' );
	$kind   = isset( $_GET['kind'] ) && 'category' === $_GET['kind'] ? 'category' : 'shop';
	$layout = isset( $_GET['layout'] ) ? sanitize_key( wp_unslash( $_GET['layout'] ) ) : '';
	if ( ! array_key_exists( $layout, gogh_shop_looks() ) ) {
		wp_die( esc_html__( 'Unknown layout.', 'gogh-editor' ) );
	}
	$term = isset( $_GET['term'] ) ? (int) $_GET['term'] : 0;
	$all  = isset( $_GET['all'] ) && '1' === $_GET['all'];
	if ( 'category' === $kind && $term && ! $all ) {
		// one category's own look ('classic' records an explicit Woo's-own)
		update_term_meta( $term, '_gogh_shop_look', '' === $layout ? 'classic' : $layout );
	} else {
		update_option( 'shop' === $kind ? 'gogh_shop_layout' : 'gogh_category_layout', $layout );
		if ( 'category' === $kind ) {
			// stamp every category — each can still be changed afterwards, one at a time
			foreach ( get_terms( array( 'taxonomy' => array( 'product_cat', 'product_tag' ), 'hide_empty' => false, 'fields' => 'ids' ) ) as $tid ) {
				delete_term_meta( $tid, '_gogh_shop_look' );
			}
		}
	}
	$back = isset( $_GET['back'] ) ? esc_url_raw( wp_unslash( $_GET['back'] ) ) : '';
	wp_safe_redirect( $back ? $back : home_url( '/' ) );
	exit;
} );
// ---------- Variations: one modal with a live preview (phase two, admin) ----------
// Where beginners abandon Woo: attributes on one tab, variations on another,
// a 'Generate' button hidden in a dropdown. Gogh asks one question — what
// varies? — draws the storefront selector as you type, and creates every
// combination itself. Woo's own tab stays for stock, SKUs and the rest.
add_action( 'add_meta_boxes_product', function ( $post ) {
	if ( ! function_exists( 'wc_get_product' ) || ! current_user_can( 'edit_post', $post->ID ) ) {
		return;
	}
	add_meta_box( 'gogh-variations', __( 'Variations', 'gogh-editor' ), function ( $post ) {
		$product  = wc_get_product( $post->ID );
		$is_draft = 'auto-draft' === get_post_status( $post );
		$n        = $product && $product->is_type( 'variable' ) ? count( $product->get_children() ) : 0;
		$names    = array();
		if ( $product ) {
			foreach ( $product->get_attributes() as $attr ) {
				if ( is_object( $attr ) && $attr->get_variation() ) {
					$names[] = wc_attribute_label( $attr->get_name() );
				}
			}
		}
		echo '<div id="gogh-variations-box" data-product="' . (int) $post->ID . '">';
		if ( $n ) {
			/* translators: 1: variation count, 2: attribute names */
			echo '<p class="gogh-var-summary"><strong>' . esc_html( sprintf( _n( '%1$d variation', '%1$d variations', $n, 'gogh-editor' ), $n ) ) . '</strong> · ' . esc_html( implode( ' · ', $names ) ) . '</p>';
		} else {
			echo '<p class="gogh-var-summary">' . esc_html__( 'One of a kind so far.', 'gogh-editor' ) . '</p>';
		}
		if ( $is_draft ) {
			echo '<button type="button" class="button" disabled>' . esc_html__( 'Set up variations', 'gogh-editor' ) . '</button>';
			echo '<p class="description">' . esc_html__( 'Save the product once, then come back here.', 'gogh-editor' ) . '</p>';
		} else {
			echo '<button type="button" class="button button-primary gogh-var-open">' . esc_html( $n ? __( 'Edit variations', 'gogh-editor' ) : __( 'Set up variations', 'gogh-editor' ) ) . '</button>';
			echo '<p class="description">' . esc_html__( 'Colour, size, whatever varies — one screen, and every combination is created for you.', 'gogh-editor' ) . '</p>';
		}
		echo '</div>';
	}, 'product', 'side', 'high' );
} );
add_action( 'admin_enqueue_scripts', function ( $hook ) {
	if ( ! in_array( $hook, array( 'post.php', 'post-new.php' ), true ) || ! function_exists( 'wc_get_product' ) ) {
		return;
	}
	$screen = function_exists( 'get_current_screen' ) ? get_current_screen() : null;
	$post   = get_post();
	if ( ! $screen || 'product' !== $screen->id || ! $post ) {
		return;
	}
	$product = wc_get_product( $post->ID );
	$globals = array();
	if ( function_exists( 'wc_get_attribute_taxonomies' ) ) {
		foreach ( wc_get_attribute_taxonomies() as $tax ) {
			$globals[] = $tax->attribute_label;
		}
	}
	wp_enqueue_script( 'gogh-admin', plugins_url( 'gogh-admin.js', __FILE__ ), array(), '0.99.421-chrome', true );
	wp_enqueue_style( 'gogh-admin', plugins_url( 'gogh-admin.css', __FILE__ ), array(), '0.99.421-chrome' );
	wp_localize_script( 'gogh-admin', 'GOGH_ADMIN', array(
		'restUrl'   => esc_url_raw( rest_url( 'wc/v3/' ) ),
		'nonce'     => wp_create_nonce( 'wp_rest' ),
		'productId' => $post->ID,
		'name'      => get_the_title( $post ),
		'price'     => $product ? (string) $product->get_regular_price() : '',
		'currency'  => function_exists( 'get_woocommerce_currency_symbol' ) ? html_entity_decode( get_woocommerce_currency_symbol(), ENT_QUOTES, 'UTF-8' ) : '',
		'thumb'     => get_the_post_thumbnail_url( $post, 'medium' ) ?: '',
		'globals'   => $globals,
	) );
} );
// the product form wears gogh's shape only on the classic product screen
add_filter( 'admin_body_class', function ( $classes ) {
	$screen = function_exists( 'get_current_screen' ) ? get_current_screen() : null;
	if ( $screen && 'product' === $screen->id && 'post' === $screen->base && function_exists( 'wc_get_product' ) ) {
		$classes .= ' gogh-productform';
	}
	return $classes;
} );
// a placeholder that teaches: a name people would say out loud
add_filter( 'enter_title_here', function ( $text, $post ) {
	if ( $post && 'product' === $post->post_type ) {
		return __( 'Product name — e.g. Lavender bar, cut by hand', 'gogh-editor' );
	}
	return $text;
}, 10, 2 );
add_action( 'admin_notices', function () {
	if ( isset( $_GET['gogh-variations'] ) && 'done' === $_GET['gogh-variations'] ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__( 'Variations created. They are in the Variations tab below, priced and ready to sell.', 'gogh-editor' ) . '</p></div>';
	}
} );
// ---------- Launch: a goal-grouped checklist, not a wizard (phase two) ----------
// Woo's onboarding stops when the settings are filled in. A shop that is set
// up but looks like nothing is not launched — so this list runs on through
// design, and it reads the site's real state every time (nothing to tick).
function gogh_launch_groups() {
	if ( ! function_exists( 'wc_get_products' ) ) {
		return array();
	}
	$products = wc_get_products( array( 'status' => 'publish', 'limit' => -1 ) );
	$no_pic   = 0;
	$virtual  = count( $products ) > 0;
	foreach ( $products as $pr ) {
		if ( ! $pr->get_image_id() ) {
			$no_pic++;
		}
		if ( ! $pr->is_virtual() ) {
			$virtual = false;
		}
	}
	$shipping = $virtual;
	if ( ! $shipping && class_exists( 'WC_Shipping_Zones' ) ) {
		foreach ( WC_Shipping_Zones::get_zones() as $z ) {
			if ( ! empty( $z['shipping_methods'] ) ) {
				$shipping = true;
			}
		}
		if ( ! $shipping && count( ( new WC_Shipping_Zone( 0 ) )->get_shipping_methods( true ) ) ) {
			$shipping = true;
		}
	}
	$gateways = array();
	if ( function_exists( 'WC' ) && WC()->payment_gateways() ) {
		foreach ( WC()->payment_gateways()->payment_gateways() as $g ) {
			if ( 'yes' === $g->enabled ) {
				$gateways[] = $g->get_title();
			}
		}
	}
	$orders   = function_exists( 'wc_get_orders' ) ? count( wc_get_orders( array( 'limit' => 1, 'return' => 'ids' ) ) ) : 0;
	$page_ok  = function ( $id ) { return $id && 'publish' === get_post_status( (int) $id ); };
	$front    = (int) get_option( 'page_on_front' );
	$front_ok = 'page' === get_option( 'show_on_front' ) && $front && false !== strpos( (string) get_post_field( 'post_content', $front ), 'wp:gogh/section' );
	$name     = trim( (string) get_option( 'blogname' ) );
	$soon     = 'yes' === get_option( 'woocommerce_coming_soon' );
	$shop_url = function_exists( 'wc_get_page_permalink' ) ? wc_get_page_permalink( 'shop' ) : home_url( '/' );
	$item     = function ( $title, $why, $done, $verb, $url ) {
		return array( 'title' => $title, 'why' => $why, 'done' => (bool) $done, 'verb' => $verb, 'url' => $url );
	};
	return array(
		array( 'title' => __( 'Set up your shop', 'gogh-editor' ), 'items' => array(
			$item( __( 'Name your shop', 'gogh-editor' ), __( 'It heads every page, every email and every receipt.', 'gogh-editor' ), $name && ! in_array( strtolower( $name ), array( 'my wordpress', 'wordpress', 'my site', 'site title' ), true ), __( 'Name it', 'gogh-editor' ), admin_url( 'options-general.php' ) ),
			$item( __( 'Add your first product', 'gogh-editor' ), __( 'A name and a price make it sellable.', 'gogh-editor' ), count( $products ) > 0, __( 'Add a product', 'gogh-editor' ), admin_url( 'post-new.php?post_type=product' ) ),
			/* translators: %d: products without a picture */
			$item( __( 'Give every product a picture', 'gogh-editor' ), $no_pic ? sprintf( _n( '%d product has no picture yet.', '%d products have no picture yet.', $no_pic, 'gogh-editor' ), $no_pic ) : __( 'People buy what they can see.', 'gogh-editor' ), count( $products ) > 0 && 0 === $no_pic, __( 'See products', 'gogh-editor' ), admin_url( 'edit.php?post_type=product' ) ),
			$item( __( 'Country and currency', 'gogh-editor' ), __( 'Prices, tax and shipping all follow from these two.', 'gogh-editor' ), get_option( 'woocommerce_default_country' ) && get_option( 'woocommerce_currency' ), __( 'Check settings', 'gogh-editor' ), admin_url( 'admin.php?page=wc-settings' ) ),
			$item( __( 'Your store address', 'gogh-editor' ), __( 'It appears on receipts, and shipping rates start from here.', 'gogh-editor' ), '' !== trim( (string) get_option( 'woocommerce_store_address' ) ), __( 'Add address', 'gogh-editor' ), admin_url( 'admin.php?page=wc-settings' ) ),
			$item( __( 'A way to ship', 'gogh-editor' ), $virtual ? __( 'Everything you sell is digital — nothing to post.', 'gogh-editor' ) : __( 'One zone with one rate is enough to start: flat rate, or free.', 'gogh-editor' ), $shipping, __( 'Set up shipping', 'gogh-editor' ), admin_url( 'admin.php?page=wc-settings&tab=shipping' ) ),
		) ),
		array( 'title' => __( 'Get paid', 'gogh-editor' ), 'items' => array(
			$item( __( 'A way to take payment', 'gogh-editor' ), $gateways ? sprintf( __( 'On: %s.', 'gogh-editor' ), implode( ', ', $gateways ) ) : __( 'Cards and wallets in one step, everything else behind a link.', 'gogh-editor' ), count( $gateways ) > 0, __( 'Get paid', 'gogh-editor' ), admin_url( 'admin.php?page=gogh-payments' ) ),
			$item( __( 'Place a test order', 'gogh-editor' ), __( 'Buy something from yourself once — checkout, the email, the order screen.', 'gogh-editor' ), $orders > 0, __( 'Go to the shop', 'gogh-editor' ), $shop_url ),
		) ),
		array( 'title' => __( 'Legal pages', 'gogh-editor' ), 'items' => array(
			$item( __( 'Privacy policy', 'gogh-editor' ), __( 'WordPress drafts one for you; publish it and point to it.', 'gogh-editor' ), $page_ok( get_option( 'wp_page_for_privacy_policy' ) ), __( 'Privacy settings', 'gogh-editor' ), admin_url( 'options-privacy.php' ) ),
			$item( __( 'Terms and conditions', 'gogh-editor' ), __( 'Shown at checkout; a short, honest page beats a long copied one.', 'gogh-editor' ), $page_ok( get_option( 'woocommerce_terms_page_id' ) ), __( 'Choose the page', 'gogh-editor' ), admin_url( 'admin.php?page=wc-settings&tab=advanced' ) ),
			$item( __( 'Refunds and returns', 'gogh-editor' ), __( 'Say what happens when something goes wrong, before it does.', 'gogh-editor' ), $page_ok( get_option( 'woocommerce_refund_returns_page_id' ) ), __( 'Choose the page', 'gogh-editor' ), admin_url( 'admin.php?page=wc-settings&tab=advanced' ) ),
		) ),
		array( 'title' => __( 'Ready to launch', 'gogh-editor' ), 'items' => array(
			$item( __( 'A home page with a story', 'gogh-editor' ), __( 'The first thing anyone sees. Designed with gogh, it says who you are.', 'gogh-editor' ), $front_ok, __( 'Design the home page', 'gogh-editor' ), $front ? add_query_arg( 'gogh-edit', '1', get_permalink( $front ) ) : home_url( '/?gogh-edit=1' ) ),
			$item( __( 'A look for the shop page', 'gogh-editor' ), __( 'Editorial, Gallery or Catalogue — pick it from the bar on the shop page.', 'gogh-editor' ), '' !== (string) get_option( 'gogh_shop_layout', '' ), __( 'Open the shop', 'gogh-editor' ), $shop_url ),
			$item( __( 'Your logo in the header', 'gogh-editor' ), __( 'Click the header while editing any page to place it.', 'gogh-editor' ), (int) get_theme_mod( 'custom_logo' ) > 0, __( 'Edit the header', 'gogh-editor' ), home_url( '/?gogh-edit=1' ) ),
			$item( __( 'Open the doors', 'gogh-editor' ), $soon ? __( 'The shop is behind Coming soon. When the rest is done, let people in.', 'gogh-editor' ) : __( 'The shop is live for everyone.', 'gogh-editor' ), ! $soon, __( 'Site visibility', 'gogh-editor' ), admin_url( 'admin.php?page=wc-settings&tab=site-visibility' ) ),
		) ),
	);
}
function gogh_launch_progress() {
	$done = 0;
	$all  = 0;
	foreach ( gogh_launch_groups() as $g ) {
		foreach ( $g['items'] as $it ) {
			$all++;
			if ( $it['done'] ) {
				$done++;
			}
		}
	}
	return array( $done, $all );
}
add_action( 'admin_menu', function () {
	if ( ! function_exists( 'wc_get_products' ) ) {
		return;
	}
	add_submenu_page( 'woocommerce', __( 'Launch your shop', 'gogh-editor' ), __( 'Launch', 'gogh-editor' ), 'manage_woocommerce', 'gogh-launch', 'gogh_launch_page', 1 );
	// off the menu (Launch is its door); a hidden page gets no title of its own, so admin_title supplies one below
	add_submenu_page( '', __( 'Get paid', 'gogh-editor' ), '', 'manage_woocommerce', 'gogh-payments', 'gogh_payments_page' );
}, 60 );
add_filter( 'admin_title', function ( $title ) {
	if ( isset( $_GET['page'] ) && 'gogh-payments' === $_GET['page'] ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		return __( 'Get paid', 'gogh-editor' ) . ' &lsaquo; ' . get_bloginfo( 'name' ) . ' &#8212; WordPress';
	}
	return $title;
} );
function gogh_launch_css() {
	return '.gogh-launch{max-width:860px;margin:24px 0}.gogh-launch h1{font-size:28px;font-weight:600;letter-spacing:-.01em;margin:0 0 6px}.gogh-launch-lede{font-size:15px;color:#50575e;margin:0 0 18px;max-width:60ch}' .
		'.gogh-launch-bar{height:8px;border-radius:999px;background:#e5e7eb;overflow:hidden;margin:0 0 6px}.gogh-launch-bar i{display:block;height:100%;background:#1f5a3f;border-radius:999px;transition:width .4s}' .
		'.gogh-launch-count{font-size:13px;color:#646970;margin:0 0 26px}' .
		'.gogh-launch-group{background:#fff;border:1px solid #dcdcde;border-radius:12px;margin:0 0 18px;overflow:hidden}.gogh-launch-group h2{display:flex;justify-content:space-between;align-items:baseline;margin:0;padding:14px 20px;font-size:16px;font-weight:600;border-bottom:1px solid #f0f0f1}.gogh-launch-group h2 span{font-size:12px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#646970}.gogh-launch-group h2 span.is-done{color:#1e5631}' .
		'.gogh-launch-item{display:grid;grid-template-columns:28px 1fr auto;gap:0 14px;align-items:center;padding:14px 20px;border-bottom:1px solid #f0f0f1}.gogh-launch-item:last-child{border-bottom:0}' .
		'.gogh-launch-mark{width:22px;height:22px;border-radius:50%;border:2px solid #c3c4c7;display:grid;place-items:center;font-size:13px;color:#fff}.gogh-launch-item.is-done .gogh-launch-mark{background:#1f5a3f;border-color:#1f5a3f}' .
		'.gogh-launch-item strong{display:block;font-size:14px;color:#1d2327}.gogh-launch-item.is-done strong{color:#646970;text-decoration:line-through;text-decoration-color:#c3c4c7}.gogh-launch-item small{display:block;font-size:13px;color:#646970;margin-top:2px}' .
		'.gogh-launch-item .button{white-space:nowrap}.gogh-launch-item.is-done .button{visibility:hidden}' .
		'.gogh-launch-foot{font-size:13px;color:#646970;margin:8px 0 0}' .
		'.gogh-pay-card{background:#fff;border:1px solid #dcdcde;border-radius:12px;padding:22px 24px;margin:0 0 16px;max-width:640px}.gogh-pay-card h2{margin:0 0 6px;font-size:18px;font-weight:600}.gogh-pay-card p{margin:0 0 12px;font-size:14px;color:#50575e;max-width:56ch}.gogh-pay-badges{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 14px}.gogh-pay-badges span{border:1px solid #dcdcde;border-radius:999px;padding:4px 10px;font-size:12px;color:#1d2327;background:#f6f7f7}' .
		'.gogh-pay-on{display:inline-block;background:#e6f4ea;color:#1e5631;border-radius:999px;padding:4px 10px;font-size:12px;font-weight:600;margin:0 0 10px}' .
		'.gogh-pay-more summary{cursor:pointer;font-size:14px;color:#1f5a3f;font-weight:600}.gogh-pay-more ul{margin:10px 0 0 0;padding:0;list-style:none}.gogh-pay-more li{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #f0f0f1;font-size:14px}.gogh-pay-more li em{font-style:normal;color:#646970}';
}
function gogh_launch_page() {
	$groups = gogh_launch_groups();
	list( $done, $all ) = gogh_launch_progress();
	echo '<style>' . gogh_launch_css() . '</style><div class="wrap gogh-launch">'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
	echo '<h1>' . esc_html__( 'Launch your shop', 'gogh-editor' ) . '</h1>';
	echo '<p class="gogh-launch-lede">' . esc_html__( 'Not a wizard — a list that reads your shop as it really is, and keeps going past the settings, through design, until people can buy.', 'gogh-editor' ) . '</p>';
	$pct = $all ? round( $done / $all * 100 ) : 0;
	echo '<div class="gogh-launch-bar"><i style="width:' . (int) $pct . '%"></i></div>';
	/* translators: 1: done, 2: total */
	echo '<p class="gogh-launch-count">' . esc_html( sprintf( __( '%1$d of %2$d done', 'gogh-editor' ), $done, $all ) ) . ( $done === $all ? ' — ' . esc_html__( 'the doors are open.', 'gogh-editor' ) : '' ) . '</p>';
	foreach ( $groups as $g ) {
		$gd = count( array_filter( $g['items'], function ( $i ) { return $i['done']; } ) );
		$ga = count( $g['items'] );
		echo '<section class="gogh-launch-group"><h2>' . esc_html( $g['title'] ) . '<span class="' . ( $gd === $ga ? 'is-done' : '' ) . '">' . (int) $gd . '/' . (int) $ga . '</span></h2>';
		foreach ( $g['items'] as $it ) {
			echo '<div class="gogh-launch-item' . ( $it['done'] ? ' is-done' : '' ) . '">' .
				'<span class="gogh-launch-mark" aria-hidden="true">' . ( $it['done'] ? '&#10003;' : '' ) . '</span>' .
				'<div><strong>' . esc_html( $it['title'] ) . '</strong><small>' . esc_html( $it['why'] ) . '</small></div>' .
				'<a class="button" href="' . esc_url( $it['url'] ) . '">' . esc_html( $it['verb'] ) . '</a></div>';
		}
		echo '</section>';
	}
	echo '<p class="gogh-launch-foot">' . esc_html__( 'Nothing here is ticked by hand: fix the thing and the list notices.', 'gogh-editor' ) . '</p></div>';
}
// one path to getting paid: cards and wallets in a step, the rest behind a link
function gogh_payments_page() {
	$installed = file_exists( WP_PLUGIN_DIR . '/woocommerce-payments/woocommerce-payments.php' );
	$active    = class_exists( 'WC_Payments' ) || is_plugin_active( 'woocommerce-payments/woocommerce-payments.php' );
	$enabled   = false;
	$others    = array();
	if ( function_exists( 'WC' ) && WC()->payment_gateways() ) {
		foreach ( WC()->payment_gateways()->payment_gateways() as $g ) {
			if ( 'woocommerce_payments' === $g->id ) {
				$enabled = 'yes' === $g->enabled;
			} else {
				$others[] = array( 'title' => $g->get_method_title(), 'on' => 'yes' === $g->enabled );
			}
		}
	}
	echo '<style>' . gogh_launch_css() . '</style><div class="wrap gogh-launch">'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
	echo '<h1>' . esc_html__( 'Get paid', 'gogh-editor' ) . '</h1>';
	echo '<p class="gogh-launch-lede">' . esc_html__( 'One way to take cards and wallets, set up in a few minutes. Everything else lives behind a link, for the day you need it.', 'gogh-editor' ) . '</p>';
	echo '<div class="gogh-pay-card">';
	if ( $enabled ) {
		echo '<span class="gogh-pay-on">' . esc_html__( 'On', 'gogh-editor' ) . '</span>';
	}
	echo '<h2>WooPayments</h2>';
	echo '<div class="gogh-pay-badges"><span>Visa</span><span>Mastercard</span><span>Amex</span><span>Apple Pay</span><span>Google Pay</span></div>';
	echo '<p>' . esc_html__( 'Built by the people who make WooCommerce. A small fee per sale and nothing monthly; the money lands in your bank account on a schedule you choose. Available in most countries — the setup tells you at once if yours is not.', 'gogh-editor' ) . '</p>';
	if ( $enabled ) {
		echo '<a class="button" href="' . esc_url( admin_url( 'admin.php?page=wc-admin&path=/payments/overview' ) ) . '">' . esc_html__( 'Open WooPayments', 'gogh-editor' ) . '</a>';
	} elseif ( $active ) {
		echo '<a class="button button-primary button-hero" href="' . esc_url( admin_url( 'admin.php?page=wc-admin&path=/payments/connect' ) ) . '">' . esc_html__( 'Finish setting up WooPayments', 'gogh-editor' ) . '</a>';
	} elseif ( $installed && current_user_can( 'activate_plugins' ) ) {
		echo '<a class="button button-primary button-hero" href="' . esc_url( wp_nonce_url( self_admin_url( 'plugins.php?action=activate&plugin=woocommerce-payments/woocommerce-payments.php' ), 'activate-plugin_woocommerce-payments/woocommerce-payments.php' ) ) . '">' . esc_html__( 'Turn on WooPayments', 'gogh-editor' ) . '</a>';
	} elseif ( current_user_can( 'install_plugins' ) ) {
		echo '<a class="button button-primary button-hero" href="' . esc_url( wp_nonce_url( self_admin_url( 'update.php?action=install-plugin&plugin=woocommerce-payments' ), 'install-plugin_woocommerce-payments' ) ) . '">' . esc_html__( 'Add WooPayments', 'gogh-editor' ) . '</a>';
		echo '<p style="margin-top:10px">' . esc_html__( 'Installs the free WooPayments plugin from WordPress.org, then walks you through connecting a bank account.', 'gogh-editor' ) . '</p>';
	} else {
		echo '<p>' . esc_html__( 'Ask an administrator to add the WooPayments plugin.', 'gogh-editor' ) . '</p>';
	}
	echo '</div>';
	echo '<details class="gogh-pay-more gogh-pay-card"><summary>' . esc_html__( 'More payment options', 'gogh-editor' ) . '</summary>';
	echo '<p style="margin-top:10px">' . esc_html__( 'Bank transfer, cash on delivery, PayPal and the rest. Turn one on if that is how your customers already pay you.', 'gogh-editor' ) . '</p><ul>';
	foreach ( $others as $o ) {
		echo '<li>' . esc_html( $o['title'] ) . '<em>' . ( $o['on'] ? esc_html__( 'on', 'gogh-editor' ) : esc_html__( 'off', 'gogh-editor' ) ) . '</em></li>';
	}
	echo '</ul><p style="margin-top:12px"><a class="button" href="' . esc_url( admin_url( 'admin.php?page=wc-settings&tab=checkout' ) ) . '">' . esc_html__( 'All payment settings', 'gogh-editor' ) . '</a></p></details>';
	echo '<p class="gogh-launch-foot"><a href="' . esc_url( admin_url( 'admin.php?page=gogh-launch' ) ) . '">&larr; ' . esc_html__( 'Back to Launch your shop', 'gogh-editor' ) . '</a></p></div>';
}
// the count rides the admin bar until the doors are open
add_action( 'admin_bar_menu', function ( $bar ) {
	if ( ! is_admin() || ! function_exists( 'wc_get_products' ) || ! current_user_can( 'manage_woocommerce' ) ) {
		return;
	}
	list( $done, $all ) = gogh_launch_progress();
	if ( ! $all || $done === $all ) {
		return;
	}
	$bar->add_node( array(
		'id'    => 'gogh-launch',
		'title' => '🚀 ' . sprintf( __( 'Launch %1$d/%2$d', 'gogh-editor' ), $done, $all ),
		'href'  => admin_url( 'admin.php?page=gogh-launch' ),
		'meta'  => array( 'title' => __( 'Launch your shop — what is left', 'gogh-editor' ) ),
	) );
}, 90 );
// 'You might also like' on product pages: on by default (it sells), one
// click off for a maker with three products (James: 'folks might want
// to hide the you might also like section')
add_filter( 'render_block_core/group', function ( $html, $block ) {
	$cls = isset( $block['attrs']['className'] ) ? (string) $block['attrs']['className'] : '';
	if ( false !== strpos( $cls, 'gogh-related' ) && '0' === (string) get_option( 'gogh_product_related', '1' ) ) {
		return '';
	}
	return $html;
}, 10, 2 );
add_action( 'admin_post_gogh_product_related', function () {
	if ( ! current_user_can( 'edit_theme_options' ) ) {
		wp_die( esc_html__( 'You cannot change this.', 'gogh-editor' ) );
	}
	check_admin_referer( 'gogh_product_related' );
	update_option( 'gogh_product_related', '0' === (string) get_option( 'gogh_product_related', '1' ) ? '1' : '0' );
	$back = isset( $_GET['back'] ) ? esc_url_raw( wp_unslash( $_GET['back'] ) ) : '';
	wp_safe_redirect( $back ? $back : home_url( '/' ) );
	exit;
} );

add_action( 'admin_post_gogh_product_layout_all', function () {
	$id = isset( $_GET['id'] ) ? (int) $_GET['id'] : 0;
	if ( ! current_user_can( 'edit_others_posts' ) ) {
		wp_die( esc_html__( 'You cannot change other products.', 'gogh-editor' ) );
	}
	check_admin_referer( 'gogh_product_layout_all' );
	$layout = $id ? get_page_template_slug( $id ) : '';
	if ( ! array_key_exists( $layout, gogh_product_layouts() ) ) {
		$layout = '';
	}
	$ids = get_posts( array(
		'post_type'      => 'product',
		'post_status'    => 'any',
		'posts_per_page' => -1,
		'fields'         => 'ids',
	) );
	foreach ( $ids as $prod_id ) {
		if ( '' === $layout ) {
			delete_post_meta( $prod_id, '_wp_page_template' );
		} else {
			update_post_meta( $prod_id, '_wp_page_template', $layout );
		}
	}
	wp_safe_redirect( $id ? get_permalink( $id ) : home_url( '/' ) );
	exit;
} );

/**
 * Post layouts: the reading looks, as a fixed menu on the admin bar —
 * one per post, or stamped across every post in one click.
 */
function gogh_post_layouts() {
	return array(
		''           => __( 'Theme default — the theme\'s own post', 'gogh-editor' ),
		'magazine'   => __( 'Magazine — big opener, generous columns', 'gogh-editor' ),
		'journal'    => __( 'Journal — quiet, dated, personal', 'gogh-editor' ),
		'essay'      => __( 'Essay — one calm column of type', 'gogh-editor' ),
		'gazette'    => __( 'Gazette — newspaper rhythm', 'gogh-editor' ),
		'photostory' => __( 'Photo story — pictures lead', 'gogh-editor' ),
		'feature'    => __( 'Feature — long-form, art-directed', 'gogh-editor' ),
		'cover'      => __( 'Cover — the photo is the title page', 'gogh-editor' ),
		'manual'     => __( 'Manual — side contents, tables and code', 'gogh-editor' ),
	);
}
add_action( 'admin_post_gogh_blog_layout', function () {
	if ( ! current_user_can( 'edit_theme_options' ) ) {
		wp_die( esc_html__( 'You cannot change the blog layout.', 'gogh-editor' ) );
	}
	check_admin_referer( 'gogh_blog_layout' );
	$layout = isset( $_GET['layout'] ) ? sanitize_key( wp_unslash( $_GET['layout'] ) ) : '';
	if ( ! in_array( $layout, gogh_blog_styles(), true ) ) {
		wp_die( esc_html__( 'Unknown layout.', 'gogh-editor' ) );
	}
	update_option( 'gogh_blog_style', $layout );
	$back = isset( $_GET['back'] ) ? esc_url_raw( wp_unslash( $_GET['back'] ) ) : '';
	wp_safe_redirect( $back ? $back : home_url( '/' ) );
	exit;
} );
add_action( 'admin_post_gogh_post_layout', function () {
	$id     = isset( $_GET['id'] ) ? (int) $_GET['id'] : 0;
	$layout = isset( $_GET['layout'] ) ? sanitize_key( wp_unslash( $_GET['layout'] ) ) : '';
	if ( ! $id || ! current_user_can( 'edit_post', $id ) ) {
		wp_die( esc_html__( 'You cannot edit this post.', 'gogh-editor' ) );
	}
	check_admin_referer( 'gogh_post_layout_' . $id );
	if ( ! array_key_exists( $layout, gogh_post_layouts() ) ) {
		wp_die( esc_html__( 'Unknown layout.', 'gogh-editor' ) );
	}
	if ( '' === $layout ) {
		delete_post_meta( $id, '_gogh_post_style' );
	} else {
		update_post_meta( $id, '_gogh_post_style', $layout );
	}
	wp_safe_redirect( get_permalink( $id ) );
	exit;
} );
add_action( 'admin_post_gogh_post_layout_all', function () {
	$id = isset( $_GET['id'] ) ? (int) $_GET['id'] : 0;
	if ( ! current_user_can( 'edit_others_posts' ) ) {
		wp_die( esc_html__( 'You cannot change other posts.', 'gogh-editor' ) );
	}
	check_admin_referer( 'gogh_post_layout_all' );
	$layout = $id ? (string) get_post_meta( $id, '_gogh_post_style', true ) : '';
	if ( ! array_key_exists( $layout, gogh_post_layouts() ) ) {
		$layout = '';
	}
	$ids = get_posts( array( 'post_type' => 'post', 'post_status' => 'any', 'numberposts' => -1, 'fields' => 'ids' ) );
	foreach ( $ids as $pid ) {
		if ( '' === $layout ) {
			delete_post_meta( $pid, '_gogh_post_style' );
		} else {
			update_post_meta( $pid, '_gogh_post_style', $layout );
		}
	}
	wp_safe_redirect( $id ? get_permalink( $id ) : home_url( '/' ) );
	exit;
} );
// a product that never chose a layout wears Story — so gogh works on every
// product page from the first one, and 'Edit with gogh' is never a dead door
add_filter( 'get_post_metadata', function ( $value, $object_id, $meta_key, $single ) {
	if ( '_wp_page_template' !== $meta_key || is_admin() || ! class_exists( 'WooCommerce' ) ) {
		return $value;
	}
	if ( 'product' !== get_post_type( $object_id ) ) {
		return $value;
	}
	static $guard = false;
	if ( $guard ) {
		return $value;
	}
	$guard = true;
	$real  = get_post_meta( $object_id, '_wp_page_template', true );
	$guard = false;
	if ( $real && 'default' !== $real ) {
		return $value;
	}
	return $single ? 'gogh-product-story' : array( 'gogh-product-story' );
}, 10, 4 );
add_action( 'admin_post_gogh_product_layout', function () {
	$id     = isset( $_GET['id'] ) ? (int) $_GET['id'] : 0;
	$layout = isset( $_GET['layout'] ) ? sanitize_text_field( wp_unslash( $_GET['layout'] ) ) : '';
	if ( ! $id || ! current_user_can( 'edit_post', $id ) ) {
		wp_die( esc_html__( 'You cannot edit this product.', 'gogh-editor' ) );
	}
	check_admin_referer( 'gogh_product_layout_' . $id );
	if ( ! array_key_exists( $layout, gogh_product_layouts() ) ) {
		wp_die( esc_html__( 'Unknown layout.', 'gogh-editor' ) );
	}
	if ( '' === $layout ) {
		delete_post_meta( $id, '_wp_page_template' );
		wp_safe_redirect( get_permalink( $id ) );
	} else {
		update_post_meta( $id, '_wp_page_template', $layout );
		wp_safe_redirect( add_query_arg( 'gogh-edit', '1', get_permalink( $id ) ) );
	}
	exit;
} );

/**
 * Wrapped images: text flows around a floated image's silhouette via
 * shape-outside. KSES must not strip the properties (or the img style) for
 * users below unfiltered_html.
 */
add_filter( 'safe_style_css', function ( $props ) {
	$props[] = 'float';
	$props[] = 'shape-outside';
	$props[] = 'shape-margin';
	$props[] = 'shape-image-threshold';
	$props[] = 'object-position'; // break-image focal point rides inline
	return $props;
} );
add_filter( 'wp_kses_allowed_html', function ( $tags, $context ) {
	if ( 'post' === $context && isset( $tags['img'] ) ) {
		$tags['img']['style'] = true;
	}
	if ( 'post' === $context ) {
		// video elements and backgrounds: a silent, looping, inline-playing
		// <video> must survive KSES for authors without unfiltered_html
		$tags['video'] = array_merge( isset( $tags['video'] ) ? $tags['video'] : array(), array(
			'class' => true, 'src' => true, 'poster' => true, 'autoplay' => true, 'muted' => true, 'loop' => true,
			'playsinline' => true, 'controls' => true, 'preload' => true, 'aria-hidden' => true, 'tabindex' => true,
		) );
	}
	return $tags;
}, 10, 2 );

/**
 * Core keys plugin-registered templates by NAME ('gogh//blank-canvas') when
 * it merges them into get_block_templates() results, but wp-includes/
 * block-editor.php reads [0] from that array — on a page using our Blank
 * canvas template the block editor emits warnings and white-screens.
 * Reindexing costs nothing and keeps every caller's expectation of a list.
 */
add_filter( 'get_block_templates', function ( $templates ) {
	return is_array( $templates ) ? array_values( $templates ) : $templates;
} );

/**
 * Pattern previews: core's block-renderer returns markup WITHOUT the
 * per-instance layout CSS (flex/grid/gap rules the style engine generates
 * during render), so grids collapse into a squished huddle in the picker.
 * This route renders a pattern and hands back that CSS alongside the markup.
 */
add_action( 'rest_api_init', function () {
	register_rest_route( 'gogh/v1', '/pattern', array(
		'methods'             => 'GET',
		'permission_callback' => function () {
			return current_user_can( 'edit_posts' );
		},
		'args'                => array( 'slug' => array( 'required' => true, 'type' => 'string' ) ),
		'callback'            => function ( $req ) {
			$pat = WP_Block_Patterns_Registry::get_instance()->get_registered( (string) $req['slug'] );
			if ( ! $pat ) {
				return new WP_Error( 'gogh_no_pattern', __( 'Unknown pattern.', 'gogh-editor' ), array( 'status' => 404 ) );
			}
			// a preview is a PICTURE of the page: rails elements show the
			// model's own sample shop rather than asking Woo for a query that
			// renders nothing outside a real page (the Shop card was blank)
			$GLOBALS['gogh_pattern_preview'] = true;
			$html = do_blocks( (string) $pat['content'] );
			$GLOBALS['gogh_pattern_preview'] = false;
			// BOTH style-engine stores, the /render lesson: with the
			// Gutenberg plugin active its namespaced store holds the layout
			// rules and core's sits empty — querying only core collapsed
			// every pattern card to a stacked strip ("really weird and small")
			$css = '';
			if ( function_exists( 'gutenberg_style_engine_get_stylesheet_from_context' ) ) {
				$css .= (string) gutenberg_style_engine_get_stylesheet_from_context( 'block-supports' );
			}
			if ( function_exists( 'wp_style_engine_get_stylesheet_from_context' ) ) {
				$css .= (string) wp_style_engine_get_stylesheet_from_context( 'block-supports' );
			}
			return array( 'rendered' => $html, 'css' => $css );
		},
	) );
} );

/**
 * Last line of defence for site chrome: gogh's editor UI classes must never
 * appear in STORED template parts or navigation menus. If they do, some
 * DOM-derived markup is being saved by mistake (this once replaced a header
 * with its own rendered DOM, add-page buttons included) — refuse the write
 * loudly instead of corrupting every page on the site.
 */
add_action( 'rest_api_init', function () {
	$guard = function ( $prepared ) {
		$c = is_object( $prepared ) && isset( $prepared->post_content ) ? $prepared->post_content : '';
		foreach ( array( 'gogh-navadd', 'gogh-pendbar', 'gogh-storedrm', 'gogh-convertbtn', 'gogh-selbox', 'data-gogh' ) as $mark ) {
			if ( false !== strpos( $c, $mark ) ) {
				return new WP_Error(
					'gogh_artifact_in_chrome',
					__( 'gogh blocked this save: editor-only markup was about to be stored in site chrome.', 'gogh-editor' ),
					array( 'status' => 400 )
				);
			}
		}
		return $prepared;
	};
	add_filter( 'rest_pre_insert_wp_template_part', $guard );
	add_filter( 'rest_pre_insert_wp_navigation', $guard );
} );

/**
 * Your brand: a small recipe (four colours, two font slugs) stored as a
 * site option and editable over the core settings REST route. Applying it
 * writes user Global Styles through the same path as theme variations.
 */
add_action( 'init', function () {
	register_setting( 'options', 'gogh_brand', array(
		'type'         => 'object',
		'default'      => null,
		'show_in_rest' => array(
			'schema' => array(
				'type'                 => 'object',
				'properties'           => array(
					'colors' => array(
						'type'       => 'object',
						'properties' => array(
							'background' => array( 'type' => 'string' ),
							'text'       => array( 'type' => 'string' ),
							'accent'     => array( 'type' => 'string' ),
							'accent2'    => array( 'type' => 'string' ),
						),
					),
					'fonts'  => array(
						'type'       => 'object',
						'properties' => array(
							'heading' => array( 'type' => 'string' ),
							'body'    => array( 'type' => 'string' ),
						),
					),
				),
				'additionalProperties' => false,
			),
		),
	) );
} );

/**
 * Experience bundles are plain .html uploads — allowed only for users who
 * may already publish arbitrary markup (unfiltered_html), so this grants
 * no capability they don't have.
 */
add_filter( 'upload_mimes', function ( $mimes ) {
	if ( current_user_can( 'unfiltered_html' ) ) {
		$mimes['html'] = 'text/html';
	}
	return $mimes;
} );

/**
 * SPIKE variant B: rebake. On every save — by anyone, including users whose
 * content KSES just filtered — regenerate the baked <style> inside each v3
 * section from its attributes. The plugin authors these bytes server-side,
 * so the saver's capabilities are irrelevant; deactivation keeps the look.
 * ADOPTED as production behaviour (variant B won the matrix): default ON,
 * gogh_rebake_enabled filter remains as the escape hatch.
 */
function gogh_rebake_post_data( $data ) {
	if ( ! apply_filters( 'gogh_rebake_enabled', true ) ) {
		return $data;
	}
	if ( empty( $data['post_content'] ) || false === strpos( $data['post_content'], 'wp:gogh/section' ) ) {
		return $data;
	}
	$content = wp_unslash( $data['post_content'] );
	$blocks  = parse_blocks( $content );
	$changed = false;
	foreach ( $blocks as &$b ) {
		if ( 'gogh/section' !== $b['blockName'] || empty( $b['attrs'] ) ) {
			continue;
		}
		$css = gogh_css_from_attrs( $b['attrs'] );
		if ( '' === $css || false !== strpos( (string) $b['innerHTML'], 'class="gogh-style"' ) ) {
			continue;
		}
		$style = '<style class="gogh-style">' . $css . '</style>';
		foreach ( array( 'innerHTML', 'innerContent' ) as $k ) {
			if ( 'innerContent' === $k ) {
				foreach ( $b['innerContent'] as &$chunk ) {
					if ( is_string( $chunk ) && false !== strpos( $chunk, 'wp-block-gogh-section' ) ) {
						$chunk   = gogh_sweep_css_residue( $chunk );
						$chunk   = preg_replace( '/(<div class="wp-block-gogh-section[^"]*">)/', '$1' . $style, $chunk, 1 );
						$changed = true;
						break;
					}
				}
			} else {
				$b[ $k ] = gogh_sweep_css_residue( (string) $b[ $k ] );
				$b[ $k ] = preg_replace( '/(<div class="wp-block-gogh-section[^"]*">)/', '$1' . $style, $b[ $k ], 1 );
			}
		}
	}
	unset( $b );
	if ( $changed ) {
		$data['post_content'] = wp_slash( serialize_blocks( $blocks ) );
	}
	return $data;
}
add_filter( 'wp_insert_post_data', 'gogh_rebake_post_data', 20 );

/**
 * ✦ Answer-ready — the page's meaning, emitted as JSON-LD.
 *
 * Schema is to meaning what cssT is to looks: a second projection of the
 * same section model. The designer composed an FAQ accordion, so the model
 * literally stores the questions and answers — no inference, no settings
 * screen. On save the graph is computed once into _gogh_schema; wp_head
 * just echoes the cached bytes.
 *
 * Guardrails: emit only what the design states. An FAQPage needs a real
 * question AND answer; anything incomplete simply doesn't emit. Yoast and
 * RankMath own the graph when they're active, and gogh_schema_enabled is
 * the escape hatch.
 */
function gogh_schema_collect_els( $els, &$faq, &$first_para ) {
	foreach ( (array) $els as $e ) {
		if ( ! empty( $e['faq'] ) && is_array( $e['faq'] ) ) {
			foreach ( $e['faq'] as $item ) {
				$q = trim( wp_strip_all_tags( (string) ( $item['q'] ?? '' ) ) );
				$a = trim( wp_strip_all_tags( (string) ( $item['a'] ?? '' ) ) );
				if ( '' !== $q && '' !== $a ) {
					$faq[] = array( 'q' => $q, 'a' => $a );
				}
			}
		}
		if ( '' === $first_para && ( $e['type'] ?? '' ) === 'para' && ! empty( $e['text'] ) ) {
			$first_para = trim( wp_strip_all_tags( (string) $e['text'] ) );
		}
		if ( ! empty( $e['kids'] ) && is_array( $e['kids'] ) ) {
			gogh_schema_collect_els( $e['kids'], $faq, $first_para );
		}
	}
}

function gogh_schema_build( $post ) {
	$faq        = array();
	$first_para = '';
	foreach ( parse_blocks( $post->post_content ) as $b ) {
		if ( 'gogh/section' !== ( $b['blockName'] ?? '' ) ) {
			continue;
		}
		if ( ! empty( $b['attrs']['model']['elements'] ) ) {
			gogh_schema_collect_els( $b['attrs']['model']['elements'], $faq, $first_para );
		} elseif ( ! empty( $b['innerHTML'] ) &&
			preg_match( '/<script type="application\/json" class="gogh-model">(.*?)<\/script>/s', $b['innerHTML'], $m ) ) {
			// legacy v2 sections carry the model in a script tag, not attrs
			$j = json_decode( $m[1], true );
			if ( ! empty( $j['elements'] ) ) {
				gogh_schema_collect_els( $j['elements'], $faq, $first_para );
			}
		}
	}
	$home = home_url( '/' );
	$org  = array(
		'@type' => 'Organization',
		'@id'   => $home . '#org',
		'name'  => get_bloginfo( 'name' ),
		'url'   => $home,
	);
	$logo_id = get_theme_mod( 'custom_logo' );
	if ( $logo_id ) {
		$logo = wp_get_attachment_image_url( $logo_id, 'full' );
		if ( $logo ) {
			$org['logo'] = $logo;
		}
	}
	if ( 'post' === $post->post_type ) {
		// Write posts are pure core blocks (deactivation-safe by design), so
		// the Article's facts come from WordPress itself — headline, dates,
		// author, image. Nothing here is inferred; every field is a fact WP
		// already asserts about the post.
		$page = array(
			'@type'            => 'Article',
			'headline'         => mb_substr( get_the_title( $post ), 0, 110 ),
			'url'              => get_permalink( $post ),
			'mainEntityOfPage' => get_permalink( $post ),
			'datePublished'    => get_post_time( 'c', true, $post ),
			'dateModified'     => get_post_modified_time( 'c', true, $post ),
			'publisher'        => array( '@id' => $home . '#org' ),
		);
		$author = get_the_author_meta( 'display_name', $post->post_author );
		if ( $author ) {
			$page['author'] = array( '@type' => 'Person', 'name' => $author );
		}
		$img = get_the_post_thumbnail_url( $post, 'full' );
		if ( ! $img && preg_match( '/<img[^>]+src="([^"]+)"/', $post->post_content, $im ) ) {
			$img = $im[1]; // the first break/splash image stands in for a missing featured image
		}
		if ( $img ) {
			$page['image'] = $img;
		}
		// the writer's own words WIN: the excerpt (edited on the search-
		// preview card) beats every derived fallback
		$hand = trim( wp_strip_all_tags( (string) $post->post_excerpt ) );
		$desc = '' !== $hand ? $hand
			: ( '' !== $first_para ? $first_para
				: wp_trim_words( wp_strip_all_tags( strip_shortcodes( $post->post_content ) ), 28, '…' ) );
		if ( $desc ) {
			$page['description'] = mb_substr( $desc, 0, '' !== $hand ? 300 : 160 );
		}
	} else {
		$page = array(
			'@type'        => 'WebPage',
			'name'         => get_the_title( $post ),
			'url'          => get_permalink( $post ),
			'dateModified' => get_post_modified_time( 'c', true, $post ),
			'publisher'    => array( '@id' => $home . '#org' ),
		);
		// same law as posts: the writer's own words WIN — the excerpt
		// (edited on the search-preview card) beats the derived first line
		$hand = trim( wp_strip_all_tags( (string) $post->post_excerpt ) );
		$desc = '' !== $hand ? $hand : $first_para;
		if ( '' !== $desc ) {
			$page['description'] = mb_substr( $desc, 0, '' !== $hand ? 300 : 160 );
		}
	}
	$graph = array( $org, $page );
	if ( $faq ) {
		$graph[] = array(
			'@type'      => 'FAQPage',
			'mainEntity' => array_map( function ( $p ) {
				return array(
					'@type'          => 'Question',
					'name'           => $p['q'],
					'acceptedAnswer' => array(
						'@type' => 'Answer',
						'text'  => $p['a'],
					),
				);
			}, $faq ),
		);
	}
	return apply_filters( 'gogh_schema', array( '@context' => 'https://schema.org', '@graph' => $graph ), $post );
}

add_action( 'save_post', function ( $post_id, $post ) {
	if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}
	if ( ! in_array( $post->post_type, array( 'page', 'post' ), true ) ) {
		return;
	}
	// pages carry meaning in their section models — no sections, no graph.
	// POSTS always emit: the Article's facts (title, dates, author, image)
	// are WordPress's own assertions, true whether or not the words were
	// written in gogh's Write room ("does this work with write?").
	if ( 'page' === $post->post_type && ! has_block( 'gogh/section', $post ) ) {
		delete_post_meta( $post_id, '_gogh_schema' );
		return;
	}
	if ( 'publish' !== $post->post_status && 'post' === $post->post_type && ! has_block( 'gogh/section', $post ) ) {
		return; // drafts keep whatever they had; the graph lands on publish
	}
	$graph = gogh_schema_build( $post );
	if ( $graph ) {
		// HEX_TAG keeps </script> impossible inside the JSON; wp_slash
		// survives the meta layer's stripslashes so \u escapes hold
		update_post_meta( $post_id, '_gogh_schema', wp_slash( wp_json_encode( $graph, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG ) ) );
	} else {
		delete_post_meta( $post_id, '_gogh_schema' );
	}
}, 10, 2 );

add_action( 'wp_head', function () {
	if ( ! is_singular() ) {
		return;
	}
	if ( defined( 'WPSEO_VERSION' ) || class_exists( 'RankMath' ) ) {
		return; // the SEO plugin owns the graph — no duplicate-schema fights
	}
	if ( ! apply_filters( 'gogh_schema_enabled', true ) ) {
		return;
	}
	$json = get_post_meta( get_the_ID(), '_gogh_schema', true );
	if ( $json ) {
		echo '<script type="application/ld+json" class="gogh-schema">' . $json . '</script>' . "\n"; // phpcs:ignore WordPress.Security.EscapeOutput -- pre-encoded JSON authored server-side
	}
} );

/**
 * ✦ The deactivation promise: switch gogh off and the site keeps its look.
 * Section layout is already baked into the saved content (the rebake), but
 * the splash and widget presentation lived only in enqueued CSS — a
 * carousel collapsed to a stack the moment the plugin went quiet. On
 * deactivation this writes the presentation CSS into the theme's own
 * Additional CSS (no plugin required to serve it); reactivation removes
 * the marked block again so nothing is ever doubled.
 */
function gogh_leavebehind_css() {
	return gogh_splash_css() . gogh_widget_css() .
		// the template-level gap zeroing keeps painted bands touching
		'.wp-site-blocks > header, .wp-site-blocks > main, .wp-site-blocks > footer, .wp-site-blocks > .wp-block-template-part { margin-block: 0 !important; }' .
		'.gogh-wrap { margin-block: 0 !important; min-width: 100%; }' .
		'.entry-content:has(> .gogh-wrap) { margin-block: 0 !important; }' .
		'.gogh-section > .wp-block-group { padding: 0 !important; box-sizing: border-box; }' .
		'.gogh-section > * { box-sizing: border-box; }' .
		// video backgrounds: the loop sits under everything; its poster (the
		// section image) shows until it plays, and whenever motion is off
		'.gogh-section > .gogh-bgvideo { position: absolute; inset: 0; z-index: -1; margin: 0 !important; padding: 0 !important; pointer-events: none; overflow: hidden; }' .
		'.gogh-section > .gogh-bgvideo video { width: 100%; height: 100%; object-fit: cover; display: block; }' .
		'.gogh-bgvideo-btn { position: absolute; right: 14px; bottom: 14px; z-index: 60; width: 36px; height: 36px; border-radius: 50%; border: 0; padding: 0; cursor: pointer; background: rgba(15,23,42,0.55); color: #fff; display: grid; place-items: center; opacity: 0.72; transition: opacity 0.2s; }' .
		'.gogh-bgvideo-btn:hover, .gogh-bgvideo-btn:focus-visible { opacity: 1; }' .
		'.gogh-bgvideo-btn svg { width: 14px; height: 14px; display: block; }' .
		'@media (prefers-reduced-motion: reduce) { .gogh-section > .gogh-bgvideo, .gogh-bgvideo-btn { display: none; } }' .
		// the video element: the frame is the design's, the player fills it
		'.gogh-section > .gogh-vid { overflow: hidden; overflow: clip; }' .
		'.gogh-section > .gogh-vid video, .gogh-section > .gogh-vid iframe { width: 100%; height: 100%; object-fit: cover; display: block; border: 0; border-radius: inherit; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper { position: relative; height: 100%; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper::before { content: none !important; padding: 0 !important; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper iframe { position: absolute; inset: 0; }' .
		'.gogh-section-html { box-sizing: border-box !important; width: 100vw !important; max-width: 100vw !important; margin-inline: calc(50% - 50vw) !important; margin-block: 0 !important; }' .
		'.gogh-paste-plain { padding-block: 2.5rem; } .gogh-paste-plain > :where(section, article, div, main, header, footer) { max-width: 46rem; margin-inline: auto; padding-inline: 1.25rem; } .gogh-paste-plain img { display: block; max-width: 100%; height: auto; max-height: min(55vh, 480px); object-fit: cover; margin-block: 1rem; border-radius: 6px; } .gogh-paste-plain :where(section, article, div) > a { display: inline-block; margin: 0.5rem 0.75rem 0.5rem 0; } .gogh-paste-plain h1 { font-size: 2.2em; line-height: 1.1; margin-block: 0.4em; } .gogh-paste-plain h2 { font-size: 1.6em; margin-block: 1.4em 0.4em; } .gogh-paste-plain h3 { font-size: 1.15em; margin-block: 1.2em 0.3em; }' .
		'html { overflow-x: clip; }' .
		'.entry-content > .gogh-wrap + .alignfull, .entry-content > .alignfull + .gogh-wrap, .entry-content > .alignfull + .alignfull { margin-block-start: 0; }';
}
function gogh_strip_leavebehind( $css ) {
	return preg_replace( '/\n?\/\* gogh:keep-the-look start \*\/.*?\/\* gogh:keep-the-look end \*\/\n?/s', '', (string) $css );
}
// keep the BLOCKS too: a self-contained helper goes into mu-plugins so the
// block editor still knows gogh/section (and gogh/form) with Gogh away —
// "gogh Section" with its inner blocks, not "Unsupported" and a Keep-as-HTML
// button that flattens them. The helper deletes itself once Gogh is back.
function gogh_keep_blocks_target() {
	return trailingslashit( defined( 'WPMU_PLUGIN_DIR' ) ? WPMU_PLUGIN_DIR : WP_CONTENT_DIR . '/mu-plugins' ) . 'gogh-keep-blocks.php';
}
function gogh_keep_blocks_leave() {
	$src = __DIR__ . '/gogh-keep-blocks.php';
	$dst = gogh_keep_blocks_target();
	if ( ! is_readable( $src ) ) {
		return false;
	}
	$dir = dirname( $dst );
	if ( ! is_dir( $dir ) ) {
		@wp_mkdir_p( $dir );
	}
	if ( ! is_dir( $dir ) || ! wp_is_writable( $dir ) ) {
		return false; // nothing changes from today: pages still render, the wrapper reads as unsupported
	}
	// the helper carries the plugin's own editor canvas rules, as of now
	$code = file_get_contents( $src );
	if ( false === $code ) {
		return false;
	}
	$code = str_replace( "'/*GOGH_EDITOR_CANVAS_CSS*/'", var_export( gogh_editor_canvas_css(), true ), $code );
	$code = str_replace( "'/*GOGH_EDITOR_FLATTEN_CSS*/'", var_export( gogh_editor_flatten_css(), true ), $code );
	return (bool) @file_put_contents( $dst, $code );
}
function gogh_keep_blocks_take_back() {
	$dst = gogh_keep_blocks_target();
	if ( file_exists( $dst ) ) {
		@unlink( $dst );
	}
}
register_deactivation_hook( __FILE__, function () {
	$css = gogh_strip_leavebehind( wp_get_custom_css() );
	wp_update_custom_css_post( $css . "\n/* gogh:keep-the-look start */\n" . gogh_leavebehind_css() . "\n/* gogh:keep-the-look end */\n" );
	gogh_keep_blocks_leave();
} );
register_activation_hook( __FILE__, function () {
	$css   = wp_get_custom_css();
	$clean = gogh_strip_leavebehind( $css );
	if ( $clean !== $css ) {
		wp_update_custom_css_post( $clean );
	}
	gogh_keep_blocks_take_back();
} );

/**
 * FAQ + Tabs widget polish — one source for the front end, the editor,
 * and the deactivation leave-behind.
 */
function gogh_widget_css() {
	return
		// FAQ + Tabs widgets: quiet, theme-inked styling for the real blocks —
		// the same rules dress the editor preview (the edit page IS the front)
		// the theme's flow blockGap dresses accordion internals like prose —
		// big margins between item, heading and panel (James: "formatting
		// breakage"). The widget owns its rhythm.
		// the widget wrapper is display:flex (it centres SMALL widgets — nav,
		// site title); accordion and tabs are block content and must fill the
		// box, not shrink to their words (the "narrow accordion" report)
		'.gogh-widget > .wp-block-accordion, .gogh-widget > .wp-block-tabs { flex: 1 1 100%; width: 100%; }' .
		'.gogh-widget .wp-block-accordion > *, .gogh-widget .wp-block-accordion-item > *, .gogh-widget .wp-block-tabs > *, .gogh-widget .wp-block-accordion-panel__content > *, .gogh-widget .wp-block-accordion-panel > *, .gogh-widget .wp-block-tab-panel > * { margin-block: 0 !important; }' .
		'.gogh-widget .wp-block-accordion-item { border-top: 1px solid color-mix(in srgb, currentColor 16%, transparent); }' .
		'.gogh-widget .wp-block-accordion-item:last-child { border-bottom: 1px solid color-mix(in srgb, currentColor 16%, transparent); }' .
		'.gogh-widget .wp-block-accordion-heading { margin: 0; font-size: 1.02em; }' .
		'.gogh-widget .wp-block-accordion-heading__toggle { display: flex; width: 100%; justify-content: space-between; align-items: center; gap: 1em; padding: 0.9em 0; background: none; border: 0; font: inherit; font-weight: 600; color: inherit; cursor: pointer; text-align: left; }' .
		'.gogh-widget .wp-block-accordion-heading__icon::before { content: "+"; font-size: 1.25em; font-weight: 400; opacity: 0.55; line-height: 1; }' .
		'.gogh-widget .is-open .wp-block-accordion-heading__icon::before, .gogh-widget .wp-block-accordion-item.is-open .wp-block-accordion-heading__icon::before { content: "\2212"; }' .
		// core 6.9 markup: the icon is a literal + in __toggle-icon — rotating
		// it 45° reads as × when open, and the transition makes it turn
		'.gogh-widget .wp-block-accordion-heading__toggle-icon { font-size: 1.25em; font-weight: 400; opacity: 0.55; line-height: 1; transition: rotate 0.3s ease; }' .
		'.gogh-widget .wp-block-accordion-heading button[aria-expanded="true"] .wp-block-accordion-heading__toggle-icon { rotate: 45deg; }' .
		'.gogh-widget .wp-block-accordion-panel__content { padding: 0 0 1.1em; opacity: 0.85; }' .
		'.gogh-widget .wp-block-accordion-panel > p { padding: 0 0 1.1em; opacity: 0.85; }' .
		'.gogh-widget .wp-block-tab-list { display: flex; gap: 0.25em; border-bottom: 1px solid color-mix(in srgb, currentColor 16%, transparent); margin-bottom: 1.2em; }' .
		'.gogh-widget .wp-block-tab-list__tab, .gogh-widget .wp-block-tab-list > button { padding: 0.7em 1em; background: none; border: 0; border-bottom: 2px solid transparent; margin-bottom: -1px; font: inherit; font-weight: 600; color: inherit; opacity: 0.55; cursor: pointer; }' .
		'.gogh-widget .wp-block-tab-list__tab[aria-selected="true"], .gogh-widget .wp-block-tab-list > button[aria-selected="true"] { opacity: 1; border-bottom-color: currentColor; }' .
		'.gogh-widget .wp-block-tab-panel { padding-top: 0.2em; }' .
		// ---- smooth open/close (James: "kinda harsh and janky") ----
		// The accordion's closed panel wears hidden=until-found (still
		// display:block), so with interpolate-size the height can transition
		// 0 ↔ auto; content-visibility transitions discretely, staying visible
		// while the panel closes. Pure view-time CSS — nothing stored — and
		// browsers without support keep today's instant toggle.
		// (accordion/tab open motion is WAAPI in gogh-view below — CSS
		// transitions AND animations freeze inside the accordion's
		// content-visibility-skipped panel, and transitioning
		// content-visibility itself froze the tab. element.animate on the
		// just-revealed panel is immune to all of it.)
		// motion is a garnish, never a requirement
		'@media (prefers-reduced-motion: reduce) { .gogh-widget .wp-block-accordion-heading__toggle-icon { transition: none; } }';
}

/**
 * ✦ Splash presentation — the carousel, photo wall, break image, and glass
 * card are pure core blocks wearing gogh classes; THIS css is their whole
 * look. Shared verbatim between the front end and the block editor so a
 * splash never "breaks in the gutenberg view": same rules, both rooms.
 * (Interactivity — arrows, autoplay, lightbox, parallax — stays view-time
 * and front-end only; the editor just has to look right.)
 */
function gogh_splash_css() {
	return
		// CSS-only carousel: flex + scroll-snap does all the work — zero JS,
		// deactivation-safe. Chrome's CSS carousel spec (scroll markers)
		// lights the dots up as a free progressive enhancement.
		'.gogh-carousel { display: flex; flex-wrap: nowrap; gap: 14px; overflow-x: auto; scroll-snap-type: x mandatory; overscroll-behavior-x: contain; scrollbar-width: none; -webkit-overflow-scrolling: touch; }' .
		'.gogh-carousel::-webkit-scrollbar { display: none; }' .
		'.gogh-carousel > .wp-block-image.gogh-slide { flex: 0 0 min(72%, 460px); scroll-snap-align: center; margin: 0 !important; }' .
		'.gogh-carousel .gogh-slide img { width: 100%; aspect-ratio: 3 / 2; object-fit: cover; border-radius: 14px; display: block; }' .
		'.gogh-carousel .gogh-slide figcaption { text-align: center; font-size: 0.85em; opacity: 0.72; margin-top: 8px; }' .
		// the photo wall: CSS columns ARE the masonry — no measuring, no JS
		'.gogh-wall { columns: 3; gap: 14px; }' .
		'.gogh-wall-2 { columns: 2; } .gogh-wall-4 { columns: 4; }' .
		'@media (max-width: 700px) { .gogh-wall, .gogh-wall-4 { columns: 2; } }' .
		'.gogh-wall > .gogh-brick { break-inside: avoid; margin: 0 0 14px !important; display: block; }' .
		'.gogh-wall .gogh-brick img { width: 100%; height: auto; border-radius: 12px; display: block; }' .
		'.gogh-wall .gogh-brick figcaption { font-size: 0.85em; opacity: 0.72; margin-top: 6px; }' .
		// the chapter-break image: a fixed window over a cover-fit photo.
		// figure.wp-block-image.gogh-splash-break outguns the theme's
		// .wp-block-image.alignfull img { height: auto } — without it the
		// break renders at the photo's full natural height.
		// crop from the TOP, not the centre: faces live in the top of
		// photographs, and a centre-cropped portrait loses its head ("images
		// are cropping"). Tested 50% 25% first — an extreme portrait still
		// lost the head; top-anchoring never does. Landscape sources are
		// untouched either way (wide images crop their sides, not their top).
		'.gogh-splash-break { overflow: clip; margin-block: 0; }' .
		'.gogh-splash-break img, figure.wp-block-image.gogh-splash-break img { width: 100%; height: min(66vh, 640px); object-fit: cover; object-position: 50% 0%; display: block; }' .
		// the frosted call-out
		'.gogh-splash-glasswrap { min-height: min(70vh, 560px); display: flex; align-items: center; justify-content: center; padding: 6vh 6vw; }' .
		'.gogh-glass { max-width: 480px; padding: 2.2rem 2.4rem; border-radius: 24px; background: color-mix(in srgb, #ffffff 72%, transparent); -webkit-backdrop-filter: blur(18px) saturate(1.35); backdrop-filter: blur(18px) saturate(1.35); border: 1px solid color-mix(in srgb, #ffffff 55%, transparent); box-shadow: 0 30px 60px -22px rgba(0,0,0,0.45); text-align: center; }' .
		'.gogh-glass-kicker { font-size: 0.78rem; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; opacity: 0.6; margin-bottom: 0.4rem; }';
}

// ✦ looks and motion serve EVERY visitor on every page — no gate. A post
// wearing Magazine must read as Magazine logged-out, and the site's gait
// is site-wide; both packs are a few KB of pure CSS.
add_action( 'wp_enqueue_scripts', function () {
	wp_register_style( 'gogh-looks', false, array(), '0.99.421-chrome' );
	wp_enqueue_style( 'gogh-looks' );
	wp_add_inline_style( 'gogh-looks', gogh_reading_style_css() . gogh_motion_css() . gogh_blog_style_css() );

	// the Blog style chooser pill retired (James: 'remove the pill for the
	// posts page - lets have consistency') — the admin bar's Blog layout
	// menu is the one door, like Product layout and Post layout
} );

/**
 * Front-end editor: enqueue for users who can edit the current page.
 */
add_action( 'wp_enqueue_scripts', function () {
	if ( ! is_singular() ) {
		return;
	}
	$post      = get_post();
	if ( ! $post ) {
		return;
	}
	$has_gogh  = false !== strpos( $post->post_content, 'gogh-section' );
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only view toggle; editor assets are capability-gated below.
	$want_edit = isset( $_GET['gogh-edit'] );
	$can_edit  = current_user_can( 'edit_post', $post->ID );
	// products: the editor belongs on gogh's own layouts only — on Woo's
	// classic template the description hides in tabs and the canvas would
	// fight the buy box (the admin bar's layout menu is the door)
	if ( 'product' === $post->post_type &&
		! in_array( get_page_template_slug( $post ), array( 'gogh-product-story', 'gogh-product-showcase', 'gogh-product-hero' ), true ) ) {
		return;
	}
	// visitors only need assets on gogh pages; EDITORS get the editor on
	// every singular page — gating on 'gogh-section' in the content is why
	// the floating edit pill never appeared on untouched or empty pages
	if ( ! $has_gogh && ! $want_edit && ! $can_edit ) {
		return;
	}

	// for every visitor: neutralise theme spacing around gogh sections, even
	// on pages whose stored stylesheets predate this rule
	wp_register_style( 'gogh-base', false, array(), '0.99.421-chrome' );
	// (the splash presentation itself lives in gogh_splash_css(), shared with
	// the block editor — a wall in Gutenberg must look like a wall)
	wp_register_script( 'gogh-view', false, array(), '0.99.421-chrome', true );
	wp_enqueue_script( 'gogh-view' );
	wp_add_inline_script( 'gogh-view',
		// mega menu panels: hover opens with intent on fine pointers; the chevron
		// opens for keyboards and touch; Escape and a click away close; one at a
		// time; in the phone overlay the same class folds the link list instead
		'(function(){var html=document.documentElement;if(html.classList.contains("gogh-editing"))return;' .
		'var items=[].slice.call(document.querySelectorAll(".wp-block-navigation-item.gogh-has-panel"));if(!items.length)return;' .
		'var fine=window.matchMedia&&window.matchMedia("(hover: hover) and (pointer: fine)").matches;var openLi=null;' .
		'function inOverlay(li){return !!li.closest(".wp-block-navigation__responsive-container.is-menu-open");}' .
		'function place(li,panel){var hdr=li.closest("header, .wp-block-template-part")||li.closest(".wp-block-navigation");var hr=hdr.getBoundingClientRect(),lr=li.getBoundingClientRect();panel.style.left=(hr.left-lr.left)+"px";panel.style.width=hr.width+"px";panel.style.top=(hr.bottom-lr.top)+"px";}' .
		'function setOpen(li,on){var panel=li.querySelector(":scope > .gogh-mega");var btn=li.querySelector(":scope > .gogh-mega-toggle");li.classList.toggle("is-open",on);if(btn)btn.setAttribute("aria-expanded",on?"true":"false");' .
		'if(panel&&!inOverlay(li)){if(on){place(li,panel);panel.hidden=false;}else{panel.hidden=true;}}' .
		'if(on){if(openLi&&openLi!==li)setOpen(openLi,false);openLi=li;}else if(openLi===li)openLi=null;}' .
		'items.forEach(function(li){var btn=li.querySelector(":scope > .gogh-mega-toggle");var t=null;' .
		'if(btn)btn.addEventListener("click",function(ev){ev.preventDefault();ev.stopPropagation();setOpen(li,!li.classList.contains("is-open"));});' .
		'if(fine){li.addEventListener("mouseenter",function(){if(inOverlay(li))return;clearTimeout(t);t=setTimeout(function(){setOpen(li,true);},120);});' .
		'li.addEventListener("mouseleave",function(){if(inOverlay(li))return;clearTimeout(t);t=setTimeout(function(){setOpen(li,false);},220);});}' .
		'li.addEventListener("keydown",function(ev){if(ev.key==="Escape"&&li.classList.contains("is-open")){setOpen(li,false);if(btn)btn.focus();}});});' .
		'document.addEventListener("click",function(ev){if(openLi&&!openLi.contains(ev.target))setOpen(openLi,false);});' .
		'document.addEventListener("keydown",function(ev){if(ev.key==="Escape"&&openLi)setOpen(openLi,false);});' .
		'window.addEventListener("resize",function(){if(openLi)setOpen(openLi,false);},{passive:true});})();'
	);
	wp_add_inline_script( 'gogh-view',
		// the Manual look's contents: built from the post's own h2/h3, ids
		// minted where missing, the current section marked as you read.
		// Exposed as window.goghManualToc(root) so the suite can drive it.
		'(function(){function slug(t){return (t||"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,60)||"section";}' .
		'window.goghManualToc=function(root){if(!root)return null;var heads=[].slice.call(root.querySelectorAll(":scope > h2, :scope > h3, :scope > .wp-block-group h2, :scope > .wp-block-group h3")).filter(function(h){return (h.textContent||"").trim();});' .
		'if(heads.length<2)return null;var old=root.querySelector(":scope > .gogh-toc");if(old)old.remove();var seen={};' .
		'heads.forEach(function(h){if(!h.id){var b=slug(h.textContent),id=b,n=2;while(seen[id]||document.getElementById(id)){id=b+"-"+(n++);}h.id=id;}seen[h.id]=1;});' .
		'var nav=document.createElement("nav");nav.className="gogh-toc";nav.setAttribute("aria-label","On this page");' .
		'nav.innerHTML="<span class=\"gogh-toc-title\">On this page</span>";var ol=document.createElement("ol");' .
		'var calm=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;' .
		'heads.forEach(function(h){var li=document.createElement("li");li.className="gogh-toc-"+h.tagName.toLowerCase();var a=document.createElement("a");a.href="#"+h.id;a.textContent=h.textContent.trim();' .
		'a.addEventListener("click",function(ev){ev.preventDefault();h.scrollIntoView({block:"start",behavior:calm?"auto":"smooth"});try{history.replaceState(null,"","#"+h.id);}catch(e){}});li.appendChild(a);ol.appendChild(li);});' .
		'nav.appendChild(ol);root.insertBefore(nav,root.firstChild);root.classList.add("gogh-has-toc");' .
		'var place=function(){var first=[].slice.call(root.children).filter(function(c){return c!==nav;})[0];var left=first?first.getBoundingClientRect().left-252:0;' .
		'if(left>=72){nav.classList.add("gogh-toc-side");nav.classList.remove("gogh-toc-boxed");nav.style.left=Math.round(left)+"px";}else{nav.classList.remove("gogh-toc-side");nav.classList.add("gogh-toc-boxed");nav.style.left="";}};' .
		'place();window.addEventListener("resize",place,{passive:true});' .
		'if(window.IntersectionObserver){var links={};[].slice.call(ol.querySelectorAll("a")).forEach(function(a){links[a.getAttribute("href").slice(1)]=a;});var here=null;' .
		'var mark=function(id){if(here)here.classList.remove("is-here");here=links[id]||null;if(here)here.classList.add("is-here");};' .
		'var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting)mark(e.target.id);});},{rootMargin:"-10% 0px -70% 0px",threshold:0});heads.forEach(function(h){io.observe(h);});mark(heads[0].id);}' .
		'return nav;};' .
		'var html=document.documentElement;if(html.classList.contains("gogh-editing"))return;' .
		// the writing room: the same contents, read-only and OUTSIDE the content
		// (no ids minted, nothing for the serializer to meet), placed beside
		// the column and rebuilt as the words change or the look auditions
		'if(document.body.classList.contains("gogh-writing")){var room=null,timer=null;' .
		'var build=function(){var root=document.querySelector(".entry-content, .wp-block-post-content");if(room){room.remove();room=null;}' .
		'if(!root||!document.body.classList.contains("gogh-read-manual"))return;' .
		'var heads=[].slice.call(root.querySelectorAll("h2, h3")).filter(function(h){return (h.textContent||"").trim();});if(heads.length<2)return;' .
		'var first=root.querySelector("p, h2, h3, ul, ol, figure");var colLeft=(first||root).getBoundingClientRect().left;var left=colLeft-252;' .
		'var panel=document.querySelector(".gogh-w-stylepop");if(panel&&!panel.hidden){var pr=panel.getBoundingClientRect();if(pr.right>left-16)left=pr.right+24;}' .
		'if(left<72||left+220>colLeft-16)return;' .
		'room=document.createElement("nav");room.className="gogh-toc gogh-toc-room";room.setAttribute("aria-hidden","true");room.contentEditable="false";room.style.left=Math.round(left)+"px";' .
		'room.innerHTML="<span class=\"gogh-toc-title\">On this page</span>";var ol=document.createElement("ol");' .
		'heads.forEach(function(h){var li=document.createElement("li");li.className="gogh-toc-"+h.tagName.toLowerCase();var a=document.createElement("a");a.textContent=h.textContent.trim();' .
		'a.addEventListener("mousedown",function(ev){ev.preventDefault();h.scrollIntoView({block:"start",behavior:(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches)?"auto":"smooth"});});li.appendChild(a);ol.appendChild(li);});' .
		'room.appendChild(ol);document.body.appendChild(room);};' .
		'var later=function(){clearTimeout(timer);timer=setTimeout(build,350);};' .
		'new MutationObserver(later).observe(document.body,{attributes:true,attributeFilter:["class"]});' .
		'document.addEventListener("input",later,true);window.addEventListener("resize",later,{passive:true});' .
