		'shell.insertBefore(b,strip);' .
		'var fit=function(){b.style.top=(strip.offsetTop+strip.clientHeight/2)+"px";b.style.transform="translateY(-50%)";};fit();' .
		'if(window.ResizeObserver)new ResizeObserver(fit).observe(strip);});' .
