	wp_enqueue_style( 'gogh-base' );
	// (reading looks + motion moved to the ungated 'gogh-looks' style — the
	// gogh-base gate was hiding them from logged-out readers on splash-less
	// posts: a post wearing Magazine read as the theme default to visitors)
	wp_add_inline_style( 'gogh-base',
		// full-bleed sections use 100vw, which includes the scrollbar — once
		// a vertical scrollbar exists they overflow sideways and the canvas
		// wobbles left-right. Clip horizontal overflow at the root (clip, not
		// hidden: no new scroll container, inner scrollers unaffected).
		'html { overflow-x: clip; }' .
		// the theme's root block-gap leaves a pale strip between the header,
		// the content, and the footer ("this weird gap above the header and
		// content") — gogh's painted bands should TOUCH. Zero the template-
		// level margins only; in-content block gaps stay the theme's business.
		'.wp-site-blocks > header, .wp-site-blocks > main, .wp-site-blocks > footer, .wp-site-blocks > .wp-block-template-part { margin-block: 0 !important; }' .
		'.gogh-wrap { margin-block: 0 !important; min-width: 100%; }' .
		'.entry-content:has(> .gogh-wrap) { margin-block: 0 !important; }' .
		// pages saved before this rule shipped: image placeholders must not
		// inherit theme Group padding
		'.gogh-section > .wp-block-group { padding: 0 !important; box-sizing: border-box; }' .
		'.gogh-section > * { box-sizing: border-box; }' .
		// video backgrounds: the loop sits under everything; its poster (the
		// section image) shows until it plays, and whenever motion is off
		'.gogh-section > .gogh-bgvideo { position: absolute; inset: 0; z-index: -1; margin: 0 !important; padding: 0 !important; pointer-events: none; overflow: hidden; }' .
		'.gogh-section > .gogh-bgvideo video { width: 100%; height: 100%; object-fit: cover; display: block; }' .
		'.gogh-bgvideo-btn { position: absolute; right: 14px; bottom: 14px; z-index: 60; width: 36px; height: 36px; border-radius: 50%; border: 0; padding: 0; cursor: pointer; background: rgba(15,23,42,0.55); color: #fff; display: grid; place-items: center; opacity: 0.72; transition: opacity 0.2s; }' .
		'.gogh-bgvideo-btn:hover, .gogh-bgvideo-btn:focus-visible { opacity: 1; }' .
		'.gogh-bgvideo-btn svg { width: 14px; height: 14px; display: block; }' .
		'@media (prefers-reduced-motion: reduce) { .gogh-section > .gogh-bgvideo, .gogh-bgvideo-btn { display: none; } }' .
		// the video element: the frame is the design's, the player fills it
		'.gogh-section > .gogh-vid { overflow: hidden; overflow: clip; }' .
		'.gogh-section > .gogh-vid video, .gogh-section > .gogh-vid iframe { width: 100%; height: 100%; object-fit: cover; display: block; border: 0; border-radius: inherit; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper { position: relative; height: 100%; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper::before { content: none !important; padding: 0 !important; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper iframe { position: absolute; inset: 0; }' .
		// pasted-HTML sections: full bleed with zero vertical margins for
		// every visitor — the theme's block-gap must not band between them
		'.gogh-section-html { box-sizing: border-box !important; width: 100vw !important; max-width: 100vw !important; margin-inline: calc(50% - 50vw) !important; margin-block: 0 !important; }' .
		gogh_splash_css() .
		'.gogh-crsl-shell { position: relative; }' .
		// ONE centred control row under the strip: arrows flank clickable
		// dots (James: "align arrows horizontally centered" + "these should
		// be clickable right?"). Ours, everywhere — the Chrome-only pseudo
		// markers are retired.
		'.gogh-crsl-nav { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 14px; }' .
		'.gogh-crsl-btn { width: 34px; height: 34px; border-radius: 50%; border: 0; display: flex; align-items: center; justify-content: center; font-size: 21px; line-height: 1; cursor: pointer; background: color-mix(in srgb, var(--wp--preset--color--contrast, #16181c) 8%, transparent); color: var(--wp--preset--color--contrast, #16181c); transition: background 0.15s ease, scale 0.15s ease; user-select: none; }' .
		'.gogh-crsl-btn:hover { background: color-mix(in srgb, var(--wp--preset--color--contrast, #16181c) 16%, transparent); scale: 1.08; }' .
		'.gogh-crsl-dots { display: flex; gap: 9px; }' .
		'.gogh-crsl-dot { width: 9px; height: 9px; border-radius: 50%; border: 0; padding: 0; cursor: pointer; background: currentColor; opacity: 0.22; transition: opacity 0.15s ease, scale 0.15s ease; }' .
		'.gogh-crsl-dot.is-here { opacity: 0.9; scale: 1.15; }' .
		// ✦ Splash motion + bleed plumbing (the LOOK is gogh_splash_css above)
		// full bleed means the VIEWPORT, not the content column — themes
		// pad alignfull unevenly, so the splash claims its own edges
		// full bleed rides WP's OWN generated container rules (they emit
		// literal negative margins per padded container, direct children
		// only — which is also why the write room's wrapper must wear
		// .alignfull itself). vw math is banned: vw includes scrollbar
		// width, which shoved everything 30px sideways.
		// on phones any stray overflow inflates the layout viewport, and then
		// 100vw resolves against the inflated width — a self-sustaining 30px
		// shove. Clipping the root pins vw to the device and ends the loop.
		'html:has(.gogh-splash-break, .gogh-splash-glasswrap) { overflow-x: clip; }' .
		// consecutive full-bleed bands touch: the root block gap otherwise
		// leaves a pale slit between painted sections (the white wedge law)
		'.entry-content > .gogh-wrap + .alignfull, .entry-content > .alignfull + .gogh-wrap, .entry-content > .alignfull + .alignfull { margin-block-start: 0; }' .
		'@supports (animation-timeline: view()) { .gogh-splash-break img { scale: 1.16; animation: gogh-bkpx linear both; animation-timeline: view(); } @keyframes gogh-bkpx { from { translate: 0 -5%; } to { translate: 0 5%; } } }' .
		// breakout images (wide/full figures in prose) parallax by default —
		// James: "i kinda love paralax". Gentler than the Break splash: the
		// photo keeps its natural height (no crop), a 1.08 scale buys the
		// headroom the ±3% drift spends, and overflow:clip keeps the frame.
		// The Break splash opts out here — it has its own stronger treatment.
		'@supports (animation-timeline: view()) { ' .
		'.entry-content figure.wp-block-image.alignwide:not(.gogh-splash-break), .entry-content figure.wp-block-image.alignfull:not(.gogh-splash-break) { overflow: clip; } ' .
		'.entry-content figure.wp-block-image.alignwide:not(.gogh-splash-break) img, .entry-content figure.wp-block-image.alignfull:not(.gogh-splash-break) img { scale: 1.08; animation: gogh-wfpx linear both; animation-timeline: view(); } ' .
		'@keyframes gogh-wfpx { from { translate: 0 -3%; } to { translate: 0 3%; } } }' .
		// motion is a garnish, never a requirement
		'@media (prefers-reduced-motion: reduce) { .gogh-splash-break img, .entry-content figure.wp-block-image.alignwide img, .entry-content figure.wp-block-image.alignfull img { animation: none; scale: 1; translate: none; } }' .
		'.gogh-crsl-side { position: absolute; z-index: 2; width: 40px; height: 40px; font-size: 24px; background: color-mix(in srgb, var(--wp--preset--color--base, #fff) 85%, transparent); box-shadow: 0 6px 18px -6px rgba(0,0,0,0.35); backdrop-filter: blur(6px); top: calc(50% - 24px); transform: translateY(-50%); }' .
		'.gogh-crsl-side-l { left: 10px; } .gogh-crsl-side-r { right: 10px; }' .
		// gogh's lightbox: walkable, unlike core's single frame
		'.gogh-lbx { position: fixed; inset: 0; z-index: 100000; display: flex; align-items: center; justify-content: center; background: color-mix(in srgb, #0c0c10 82%, transparent); backdrop-filter: blur(10px); }' .
		'.gogh-lbx img { max-width: min(92vw, 1400px); max-height: 84vh; object-fit: contain; border-radius: 10px; box-shadow: 0 30px 90px -20px rgba(0,0,0,0.7); }' .
		'.gogh-lbx figcaption { position: absolute; left: 0; right: 0; bottom: 26px; text-align: center; color: #fff; opacity: 0.85; font-size: 15px; }' .
		'.gogh-lbx .gogh-crsl-btn { position: absolute; top: 50%; transform: translateY(-50%); width: 44px; height: 44px; font-size: 26px; background: rgba(255,255,255,0.14); color: #fff; }' .
		'.gogh-lbx .gogh-lbx-l { left: 22px; } .gogh-lbx .gogh-lbx-r { right: 22px; }' .
		'.gogh-lbx .gogh-lbx-x { position: absolute; top: 18px; right: 22px; transform: none; font-size: 20px; }' .
		'@media (prefers-reduced-motion: no-preference) { .gogh-lbx { animation: gogh-lbx-in 0.18s ease; } @keyframes gogh-lbx-in { from { opacity: 0; } } }' .
		// the transparent header floats over the first section: absolutely
		// positioned with a soft top scrim so white chrome reads on any hero
		// While a layout is AUDITIONING, the chosen layout lives in a
		// .gogh-chrome-preview box and the old content is merely HIDDEN — but
		// :has ignores display, so the hidden original's overlay class kept
		// the header transparent even while previewing a solid layout, so the
		// audition lied and switching away "did nothing" (the stuck-header
		// report). Rule: while previewing, ONLY the preview box governs;
		// otherwise (and always on the published page) the part's own content.
		// (the header's dressing ships site-wide with gogh-menu — see gogh_chrome_css)
		gogh_widget_css()
	);

	if ( ! current_user_can( 'edit_post', $post->ID ) ) {
		return;
	}

	// write mode owns the room: the canvas editor stays out ("lots of
	// distractions here?" — the ＋Section pill and convert buttons were
	// gate-crashing the clean canvas)
	if ( isset( $_GET['gogh-write'] ) ) {
		return;
	}

	// compose must be REGISTERED here too — a dependency on an
	// unregistered handle silently drops the whole editor script
	wp_register_script( 'gogh-compose', plugins_url( 'gogh-compose.js', __FILE__ ), array(), '0.99.421-chrome', true );
	wp_enqueue_script( 'gogh-editor', plugins_url( 'gogh-editor.js', __FILE__ ), array( 'gogh-compose' ), '0.99.421-chrome', true );
	wp_enqueue_style( 'gogh-editor', plugins_url( 'gogh-editor.css', __FILE__ ), array(), '0.99.421-chrome' );

	// WebMCP bridge: the page registers its editing verbs as agent tools.
	// OPT-IN only — add ?gogh-mcp=1 for a demo session (or enable sitewide
	// via the gogh_webmcp_enabled filter). Keeps future WebMCP-speaking
	// agents from discovering publish-capable tools uninvited.
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only opt-in toggle; script is capability-gated above.
	// …and the help bot's show-me bridge rides the same verbs, so the
	// experiments flag loads them too (the bridge itself is origin-checked)
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only labs toggle
	$gogh_exp = isset( $_GET['gogh-test'] ) || ( isset( $_GET['gogh-experiments'] ) && '0' !== $_GET['gogh-experiments'] );
	if ( isset( $_GET['gogh-mcp'] ) || $gogh_exp || apply_filters( 'gogh_webmcp_enabled', false ) ) {
		wp_enqueue_script( 'gogh-webmcp', plugins_url( 'gogh-webmcp.js', __FILE__ ), array( 'gogh-editor' ), '0.99.421-chrome', true );
	}

	// regression suite: /page/?gogh-test (editors only, never saves)
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only toggle enqueuing a test script for capability-checked editors.
	if ( isset( $_GET['gogh-test'] ) ) {
		wp_enqueue_script( 'gogh-tests', plugins_url( 'gogh-tests.js', __FILE__ ), array( 'gogh-editor' ), '0.99.421-chrome', true );
	}

	// products live outside wp/v2, so gogh carries its own save route for
	// them — registered UNDER wp/v2 deliberately: the editor derives the
	// REST root by splitting on 'wp/v2/'
	$rest_base = ( 'page' === $post->post_type ) ? 'pages' : ( 'product' === $post->post_type ? 'gogh-product' : ( 'gogh_panel' === $post->post_type ? 'gogh-panels' : 'posts' ) );
	wp_localize_script( 'gogh-editor', 'GOGH', array(
		'postId'   => $post->ID,
		// the SEO panel's search-preview card needs the page's public face
		'postType'   => $post->post_type,
		// a menu panel's canvas: its own shelf in the picker, and a way back
		'isPanel'    => 'gogh_panel' === $post->post_type,
		'isPanelWoo' => 'gogh_panel' === $post->post_type && function_exists( 'wc_get_products' ),
		'panelFor'   => get_the_title( $post ),
		'homeUrl'    => esc_url_raw( home_url( '/' ) ),
		'postStatus' => $post->post_status,
		'postTitle'  => get_the_title( $post ),
		'permalink'  => esc_url_raw( get_permalink( $post->ID ) ),
		'excerpt'    => (string) $post->post_excerpt,
		'build'    => '0.99.421-chrome',
		// two rooms, one landmark (same contract as the admin bar): on a POST
		// the corner pill opens the WRITING surface, not the freeform canvas
		'writeUrl' => is_singular( 'post' ) ? add_query_arg( 'gogh-write', '1', get_permalink( $post ) ) : null,
		// the first minute: three staged beats on their first section — shown
		// once per user, ever (design note: The First Minute)
		'firstMinute' => (bool) ( current_user_can( 'edit_posts' ) && ! get_user_meta( get_current_user_id(), '_gogh_first_minute', true ) ),
		'menuStyle' => gogh_menu_style(),
		'restUrl'  => rest_url( 'wp/v2/' . $rest_base . '/' . $post->ID ),
		'mediaUrl' => rest_url( 'wp/v2/media' ),
		'canUpload' => current_user_can( 'upload_files' ),
		'canExp'   => current_user_can( 'upload_files' ) && current_user_can( 'unfiltered_html' ),
		// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only labs toggle
		// Make freeform ships on by default; &gogh-experiments=0 is the kill-switch,
		// bare &gogh-experiments opts into future experimental features.
		'canConvert' => apply_filters( 'gogh_convert_enabled', ! isset( $_GET['gogh-experiments'] ) || '0' !== $_GET['gogh-experiments'] ),
		// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only labs toggle
		'experiments' => isset( $_GET['gogh-test'] ) || ( isset( $_GET['gogh-experiments'] ) && '0' !== $_GET['gogh-experiments'] ),
		// the help bot: gogh's editor embeds it in a small sheet; empty URL
		// (via the filter) removes the ? button entirely
		'helpUrl'  => apply_filters( 'gogh_helper_url', 'https://gogh-helper.jamesmarsland.workers.dev' ),
		'brand'    => get_option( 'gogh_brand', null ) ?: null,
		'activeStyle' => get_option( 'gogh_active_style', '' ),
		'motion'   => get_option( 'gogh_motion', '' ),
		'askAI'    => (bool) ( gogh_ask_key() && gogh_labs_ask() ),
		'labsAsk'  => gogh_labs_ask(),
		'expAI'    => (bool) gogh_ask_key(),
		'canKey'   => current_user_can( 'manage_options' ),
		'typeScale' => (int) get_option( 'gogh_type_scale', 100 ),
		'hasWoo'   => class_exists( 'WooCommerce' ),
		'adminUrl' => admin_url(),
		// block-gated pieces light up the day the block exists (7.1 brings tabs)
		'hasAccordion' => WP_Block_Type_Registry::get_instance()->is_registered( 'core/accordion' ),
		'hasTabs'  => WP_Block_Type_Registry::get_instance()->is_registered( 'core/tabs' ),
		'starters' => array_values( array_map( function ( $m ) {
			return array(
				'slug'        => $m['slug'],
				'name'        => $m['name'],
				'type'        => isset( $m['type'] ) ? $m['type'] : '', // the kind of site — the picker's first line
				'requires'    => isset( $m['requires'] ) ? $m['requires'] : '',
				'description' => isset( $m['description'] ) ? $m['description'] : '',
				'preview'     => isset( $m['preview'] ) ? $m['preview'] : null,
				'pages'       => array_map( function ( $pg ) {
					return array( 'slug' => isset( $pg['slug'] ) ? $pg['slug'] : ( isset( $pg['woo'] ) ? $pg['woo'] : '' ), 'title' => $pg['title'], 'woo' => isset( $pg['woo'] ) ? $pg['woo'] : '' );
				}, $m['pages'] ),
			);
		}, gogh_starters() ) ),
		'pageTemplate'  => get_page_template_slug( $post ) ?: '',
		'pageTemplates' => (function () use ( $post ) {
			$out = array();
			// includes gogh's registered Blank canvas (as 'blank-canvas') on WP 6.7+
			foreach ( (array) wp_get_theme()->get_page_templates( $post ) as $slug => $title ) {
				$out[] = array( 'slug' => (string) $slug, 'title' => (string) $title );
			}
			return $out;
		})(),
		'modified' => get_post_modified_time( 'Y-m-d\TH:i:s', true, $post ),
		'theme'    => get_stylesheet(),
		'themeName' => wp_get_theme()->get( 'Name' ),
		'gsId'     => ( class_exists( 'WP_Theme_JSON_Resolver' ) && current_user_can( 'edit_theme_options' ) )
			? WP_Theme_JSON_Resolver::get_user_global_styles_post_id() : 0,
		'palette'  => array_values( array_map(
			function ( $c ) { return array( 'slug' => $c['slug'] ); },
			(array) ( wp_get_global_settings( array( 'color', 'palette' ) )['theme'] ?? array() )
		) ),
		'nonce'    => wp_create_nonce( 'wp_rest' ),
	) );
} );

/**
 * Live-preview renderer: the core block-renderer returns bare markup with
 * none of the per-instance layout CSS (nav flex rules, container gaps), so
 * header/footer previews looked broken. This renders markup the way a real
 * page does and returns the generated styles + the block stylesheets the
 * markup needs.
 */
add_action( 'rest_api_init', function () {
	register_rest_route( 'gogh/v1', '/render', array(
		'methods'             => 'POST',
		'permission_callback' => function () {
			return current_user_can( 'edit_posts' );
		},
		'callback'            => function ( $req ) {
			$content = (string) $req->get_param( 'content' );
			$html    = do_blocks( $content );
			// BOTH style-engine stores: with the Gutenberg plugin active its
			// namespaced store holds the layout/element rules and core's sits
			// empty — querying only core lost every justify/gap/colour rule
			// ("quite a few header layouts look a little broken")
			$css = '';
			if ( function_exists( 'gutenberg_style_engine_get_stylesheet_from_context' ) ) {
				$css .= (string) gutenberg_style_engine_get_stylesheet_from_context( 'block-supports' );
			}
			if ( function_exists( 'wp_style_engine_get_stylesheet_from_context' ) ) {
				$css .= (string) wp_style_engine_get_stylesheet_from_context( 'block-supports' );
			}
			$hrefs = array();
			$walk  = function ( $blocks ) use ( &$walk, &$hrefs ) {
				foreach ( $blocks as $b ) {
					if ( ! empty( $b['blockName'] ) ) {
						$bt = WP_Block_Type_Registry::get_instance()->get_registered( $b['blockName'] );
						if ( $bt ) {
							foreach ( (array) $bt->style_handles as $h ) {
								if ( $h && wp_style_is( $h, 'registered' ) ) {
									$obj = wp_styles()->registered[ $h ];
									if ( ! empty( $obj->src ) ) {
										$src = ( 0 === strpos( $obj->src, 'http' ) ) ? $obj->src : site_url( $obj->src );
										$hrefs[ $h ] = add_query_arg( 'ver', $obj->ver ? $obj->ver : get_bloginfo( 'version' ), $src );
									}
								}
							}
						}
					}
					if ( ! empty( $b['innerBlocks'] ) ) {
						$walk( $b['innerBlocks'] );
					}
				}
			};
			$walk( parse_blocks( $content ) );
			return array(
				'html'   => $html,
				'css'    => $css,
				'styles' => array_values( $hrefs ),
			);
		},
	) );
} );

/**
 * Editor contexts (post editor, site editor, pattern previews): a gogh
 * section's grid uses cqw units against the .gogh-wrap container. In
 * shrink-to-fit preview wrappers, inline-size containment collapses the wrap
 * to width 0 — every saved section needs the same width floor there.
 */
/**
 * The block editor's canvas rules for gogh sections — one source for the
 * plugin and for the keep-the-blocks helper it leaves behind on deactivation.
 */
function gogh_editor_canvas_css() {
	return
		'.gogh-wrap { min-width: 100%; margin-block: 0 !important; }' .
		'.gogh-section > .wp-block-group { padding: 0 !important; box-sizing: border-box; }' .
		'.gogh-section > * { box-sizing: border-box; }' .
		// video backgrounds: the loop sits under everything; its poster (the
		// section image) shows until it plays, and whenever motion is off
		'.gogh-section > .gogh-bgvideo { position: absolute; inset: 0; z-index: -1; margin: 0 !important; padding: 0 !important; pointer-events: none; overflow: hidden; }' .
		'.gogh-section > .gogh-bgvideo video { width: 100%; height: 100%; object-fit: cover; display: block; }' .
		'.gogh-bgvideo-btn { position: absolute; right: 14px; bottom: 14px; z-index: 60; width: 36px; height: 36px; border-radius: 50%; border: 0; padding: 0; cursor: pointer; background: rgba(15,23,42,0.55); color: #fff; display: grid; place-items: center; opacity: 0.72; transition: opacity 0.2s; }' .
		'.gogh-bgvideo-btn:hover, .gogh-bgvideo-btn:focus-visible { opacity: 1; }' .
		'.gogh-bgvideo-btn svg { width: 14px; height: 14px; display: block; }' .
		'@media (prefers-reduced-motion: reduce) { .gogh-section > .gogh-bgvideo, .gogh-bgvideo-btn { display: none; } }' .
		// the video element: the frame is the design's, the player fills it
		'.gogh-section > .gogh-vid { overflow: hidden; overflow: clip; }' .
		'.gogh-section > .gogh-vid video, .gogh-section > .gogh-vid iframe { width: 100%; height: 100%; object-fit: cover; display: block; border: 0; border-radius: inherit; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper { position: relative; height: 100%; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper::before { content: none !important; padding: 0 !important; }' .
		'.gogh-section > .gogh-vid .wp-block-embed__wrapper iframe { position: absolute; inset: 0; }' .
		// splashes are core blocks wearing gogh classes — without their
		// presentation the editor shows a wall as a stack and a carousel as
		// a pile ("kinda breaking in the gutenberg view"). Same CSS, both rooms.
		gogh_splash_css() .
		// the editor prefixes theme rules with .editor-styles-wrapper, which
		// out-specifies the shared height rule (its height:auto won, so the
		// break showed the photo's full natural height) — re-state the window
		// at editor specificity
		'.editor-styles-wrapper figure.wp-block-image.gogh-splash-break img { height: min(66vh, 640px); }' .
		// buttons: on the canvas they FILL their grid cell (width/height 100%
		// from the section CSS) — in Gutenberg, where container units can
		// resolve oddly (Playground especially), that fill balloons a button
		// into a wrapping blob. Natural pill size in the editor is faithful
		// AND unbreakable.
		'.editor-styles-wrapper .gogh-section .wp-block-button, .editor-styles-wrapper .gogh-section .wp-block-button__link { width: auto !important; height: auto !important; min-height: 0 !important; white-space: nowrap; }';
}
add_action( 'enqueue_block_assets', function () {
	if ( ! is_admin() ) {
		return;
	}
	wp_register_style( 'gogh-editor-base', false, array(), GOGH_VERSION . '-chrome' );
	wp_enqueue_style( 'gogh-editor-base' );
	wp_add_inline_style( 'gogh-editor-base', gogh_editor_canvas_css() );
} );

/**
 * Admin-bar entry point: "Edit with gogh" on any front-end page the user can
 * edit. On a page with no gogh content yet, the editor bootstraps a section.
 */
add_action( 'admin_bar_menu', function ( $bar ) {
	if ( is_admin() || ! is_singular() ) {
		return;
	}
	$post = get_post();
	if ( ! $post || ! current_user_can( 'edit_post', $post->ID ) ) {
		return;
	}
	// two rooms, one landmark: pages open the CANVAS, posts open the
	// WRITING surface — the bar knows which room you are in
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only mode check
	$editing = isset( $_GET['gogh-edit'] ) || isset( $_GET['gogh-write'] );
	$is_post = 'post' === get_post_type( $post );
	$pen  = '<svg class="gogh-ab-ic" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>';
	$pal  = '<svg class="gogh-ab-ic" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><circle cx="13.5" cy="6.5" r="2.1"/><circle cx="18.5" cy="12" r="2.1"/><circle cx="8.5" cy="7.5" r="2.1"/><circle cx="6" cy="13" r="2.1"/><path d="M12 22a10 10 0 1 1 10-10c0 2.2-1.8 3-3.5 3H16a2.5 2.5 0 0 0-2 4c.5.7 0 3-2 3z"/></svg>';
	$done = '<svg class="gogh-ab-ic" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M20 6L9 17l-5-5"/></svg>Done';
	$bar->add_node( array(
		'id'    => 'gogh-edit',
		'title' => $editing ? $done : ( $is_post ? $pen . 'Edit post' : $pal . 'Edit with gogh' ),
		'href'  => $editing
			? ( 'gogh_panel' === get_post_type( $post ) ? home_url( '/' ) : get_permalink( $post ) ) // a panel's only door is back to the site
			: add_query_arg( $is_post ? 'gogh-write' : 'gogh-edit', '1', get_permalink( $post ) ),
	) );
}, 90 );

/**
 * v1 posture: the front-end admin bar shows ONE way to edit — gogh. The
 * native entry points (Site Editor, Edit Page, +New, comments) return with
 * the experiments flag for the curious.
 */
add_action( 'admin_bar_menu', function ( $bar ) {
	if ( is_admin() ) {
		return;
	}
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only mode check
	if ( isset( $_GET['gogh-experiments'] ) || isset( $_GET['gogh-test'] ) ) {
		return;
	}
	// the front-end bar is a CREATION surface, not a dashboard: the WP
	// logo menu, update counters and search live in wp-admin where they
	// belong ("how can we make this nicer / simpler for folks")
	foreach ( array( 'site-editor', 'edit-site', 'customize', 'comments', 'new-content', 'edit', 'wp-logo', 'updates', 'search' ) as $id ) {
		$bar->remove_node( $id );
	}
	// products: a tiny layout menu — pick one of a few fixed layouts,
	// never edit a template
	if ( is_singular( 'product' ) && function_exists( 'gogh_product_layouts' ) ) {
		$pid = get_queried_object_id();
		if ( $pid && current_user_can( 'edit_post', $pid ) ) {
			$current = get_page_template_slug( $pid );
			$layouts = gogh_product_layouts();
			if ( ! isset( $layouts[ $current ] ) ) {
				$current = '';
			}
			$bar->add_node( array(
				'id'    => 'gogh-product-layout',
				'title' => '🎨 Product layout',
			) );
			foreach ( $layouts as $slug => $label ) {
				$bar->add_node( array(
					'id'     => 'gogh-product-layout-' . ( $slug ? $slug : 'classic' ),
					'parent' => 'gogh-product-layout',
					'title'  => ( $slug === $current ? '✓ ' : '' ) . $label,
					'href'   => wp_nonce_url( admin_url( 'admin-post.php?action=gogh_product_layout&id=' . $pid . '&layout=' . rawurlencode( $slug ) ), 'gogh_product_layout_' . $pid ),
				) );
			}
			// one more click stamps the catalogue — individual products can
			// still be changed afterwards, one at a time
			$current_label = preg_replace( '/\s+—.*$/u', '', $layouts[ $current ] );
			// the layouts are one kind of thing; what follows is another — a
			// secondary group sets them apart (James: 'any elegant way of
			// differentiating the show option here? its kinda a different thing')
			$bar->add_group( array(
				'id'     => 'gogh-product-layout-extras',
				'parent' => 'gogh-product-layout',
				'meta'   => array( 'class' => 'ab-sub-secondary' ),
			) );
			$bar->add_node( array(
				'id'     => 'gogh-product-layout-all',
				'parent' => 'gogh-product-layout-extras',
				'title'  => sprintf( __( 'Apply “%s” to all products', 'gogh-editor' ), $current_label ),
				'href'   => wp_nonce_url( admin_url( 'admin-post.php?action=gogh_product_layout_all&id=' . $pid ), 'gogh_product_layout_all' ),
			) );
			$related_on = '0' !== (string) get_option( 'gogh_product_related', '1' );
			$bar->add_node( array(
				'id'     => 'gogh-product-related',
				'parent' => 'gogh-product-layout-extras',
				// a verb, not a tick: it says what the click will do
				'title'  => $related_on ? __( 'Hide “You might also like”', 'gogh-editor' ) : __( 'Show “You might also like”', 'gogh-editor' ),
				'href'   => wp_nonce_url( admin_url( 'admin-post.php?action=gogh_product_related&back=' . rawurlencode( get_permalink( $pid ) ) ), 'gogh_product_related' ),
			) );
		}
	}
	// posts: the same tiny menu for the reading looks (James: 'i really
	// like the way you have product layout in the admin toolbar - we should
	// do that for our blog layout options')
	if ( is_singular( 'post' ) ) {
		$post_id = get_queried_object_id();
		if ( $post_id && current_user_can( 'edit_post', $post_id ) ) {
			$looks   = gogh_post_layouts();
			$cur_look = (string) get_post_meta( $post_id, '_gogh_post_style', true );
			if ( ! isset( $looks[ $cur_look ] ) ) {
				$cur_look = '';
			}
			$bar->add_node( array(
				'id'    => 'gogh-post-layout',
				'title' => '🎨 Post layout',
			) );
			foreach ( $looks as $slug => $label ) {
				$bar->add_node( array(
					'id'     => 'gogh-post-layout-' . ( $slug ? $slug : 'theme' ),
					'parent' => 'gogh-post-layout',
					'title'  => ( $slug === $cur_look ? '✓ ' : '' ) . $label,
					'href'   => wp_nonce_url( admin_url( 'admin-post.php?action=gogh_post_layout&id=' . $post_id . '&layout=' . rawurlencode( $slug ) ), 'gogh_post_layout_' . $post_id ),
				) );
			}
			$cur_label = preg_replace( '/\s+—.*$/u', '', $looks[ $cur_look ] );
			$bar->add_group( array(
				'id'     => 'gogh-post-layout-extras',
				'parent' => 'gogh-post-layout',
				'meta'   => array( 'class' => 'ab-sub-secondary' ),
			) );
			$bar->add_node( array(
				'id'     => 'gogh-post-layout-all',
				'parent' => 'gogh-post-layout-extras',
				'title'  => sprintf( __( 'Apply “%s” to all posts', 'gogh-editor' ), $cur_label ),
				'href'   => wp_nonce_url( admin_url( 'admin-post.php?action=gogh_post_layout_all&id=' . $post_id ), 'gogh_post_layout_all' ),
			) );
		}
	}
	// the blog page: the Blog style as the same tiny menu (the floating pill
	// keeps its hover auditions; the bar is the door people already know)
	if ( ( is_home() || is_category() || is_tag() || is_author() ) && current_user_can( 'edit_theme_options' ) ) {
		$blog_cur   = get_option( 'gogh_blog_style', '' );
		$blog_looks = array(
			''       => __( 'Default — the theme\'s own list', 'gogh-editor' ),
			'list'   => __( 'List — tidied flow, hairlines, dates right', 'gogh-editor' ),
			'cards'  => __( 'Cards — image-led grid', 'gogh-editor' ),
			'cover'  => __( 'Cover — newest post huge, the rest in a grid', 'gogh-editor' ),
			'ledger' => __( 'Ledger — dense editorial index', 'gogh-editor' ),
		);
		if ( ! isset( $blog_looks[ $blog_cur ] ) ) {
			$blog_cur = '';
		}
		$bar->add_node( array(
			'id'    => 'gogh-blog-layout',
			'title' => '🎨 Blog layout',
		) );
		foreach ( $blog_looks as $slug => $label ) {
			$bar->add_node( array(
				'id'     => 'gogh-blog-layout-' . ( $slug ? $slug : 'theme' ),
				'parent' => 'gogh-blog-layout',
				'title'  => ( $slug === $blog_cur ? '✓ ' : '' ) . $label,
				'href'   => wp_nonce_url( admin_url( 'admin-post.php?action=gogh_blog_layout&layout=' . rawurlencode( $slug ) . '&back=' . rawurlencode( home_url( add_query_arg( array() ) ) ) ), 'gogh_blog_layout' ),
			) );
		}
	}
	// the shop page and category pages: their looks, from the same door
	$shop_kind = function_exists( 'gogh_shop_look_kind' ) ? gogh_shop_look_kind() : '';
	if ( $shop_kind && current_user_can( 'edit_theme_options' ) ) {
		$shop_cur   = gogh_shop_look_active( $shop_kind );
		$shop_looks = gogh_shop_looks();
		$shop_id    = 'gogh-' . $shop_kind . '-layout';
		$bar->add_node( array(
			'id'    => $shop_id,
			'title' => 'shop' === $shop_kind ? '🎨 Shop layout' : '🎨 Category layout',
		) );
		$shop_term = 'category' === $shop_kind ? (int) get_queried_object_id() : 0;
		$shop_back = rawurlencode( home_url( add_query_arg( array() ) ) );
		foreach ( $shop_looks as $slug => $label ) {
			$bar->add_node( array(
				'id'     => $shop_id . '-' . ( $slug ? $slug : 'classic' ),
				'parent' => $shop_id,
				'title'  => ( $slug === $shop_cur ? '✓ ' : '' ) . $label,
				'href'   => wp_nonce_url( admin_url( 'admin-post.php?action=gogh_shop_layout&kind=' . $shop_kind . '&layout=' . rawurlencode( $slug ) . ( $shop_term ? '&term=' . $shop_term : '' ) . '&back=' . $shop_back ), 'gogh_shop_layout' ),
			) );
		}
		if ( $shop_term ) {
			// this category chose above; one more click stamps every category
			$shop_cur_label = preg_replace( '/\s+—.*$/u', '', $shop_looks[ $shop_cur ] );
			$bar->add_group( array(
				'id'     => $shop_id . '-extras',
				'parent' => $shop_id,
				'meta'   => array( 'class' => 'ab-sub-secondary' ),
			) );
			$bar->add_node( array(
				'id'     => $shop_id . '-all',
				'parent' => $shop_id . '-extras',
				'title'  => sprintf( __( 'Apply “%s” to all categories', 'gogh-editor' ), $shop_cur_label ),
				'href'   => wp_nonce_url( admin_url( 'admin-post.php?action=gogh_shop_layout&kind=category&all=1&layout=' . rawurlencode( $shop_cur ) . '&back=' . $shop_back ), 'gogh_shop_layout' ),
			) );
		}
	}
	// one thing beginners DO need from the old menu: a new page — and it
	// goes straight into gogh
	// which room is this? posts and the blog index are the WRITING room;
	// everything else is the design studio — the bar only offers the verbs
	// that belong to the room ("this is really the site designer")
	$has_blog     = 'posts' === get_option( 'show_on_front' ) || (int) get_option( 'page_for_posts' ) > 0;
	$plus         = '<svg class="gogh-ab-ic" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>';
	$pen2         = '<svg class="gogh-ab-ic" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>';
	$new_page = array(
		'id'    => 'gogh-new-page',
		'title' => $plus . 'New page',
		// the front door: blank draft, canvas, first minute — the nameplate
		// and the publish gate own naming now (the old name-first modal and
		// its instantly-published empty page retired with them)
		'href'  => admin_url( 'post-new.php?post_type=page' ),
	);
	$new_post = array(
		'id'    => 'gogh-write',
		'title' => $pen2 . 'New post',
		'href'  => add_query_arg( 'gogh-new-post', '1', home_url( '/' ) ),
		'meta'  => array( 'title' => 'A clean canvas and space to think' ),
	);
	// one door per room: on a SINGLE post the door is Edit post — New post
	// rides top-level only on the blog index, where there is nothing to
	// edit ("we need to remove new post from here"); it stays under the
	// site-name menu everywhere as the safety net
	if ( is_home() && $has_blog && current_user_can( 'edit_posts' ) ) {
		$bar->add_node( $new_post );
	}
	// New page rides only in the site menu now ("maybe lets remove this") —
	// the bar on a page keeps a single door: Edit with gogh
	// the safety net: both creations live quietly under the site name, so
	// nothing is ever unreachable from the wrong room
	if ( current_user_can( 'publish_pages' ) ) {
		$bar->add_node( array_merge( $new_page, array( 'id' => 'gogh-new-page-menu', 'parent' => 'site-name' ) ) );
	}
	if ( $has_blog && current_user_can( 'edit_posts' ) ) {
		$bar->add_node( array_merge( $new_post, array( 'id' => 'gogh-write-menu', 'parent' => 'site-name' ) ) );
	}
	// wp-admin plumbing leaves the site menu — Dashboard stays as the
	// escape hatch; Plugins and Themes are not site-making
	foreach ( array( 'plugins', 'themes', 'widgets', 'menus', 'appearance' ) as $noise ) {
		$bar->remove_node( $noise );
	}
	// the edit/exit landmark closes the cluster: re-adding sends it last
	$edit_node = $bar->get_node( 'gogh-edit' );
	if ( $edit_node ) {
		$bar->remove_node( 'gogh-edit' );
		$bar->add_node( (array) $edit_node );
	}
}, 999 );

/**
 * EXPERIMENT (&gogh-experiments): "+ New → Page" from the front-end admin
 * bar creates the page and lands straight in gogh, not the block editor.
 */
add_action( 'admin_bar_menu', function ( $bar ) {
	if ( is_admin() ) {
		return;
	}
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- read-only mode check
	if ( ! ( isset( $_GET['gogh-experiments'] ) || isset( $_GET['gogh-test'] ) ) ) {
		return;
	}
	$node = $bar->get_node( 'new-page' );
	if ( $node ) {
		$node->href = admin_url( 'post-new.php?post_type=page' );
		$bar->add_node( (array) $node );
	}
}, 1000 );
/**
 * No page title by default — for EVERY new page, however it's created
 * (gogh's New page, wp-admin, REST). A freeform canvas carries its own
 * title typography; the theme's auto title above it just duplicates
 * ('should no page title be the default with gogh?'). Page style brings
 * it back per page; pages that already chose a template are untouched.
 */
add_action( 'wp_insert_post', function ( $post_id, $post, $update ) {
	if ( $update || 'page' !== $post->post_type ) {
		return;
	}
	if ( ! get_page_template_slug( $post_id ) ) {
		update_post_meta( $post_id, '_wp_page_template', 'page-no-title' );
	}
}, 10, 3 );

/**
 * The editor-only rules a gogh section needs inside the block editor —
 * the inner-blocks wrapper flattened into the grid, full canvas width, no
 * appenders in decorative groups. One source for the plugin and for the
 * keep-the-blocks helper it leaves behind on deactivation.
 */
function gogh_editor_flatten_css() {
	// Editor-only adjustments:
	// 1. The group block's inner-blocks wrappers would break the grid —
	//    promote grandchildren into the grid with display:contents.
	// 2. Hide the leading Custom HTML block that carries the style + model.
	return "\n"
		. '.gogh-section > .block-editor-inner-blocks,'
		. '.gogh-section > div:not([class]),'
		// empty groups (gogh boxes/shapes) get an extra CLASS-LESS wrapper from
		// the editor — promote it too, or the anonymous div becomes the grid
		// item: auto-placed, zero-height, shape invisible
		. '.gogh-section .block-editor-block-list__layout > div:not([class]),'
		. '.gogh-section .block-editor-inner-blocks > .block-editor-block-list__layout { display: contents; }' . "\n"
		. '.is-root-container > [data-type="core/html"]:first-child { display: none; }' . "\n"
		// gogh/section blocks span the full editor canvas, like the front end
		. '.editor-styles-wrapper [data-type="gogh/section"],'
		. '.editor-styles-wrapper .wp-block:has(> .wp-block-gogh-section) {'
		. ' max-width: none !important; width: auto;'
		// kill the editor's block-gap margins so sections sit flush, like the front end
		. ' margin-block: 0 !important;'
		. ' margin-left: calc(-1 * var(--wp--style--root--padding-left, 0px)) !important;'
		. ' margin-right: calc(-1 * var(--wp--style--root--padding-right, 0px)) !important; }' . "\n"
		. '.gogh-wrap { margin-block: 0 !important; }' . "\n"
		// empty image/decoration groups: suppress Gutenberg's layout variation
		// picker and appender so the div renders with its gogh background
		. '.gogh-section .block-editor-block-variation-picker,'
		. '.gogh-section .wp-block-group__placeholder > .components-placeholder,'
		. '.gogh-section .block-list-appender { display: none !important; }';
}
/**
 * Backend parity: inject the page's own generated gogh CSS into the block
 * editor iframe so the editor canvas renders the section like the front end.
 */
add_filter( 'block_editor_settings_all', function ( $settings, $context ) {
	$post = isset( $context->post ) ? $context->post : null;
	if ( ! $post || false === strpos( $post->post_content, 'gogh-section' ) ) {
		return $settings;
	}
	if ( ! preg_match_all( '/<style class="gogh-style">(.*?)<\/style>/s', $post->post_content, $m ) ) {
		return $settings;
	}

	$css = implode( "\n", $m[1] );

	$css .= gogh_editor_flatten_css();
	$settings['styles'][] = array( 'css' => $css );
	return $settings;
}, 10, 2 );
